(1590723, 'Laut Bercerita', 'Drama', 133, 'NR', 'Set during the volatile final months of Indonesia’s New Order regime, the narrative chronicles a young student activist''s perilous commitment to pro-democracy underground movements and his family''s subsequent, grueling quest for justice following his forced disappearance.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/8FqJSSMPaKJzqq2VVxVmdHUozLY.jpg', 'https://image.tmdb.org/t/p/w1280/dibjzvhuz4FiF0Af9BkcMDHRSCD.jpg', 8, 'Crx2f2CvUpc', '2026-10-29', 4.42, 3, 'tt39073337', null, null, 'TV-MA', 'Drama, Sejarah', 'Yosep Anggi Noen', 'Leila S. Chudori, Yosep Anggi Noen', 'Gita Fara, Budi Setyarso, Leila S. Chudori', 'Pal8 Pictures, Visual Media Studio, Jagartha, Lynx Films', '[{"name":"Reza Rahadian","character":"Biru Laut"},{"name":"Yunita Siregar","character":"Asmara Jati"},{"name":"Christine Hakim","character":"Mrs. Ratih Wibisana / Laut''s Mother"},{"name":"Arswendy Bening Swara","character":"Mr. Arya Wibisana / Laut''s Father"},{"name":"Eva Celia","character":"Ratih Anjani"},{"name":"Dian Sastrowardoyo","character":"Kasih Kinanti"},{"name":"Yoga Pratama","character":"Arifin Bramantyo"},{"name":"Ben Nugroho","character":"Alex Perazon"},{"name":"Kevin Julio","character":"Daniel Tumbuan"},{"name":"Dewa Dayana","character":"Sunu Dyantoro"}]'::jsonb, '17+', null),
(1567791, 'Munafik: Melawan Iblis', 'Kengerian', 103, 'NR', 'Di perjalanan pulang setelah membantu sebuah keluarga mengusir Iblis di tubuh anak mereka, Adam (Arya Saloka) seorang pengajar agama sekaligus praktisi ruqyah mengalami kecelakaan maut yang membuatnya kehilangan Aini, istrinya. Sejak saat itu ia berhenti melakukan ruqyah dan hidup dalam kesedihan berkepanjangan. Sampai suatu hari, ia diminta Anwar (Dimas Aditya) menyelamatkan Fitri (Acha Septriasa) seorang perawat sekaligus putri dari Mansur (Donny Damara), figur yang dihormati di desa tempat Adam tinggal. Adam yang awalnya menolak menemukan alasan untuk kembali melakukan ruqyah karena mengingat pesan mendiang istrinya. Namun, seiring waktu ia menemukan ada rahasia gelap di balik terror gaib yang menimpa Fitri.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/sXrzWnoA14DWSMUqCEY0o0CTxPg.jpg', 'https://image.tmdb.org/t/p/w1280/9W2ZK1AzTE8WIw10gnzDzVLzXEc.jpg', 6.8, 'gkij9R9EV5o', '2026-09-03', 4.182, 2, 'tt38782610', 6.8, 13, 'TV-MA', 'Kengerian, Misteri, Cerita Seru', 'Guntur Soeharjanto', 'M. Ali Ghifari', 'Oswin Bonifanz, Ayu Amirrol, Syamin Yusof', 'Unlimited Production, Skop Productions Sdn. Bhd., AZ Films, Komet Productions', '[{"name":"Arya Saloka","character":"Ustadz Adam"},{"name":"Acha Septriasa","character":"Fitri"},{"name":"Dimas Aditya","character":"Ustadz Anwar"},{"name":"Muhammad Faqih Alaydrus","character":"Amir"},{"name":"Donny Damara","character":"H. Mansyur"},{"name":"Nova Eliza","character":"Hj. Zulfa"},{"name":"Izabel Jahja","character":"Umi Fitri"},{"name":"Widi Dwinanda","character":"Aini"},{"name":"Elvira Devinamira","character":"Hanifah"},{"name":"Oce Permatasari","character":"ART H. Mansyur"}]'::jsonb, '17+', null),
(1601709, 'Bapakmu Kiper', 'Komedi', 90, 'NR', 'The story follows an 18-year-old named Ronaldhino Sujatmiko—known as Dino—who harbors anger toward his father, Warto. Warto is a former local soccer star and soccer gambler whom Dino believes is responsible for his mother’s death. Dino’s chance to leave his village comes through the Tarkam Super Cup, a soccer talent search tournament. The conflict comes to a head when Dino’s main team is taken over by another party just before the final. This situation forces his father, Warto, to step in and form a new team made up of veteran players, despite all the limitations they face.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/e91DcxPpBfjAuVf67rP8zVFEjBi.jpg', 'https://image.tmdb.org/t/p/w1280/6dporxDetmS1eYrmIbpZfLdX81D.jpg', 5, 'zDv6_dfI7F8', '2026-09-03', 3.31, 1, 'tt43635381', 2.3, 791, null, 'Komedi, Drama', 'Ody C. Harahap', 'Titien Wattimena, Aaron Hart', 'Patricia Gunadi', 'Entelekey Media, Entelekey Sinema', '[{"name":"Fedi Nuril","character":"Warto"},{"name":"Ali Fikry","character":"Ronaldhino Sujatmiko / Dino"},{"name":"Vidi Bule","character":"Adam Hansip"},{"name":"Tanta Ginting","character":"Ngatiman Bengkel"},{"name":"Augie Fantinus","character":"Hendra"},{"name":"Yanda Djaitov","character":"Supar Kuli"},{"name":"Chrismanto Eka Prastio","character":"Yono Copet"},{"name":"Didi Murs Mahmud","character":"David Bekam"},{"name":"Neysa Chandria","character":"Kristin"},{"name":"M. N. Qomaruddin","character":"Yadi Dukun"}]'::jsonb, '13+', null),
(1716222, 'Paket Santet', 'Kengerian', 98, 'NR', 'Sebuah paket tiba di depan pintu. Tidak ada nama pengirim. Tidak ada alasan mengapa paket itu ditujukan kepada mereka. Namun, sejak paket itu dibuka, hidup penerimanya langsung berubah jadi mimpi buruk. Satu per satu nyawa menjadi taruhan. Kini, pertanyaannya bukan lagi bagaimana cara menghindari paket tersebut, melainkan bagaimana cara terhindar dari kutukan setelah menerimanya.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ooeIRaAM9N02d8Z4eXPKE5BlBMM.jpg', 'https://image.tmdb.org/t/p/w1280/wP70ACOajhix1Ko845sBxUT9vkG.jpg', 6, 'iAAtCbIbGfU', '2026-08-27', 3.189, 2, 'tt42697813', 7.7, 7, null, 'Kengerian, Misteri, Cerita Seru', 'Dinna Jasanti', 'Obe Karel, Titien Wattimena, Ambaridzki Ramadhantyo', 'Shanty Harmayn, Aoura Lovenson Chandra, Tanya Yuson', 'BASE Entertainment, PK Films, Applause Entertainment, ARENDI', '[{"name":"Fatih Unru","character":"Deva"},{"name":"Yasamin Jasem","character":"Bella"},{"name":"Gabriella Ekaputri","character":"Celia"},{"name":"Fadly Faisal","character":"Ale"},{"name":"Fiki Naki","character":"Firza"},{"name":"Farandika","character":"Glen"},{"name":"Azela Putri","character":"Kiki"},{"name":"Vonny Anggraini","character":"Deva''s Mother"},{"name":"Aida Nurmala","character":"Bella''s Mother"},{"name":"Moh Iqbal Sulaiman","character":"Rizal"}]'::jsonb, '13+', null),
(1541802, 'Operasi Pesta Copet', 'Komedi', 113, 'NR', 'In a desperate act to get quick money, Ijal and friends embark on a high-stakes operation: pickpocketing at Indonesia''s biggest music festival, Pestapora.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/q6jhaPlAnzNFuvPDbDXBDbavIXE.jpg', 'https://image.tmdb.org/t/p/w1280/zj0UjmCotGH7BnMRbKEr5ZxQUZE.jpg', 8, 'OB6e0VrfUyQ', '2026-08-27', 2.772, 2, 'tt38201949', 7.9, 71, 'TV-14', 'Komedi, Kejahatan, Musik', 'Edy Khemod', 'Rino Sarjono, Edy Khemod', 'Ernest Prakasa, Dipa Andika, Iqbaal Ramadhan, James Erlangga', 'Imajinari, Angin Segar Production, Boss Creator, Legacy Pictures', '[{"name":"Iqbaal Ramadhan","character":"Ijal"},{"name":"Kristo Immanuel","character":"Adut"},{"name":"Zulfa Maharani","character":"Tia"},{"name":"Kawai Labiba","character":"Melodi"},{"name":"Fauzan Lubis","character":"Silet"},{"name":"Azizah Hanum","character":"Hanum"},{"name":"Ardit Erwandha","character":"Maman"},{"name":"Kiki Narendra","character":"Toni"},{"name":"Mal Jupri","character":"Atot"},{"name":"Rio Dumatubun","character":"Opik"}]'::jsonb, '13+', null),
(1420041, 'Memburu Pemangsa', 'Aksi', 115, 'NR', 'Sekelompok jurnalis sedang menginvestigasi kasus pembunuhan anak, namun tiap petunjuk justru membuka teror baru, dan mencari tahu terlalu dalam membuat mereka dalam bahaya yang tak mereka pahami.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/iF8QBPgMvrqv1HEIPH2eIh6Z4eQ.jpg', 'https://image.tmdb.org/t/p/w1280/44fTEcaEtk7PmGFPZUSQEsThGGF.jpg', 5.7, 'PceQZIf1k70', '2026-09-24', 3.209, 3, 'tt35486488', null, null, null, 'Aksi, Kejahatan, Kengerian', 'Umay Shahab', 'Rezy Junio, Umay Shahab, Reka Wijaya', 'Imam Salimy', 'Sinemaku Pictures, Legacy Pictures, NextG Investment, Applause Entertainment', '[{"name":"Laura Basuki","character":"Agnes"},{"name":"Prilly Latuconsina","character":"Cia"},{"name":"Yasamin Jasem","character":"Anya"},{"name":"Taskya Namya","character":"Brina"},{"name":"Teuku Rifnu Wikana","character":"The Predator"},{"name":"Septian Dwi Cahyo","character":"Dudi"},{"name":"Andri Mashadi","character":"Petra"},{"name":"Norman R. Akyuwen","character":"Lara"},{"name":"Jordan Omar","character":"Pandu"},{"name":"Javinada Qeila","character":"Cindy"}]'::jsonb, '17+', null),
(1378262, 'Lobang Buaya, 309 Hari Sebelum Tragedi Berdarah', 'Kejahatan', 99, 'NR', 'When a spate of gruesome killings rocks the countryside in East Jakarta, army officer Soegeng is tasked with clearing up rumours about the military’s involvement. Soegeng’s investigation, however, confronts him with the foundations of corruption – a truth too close for comfort.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/eWgVIP4Z3BkgdOSbkO6Sr46ffyt.jpg', 'https://image.tmdb.org/t/p/w1280/mOLtKIvXd1SmobFAaANA1MOuoDk.jpg', 6, 'bxLqGxvjiYQ', '2026-10-01', 2.419, 1, 'tt34548453', null, null, null, 'Kejahatan, Kengerian, Misteri, Cerita Seru', 'Hanung Bramantyo', 'Haqi Achmad, Hanung Bramantyo', 'Shierly Kosasih', 'Adhya Pictures, Dapur Film, EST Studios, JERRYGOOD Company Inc.', '[{"name":"Baskara Mahendra","character":"Soegeng"},{"name":"Carissa Perusset","character":"Arum Wangi"},{"name":"Khiva Iskak","character":"Suradji"},{"name":"Anya Zen","character":"Ningsih"},{"name":"Mathias Muchus","character":"Sukarya / The Great Lord"},{"name":"Abah Qomar","character":"Kyai Soleman"},{"name":"Royhan Hidayat","character":"Supri"},{"name":"\"Tuwek\" Dinmas Herjuna","character":"Suripno"},{"name":"Kurniawan Hasnajaya","character":"Supono"},{"name":"Ari Purnomo","character":"Sumanto"}]'::jsonb, '17+', null),
(1716269, 'Rumah Singgah', 'Drama', 113, 'NR', 'Karla, a talented young runner diagnosed with bone cancer, receives treatment at a halfway house. There, she learns to accept reality through the support of the residents and bu Andin, while together they realize their ultimate dream.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/m3N5NcK4rE7GOaWAuefr0xbncpX.jpg', 'https://image.tmdb.org/t/p/w1280/4WkrOK5DkGO0QIdggzejKoBeDOr.jpg', 7.6, 'B-LKbBHGWa4', '2026-08-27', 2.904, 4, 'tt39060117', null, null, null, 'Drama', 'Dyan Sunu Prastowo', 'Raditya Kurnia, Celvin Jaya Hadi', 'Hans Andreas', 'Mandela Pictures, Limelight Pictures, Senara Films', '[{"name":"Adhisty Zara","character":"Karla"},{"name":"Devano Danendra","character":"Luki"},{"name":"Ciccio Manassero","character":"Toni"},{"name":"Messi Gusti","character":"Pika"},{"name":"Aming Sugandhi","character":"Mang Didu"},{"name":"Dewi Irawan","character":"Bu Andin"},{"name":"Alex Abbad","character":"Ardi"},{"name":"Marthino Lio","character":"Pras"},{"name":"Agnes Naomi","character":"Mayang"},{"name":"Rena Haura","character":"Gadis"}]'::jsonb, 'SU', null),
(1565598, 'Dan Bandung', 'Drama', 120, 'NR', 'Basil, a working-studying Fine Arts student, falls in love with Elma after meeting her at a Persib soccer match. He creates a t-shirt featuring her image that goes viral, leading to their acquaintance and eventual dating. However, their relationship faces opposition from Elma''s father, forcing Basil to fight for his love amidst various obstacles.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/fSK0eQ6toOrjTpRtqB1WoqN50cc.jpg', 'https://image.tmdb.org/t/p/w1280/3W9ipa59TAws4nAbaP0SdksktJG.jpg', 6.2, 'l5GGKpxcCYc', '2026-08-20', 3.264, 3, 'tt43602769', 7.5, 14, null, 'Drama, Percintaan', 'Rudi Soedjarwo', 'Titien Wattimena, Pidi Baiq', 'Titin Suryani', 'Verona Films, TIX ID', '[{"name":"Samo Rafael","character":"Basil"},{"name":"Shanna Shannon","character":"Elma"},{"name":"Keisya Levronka","character":"Susi"},{"name":"Paul Aro","character":"Bimo"},{"name":"Razan Zu","character":"Doni"},{"name":"Theo Supple","character":"Uu"},{"name":"Jenny Zhang","character":"Andini"},{"name":"Donny Damara","character":"Kertawijaya"},{"name":"Arswendy Bening Swara","character":"Nugraha"},{"name":"Nugie","character":"Mang Yadi"}]'::jsonb, '13+', null),
(1739312, 'Warga Rusun 609', 'Komedi', 103, 'NR', 'The idiosyncratic tenants of a public housing complex must form a unified front to resist an aggressive municipal demolition plan, all while covertly managing a severe supernatural haunting inside Room 609 by an aggrieved spirit demanding an unfulfilled romantic vow.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/d9k5T523oJjvNBEduSIuBJ6rvpR.jpg', 'https://image.tmdb.org/t/p/w1280/7uQrqaL25mCJXCCSYDBPRHfxGEu.jpg', 5, 'HK3qtX_S0FQ', '2026-10-01', 2.796, 2, 'tt43720940', 6.8, 16, null, 'Komedi, Kengerian', 'Herwin Novianto', 'Upi Avianto', 'Gope T. Samtani', 'Rapi Films, Sky Media, Legacy Pictures, Vortera Studios', '[{"name":"Ranty Maria","character":"Bunga"},{"name":"Morgan Oey","character":"Arka Susanto"},{"name":"Gita Bhebhita","character":"Damai Sejahtera boru Sembiring"},{"name":"Tanta Ginting","character":"Terang Tarigan"},{"name":"Sarah Sechan","character":"Wati"},{"name":"Dimas Danang","character":"Wira"},{"name":"Galabby Thahira","character":"Nurjanah"},{"name":"Riyuka Bunga","character":"Tuti"},{"name":"Aming Sugandhi","character":"Anjay"},{"name":"Yono Bakrie","character":"Gugum"}]'::jsonb, '13+', null),
(1727650, 'Ibadah & Cinta', 'Drama', 116, 'NR', 'A secular young man raised in Australia undergoes a profound spiritual awakening after falling in love with the daughter of a prominent Islamic scholar, only for their matrimonial aspirations to be jeopardized by a pre-arranged betrothal mandated by her traditionalist family.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/cQlIFMvnAAUH9MZ7l1UkSD13ddB.jpg', 'https://image.tmdb.org/t/p/w1280/v9pNRRWO5gZ1ybKxmKVeL7yTgSD.jpg', 7, '_k-qM7bnIbg', '2026-09-24', 2.734, 1, 'tt40201329', null, null, null, 'Drama, Percintaan', 'Jastis Arimba', 'Ifan Adriansyah Ismail, Jastis Arimba', 'Rendy Gunawan, Arismuda Irawan', 'Sinemata, Multi Buana Kreasindo', '[{"name":"Achmad Megantara","character":"Rico"},{"name":"Indah Permatasari","character":"Santun"},{"name":"Adhin Abdul Hakim","character":"Ganda"},{"name":"Berlliana Lovell","character":"Nissa"},{"name":"Mathias Muchus","character":"Kyai Umar"},{"name":"Elma Theana","character":"Khadijah"},{"name":"Jamie Aditya","character":"Rico''s Dad"},{"name":"Sita Permata Sari","character":"Desi"},{"name":"Nadzira Shafa","character":"Zira"},{"name":"Stevan Rizky","character":"Ustad Salman"}]'::jsonb, '13+', null),
(1727665, 'Akal Imitasi', 'Drama', 98, 'NR', 'Set in the year 2029, the story focuses on an AI-based system called PIKO in schools, and how this technology widens the gap and leads to the loss of the true essence of learning.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/lxnXXcHffRvRo3mCKJYqPQCkpfz.jpg', 'https://image.tmdb.org/t/p/w1280/pQoz9HcCaiKIu8wFFuGh1X3M7My.jpg', 4, '6zT_Zjjqj0Y', '2026-09-17', 2.65, 1, 'tt43704631', null, null, null, 'Drama, Cerita Fiksi', 'Zhaddam Aldhy Nurdin', 'Chairul Rijal', 'Suherman Suhari', 'DL Entertainment', '[{"name":"Zaskia Alya Kyla","character":"Ika"},{"name":"Tika Bravani","character":"Teacher Lilis"},{"name":"Teuku Rifnu Wikana","character":"Teacher Damar"},{"name":"Rance Allen Wright","character":"Rafi"},{"name":"Arziqy Herdi Pratama","character":"Neo"},{"name":"Kaysha Varisha Wahab","character":"Alya"},{"name":"Ahmad Hafidz Makkaarennu","character":"Daniel"},{"name":"Mohammad Rannan Tristan","character":"Reyhan"},{"name":"Diva Pancarani","character":"Dewi"},{"name":"Wahyu Mellong","character":"Kevin"}]'::jsonb, 'SU', null),
(1622688, 'Baby Udon', 'Drama', 115, 'NR', 'Fanny Kondoh, a young Indonesian woman, falls in love with Hajime Kondoh, a Japanese man who comes to Indonesia for work. After getting married, Fanny and Hajime begin building a life together, embracing both its joys and challenges. As they struggle to fulfill their dream of having a child, they are faced with one heartbreaking trial after another, testing the strength of their love, especially when Hajime is diagnosed with cancer.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ge7LZLK3B64CQohvPPnEM38eGjq.jpg', 'https://image.tmdb.org/t/p/w1280/8ojEAapPIzHgIlOgZ8KOud1B9Y5.jpg', 6, 'rw4ioWmttvA', '2026-09-03', 2.537, 2, null, null, null, null, 'Drama, Percintaan', 'Fajar Bustomi', 'Oka Aurora, Christina Cindy', 'Marcella Daryanani, Olivia Allan Sumargo', 'Sumargo Film, Lyto Pictures', '[{"name":"Caitlin Halderman","character":"Fanny Kondoh"},{"name":"Denny Sumargo","character":"Hajime Kondoh"},{"name":"Vonny Anggraini","character":"Ibu Retno"},{"name":"Naufal Samudra","character":"Toni"},{"name":"Ayya Renita","character":"Susi"},{"name":"Putri Ayudya","character":"Dr. Shintia"},{"name":"Alfie Alfandy","character":"Dr. Richard"},{"name":"Miyu Okazaki","character":"Yumiko"},{"name":"Hiroaki Kato","character":"Hiro"},{"name":"Nobuyuki Suzuki","character":"Suzuki"}]'::jsonb, '13+', null),
(1716810, 'Autopsy: Dead Body Can Talk', 'Cerita Seru', 115, 'NR', 'Dr. Sumy Hastry—a sharp, calm, and experienced forensic is intertwined with intuition and supernatural phenomena that are part of her long journey.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/jI82Y6SCWUSUL2aw1Uokomd1Tlu.jpg', 'https://image.tmdb.org/t/p/w1280/l3D5HQv73YCenXfQ3ClXPcEJrRR.jpg', 4, 'LZrKHylvBzk', '2026-09-03', 2.251, 2, null, null, null, null, 'Cerita Seru, Misteri', 'Ouzan Ruz', 'M. Nurman Wardi', 'Marsa Moesa, Fariz Stanzah', 'Karya Kreatif Utama', '[{"name":"Masayu Anastasia","character":"dr. Sumy Hastry"},{"name":"Teuku Rifnu Wikana","character":"Rendra"},{"name":"Ge Pamungkas","character":"Mojo"},{"name":"Riyuka Bunga","character":"Yatna"},{"name":"Samuel Rizal","character":"Hary"},{"name":"Indra Frimawan","character":"Warji"},{"name":"Abdurrahman Arif","character":"Yanto"},{"name":"Nagra Pakusadewo","character":"Aldi"},{"name":"Zidni Hakim","character":""},{"name":"Andrew Suleiman","character":"Choi"}]'::jsonb, '17+', null),
(1589665, 'Kuasa Gelap: Perjanjian Darah', 'Kengerian', 117, 'NR', 'Following a catastrophic, failed ritual in a remote Indonesian province, two Catholic exorcists are deployed to confront a devastatingly powerful ancient entity unleashed by an ancestral pact for illicit wealth.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/pnr5cn7TJlGw6yUMgbCtDkGRLuQ.jpg', 'https://image.tmdb.org/t/p/w1280/yPeEsPDAsTrYpBNEwaO4xziacuI.jpg', 6.7, 'DKaO7xm7tpo', '2026-10-08', 2.488, 3, 'tt41272731', null, null, 'TV-MA', 'Kengerian', 'Rizal Mantovani', 'Robert Ronny, Andri Cahyadi', 'Robert Ronny, Prima Taufik', 'Paragon Pictures, Ideosource Entertainment, Virtuelines Entertainment, Legacy Pictures', '[{"name":"Jerome Kurnia","character":"Romo Thomas"},{"name":"Lukman Sardi","character":"Romo Rendra"},{"name":"Lydia Kandou","character":"Sister Aloysia"},{"name":"Ferry Salim","character":"Halim"},{"name":"Feby Febiola","character":"Linda"},{"name":"Venly Arauna","character":"Daniel"},{"name":"Keysha Angelica","character":"Nia"},{"name":"Kiki Narendra","character":"Romo Wicaksana"},{"name":"Faiz Vishal","character":"Bayu"},{"name":"Pipien Putri","character":"Liliana"}]'::jsonb, '13+', null),
(1691303, 'The Doll Ghawiah', 'Kengerian', 110, 'NR', 'It all began with an accident on Babakan Siliwangi Road. Nala encountered a mysterious little girl and her doll in the Babakan Siliwangi forest. The doll’s name was Ghawiah, which means “lost.” Ever since that accident, many strange occurrences have begun to haunt the local residents.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/tXt9V93rf1Jpy1DsDjiDLzYsa3w.jpg', 'https://image.tmdb.org/t/p/w1280/3Bp3yKRBIUQoZwsRCspZThFn5zf.jpg', 2.5, 'MnnHZcvgpW4', '2026-10-29', 2.349, 2, 'tt42575845', null, null, 'TV-MA', 'Kengerian, Misteri, Cerita Seru', 'Guntur Soeharjanto', 'Riheam Junianti', 'Rocky Soraya', 'Hitmaker Studios, Legacy Pictures, Masih Belajar Pictures, DT Films', '[{"name":"Titi Kamal","character":"Evi"},{"name":"Darius Sinathrya","character":"Arya"},{"name":"Sara Wijayanto","character":"Laras"},{"name":"Aisyah Aqilah","character":"Gita"},{"name":"Laura Moane","character":"Nala"},{"name":"Fara Shakila","character":"Uci"},{"name":"Ananda George","character":"Maman"},{"name":"Putri Patricia","character":"Uci''s Mother"},{"name":"Rendi Khrisna","character":"Uci''s Father"},{"name":"Daniel Topan","character":"Restaurant Guest"}]'::jsonb, '17+', null),
(1735459, 'Ibu, Bagaimana Aku Tanpamu?', 'Drama', 111, 'NR', 'Confronted with the devastating reality of her mother’s terminal diagnosis, a young woman embarks on a compressed emotional journey to fulfill her mother''s final, unexpressed desires before her imminent decease, forcing a profound reckoning with grief and filial duty.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/zaL5fqcgMlBdkrwRF1g7XLDsbj0.jpg', 'https://image.tmdb.org/t/p/w1280/sLH3yzYvQn2UDWuEqtrsX1MAgB3.jpg', 6, 'Sh6ryxsOHYg', '2026-09-24', 1.811, 3, 'tt44773462', 6.1, 16, 'TV-G', 'Drama, Keluarga', 'Herwin Novianto', 'Alim Sudio', 'Frederica', 'Falcon Pictures', '[{"name":"Marsha Timothy","character":"Stella"},{"name":"Fara Shakila","character":"Rere"},{"name":"Praz Teguh","character":"Daniel Lim"},{"name":"Ivan Gunawan","character":"Prince"},{"name":"Sara Wijayanto","character":"Nita"},{"name":"Kiki Narendra","character":"Rommy"},{"name":"Queen Lubis","character":"Maya"},{"name":"Papham","character":"Hestu"},{"name":"仲川遥香","character":"Julia"},{"name":"Kinaryosih","character":"Deasy"}]'::jsonb, 'SU', null),
(1721251, 'Bapak Paling Jujur', 'Komedi', 103, 'NR', 'Pencitraan udah disiapin. Jonas Prakoso dan Sambodo udah siap banget jadi calon gubernur dan wakil gubernur idaman. Tapi kutukan nenek bikin Jonas GAK BISA BOHONG SAMA SEKALI! Kepikiran apa, nyeplos. Di depan keluarga, timses, lawan politik, sampai rakyat. Kalau mulut nggak punya rem, siap-siap semuanya kebongkar!', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/dO4XM18B792WojquLq3oF98eZM5.jpg', 'https://image.tmdb.org/t/p/w1280/tis0UiquiP5VmA6tgzqy2egztvs.jpg', 6.2, 'jkCL8mxz-EU', '2026-10-15', 2.231, 3, 'tt43635436', null, null, null, 'Komedi, Drama', 'Fajar Nugros', 'Rino Sarjono, Ambaridzki Ramadhantyo, Farhan Arief, Almas Alardhi', 'Aoura Lovenson Chandra', 'Cahaya Pictures, Studio Antelope, Laspro, ARENDI', '[{"name":"Andovi da Lopez","character":"Jonas Prakoso"},{"name":"Claresta Taufan","character":"Vanny"},{"name":"Nayla D. Purnama","character":"Rasuna"},{"name":"Benidictus Siregar","character":"Marbun"},{"name":"Soleh Solihun","character":"Sambodo"},{"name":"Indy Barends","character":"Suherlin"},{"name":"Rizki Muhamad Firman","character":"Kris"},{"name":"Mrkeminggris","character":"Rudi Bule"},{"name":"Jovial Da Lopez","character":"Actor Played Young Jonas"},{"name":"Dian Sidik","character":"Yoga Instructor"}]'::jsonb, '13+', null),
(1699756, 'Ayah, Aku Mau Cerita....', 'Kejahatan', 166, 'NR', 'When his family stares down the barrel of criminal charges, a commoner channels his street smarts and knowledge of action films to tie the long arm of the law into an investigative Gordian knot.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1nHqIu8RAOv16yAWbVSL0XTsk3i.jpg', 'https://image.tmdb.org/t/p/w1280/oj93gx6nEqcmU8sFDr5c43bA0Jl.jpg', 6.5, '9nI65nJULvQ', '2026-08-20', 2.135, 2, 'tt42903440', null, null, null, 'Kejahatan, Drama, Misteri, Cerita Seru', 'Danial Rifki', 'Danial Rifki', 'Frederica', 'Falcon Pictures', '[{"name":"Vino G. Bastian","character":"Andi Budiman"},{"name":"Marsha Timothy","character":"Iriana"},{"name":"Niken Anjani","character":"Marini"},{"name":"Ziva Magnolya","character":"Aisha"},{"name":"Pritt Timothy","character":"Karim"},{"name":"Gunawan Sudradjat","character":"Salman"},{"name":"Rizky Hanggono","character":"Gatot"},{"name":"Sadana Agung","character":"Yusuf"},{"name":"Queen Lubis","character":"Ditta"},{"name":"Norman R. Akyuwen","character":"Hendrikus"}]'::jsonb, '13+', null),
(1496450, 'Pirunduk', 'Kengerian', 96, 'NR', 'Di sebuah desa terpencil, Siti (Aulia Sarah) menikahi juragan Badarudin (Bucek Depp) demi melunasi utang ayahnya, namun justru terjebak dalam rumah tangga yang penuh kekerasan. Saat kehidupannya semakin terpuruk, Siti memilih jalan terlarang dengan mempelajari ilmu hitam Pirunduk untuk menundukkan suaminya. Namun kekuatan tersebut membawa konsekuensi yang mengancam Siti, Badarudin, dan seluruh warga desa.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/3l9k6uYjyHglCMWOrcjuE9SsDvS.jpg', 'https://image.tmdb.org/t/p/w1280/tjqtp0V9YoJPgGqOTC7Qa7313yT.jpg', 7, 'Zn1CqB2eVUM', '2026-10-22', 2.176, 2, 'tt36553729', null, null, null, 'Kengerian', 'Billy Christian', 'Budi Ismanto, Tubagus Deddy', 'Budi Ismanto', 'Bima Sakti Pictures, Pentana Production Studio, Pichouse Films', '[{"name":"Aulia Sarah","character":"Siti"},{"name":"Bucek Depp","character":"Badarudin"},{"name":"Yoriko Angeline","character":"Ratih"},{"name":"Alam Jaya","character":"Ramlan"},{"name":"Rina DD Basrindu (Acil Imas)","character":"Mak Ijah"},{"name":"Boy Idrus","character":"Rojak"},{"name":"Bastari Bayu","character":"Jamal"},{"name":"Kholilur Rahman","character":"Abi"},{"name":"Ayu Putri","character":"Aida"},{"name":"Trisia Chandra","character":"Acil Nunung"}]'::jsonb, '13+', null),
(1590613, 'Cerita Lila', 'Kengerian', 106, 'NR', 'Lila, arwah seorang gadis kecil yang masih terikat pada masa lalunya, terus mencari saudari kembarnya yang hilang, Lili. Kehidupannya berubah saat Nia dan ibunya, Tari, pindah ke rumah tempat Lila berada. Persahabatan yang terjalin antara Lila dan Nia membawa mereka pada pencarian yang perlahan membuka rahasia kelam yang lama terkubur. Ketika kehadiran sosok Rahma mulai mengancam keselamatan mereka, Nia meminta bantuan Sara Wijayanto dan Wisnu untuk mengungkap kebenaran di balik tragedi masa lalu.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/80CcJdrV3ewqPawFMAFGIrldgR5.jpg', 'https://image.tmdb.org/t/p/w1280/9rZVlvA5Nk3SA4GJk1ySUbZLtTg.jpg', 5.3, '_S9ummr0mjg', '2026-06-18', 14.866, 8, 'tt39400218', null, null, null, 'Kengerian', 'Bobby Prasetyo', 'Erwanto Alphadullah, Gea Rexy, Sara Wijayanto', 'Raam Punjabi', 'MVP Pictures, Folago Pictures, PK Films, Legacy Pictures', '[{"name":"Lutesha","character":"Tari"},{"name":"Shareefa Daanish","character":"Rahma"},{"name":"Myesha Lin","character":"Nia"},{"name":"Firzanah Alya","character":"Lila"},{"name":"Firzanah Alya","character":"Lili"},{"name":"Sara Wijayanto","character":"Herself"},{"name":"Wisnu Hardana","character":"Wisnu"},{"name":"Whani Darmawan","character":"Old Bimo"},{"name":"Demian Aditya","character":"Himself"},{"name":"Fadi Iskandar","character":"Himself"}]'::jsonb, '17+', null),
(1469930, 'Tumbal Proyek', 'Kengerian', 106, 'NR', 'While investigating their father’s death inside a major bridge construction company, Yuda and his family attempt to prove that the frequent, deadly workplace accidents are actually human sacrifices.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/wdOa8jWX8u1YNSlWyRvoNCc9y7S.jpg', 'https://image.tmdb.org/t/p/w1280/k3Nc57fdRkzleHjodta45mGJV2C.jpg', 3.9, 'StEBQjJcubs', '2026-05-13', 10.811, 9, 'tt38497679', 6.8, 78, null, 'Kengerian, Cerita Seru', 'Jeropoint', 'Jeropoint', 'Dheeraj Kalwani', 'Dee Company', '[{"name":"Callista Arum","character":"Laras"},{"name":"Kiesha Alvaro","character":"Yuda"},{"name":"Karina Suwandi","character":"Martha"},{"name":"Eduwart Manalu","character":"Sutomo"},{"name":"Fuad Idris","character":"Mbah Tarmo"},{"name":"Agus Firmansyah","character":"Rudi"},{"name":"Adi Sudirja","character":"Yanto"},{"name":"Rendi Khrisna","character":"Bayu"},{"name":"Raffan Al Aryan","character":"Wahyu"},{"name":"Cetul Leatherart","character":"Heru"}]'::jsonb, '17+', null),
(1589713, 'Badut Gendong', 'Aksi', 101, 'NR', 'Darso, a clown busker, lost his wife and unborn child to thug violence. In grief, he brought his wife''s body back to his village. However, the village is in chaos due to a conflict with an evil developer and a curse ritual that summons dark forces. Darso is also caught up in the evil forces connected to the person he loves most.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/kIAltyOVZFIRFFFgBUBABb0HyF7.jpg', 'https://image.tmdb.org/t/p/w1280/aVnrli2pknnbAeGhsjhLBWc5yCL.jpg', 7.8, 'yPaqYzR_ocI', '2026-05-27', 9.703, 6, 'tt39059815', null, null, null, 'Aksi, Drama, Kengerian, Fantasi, Cerita Seru', 'Charles Gozali', 'Charles Gozali, Asaf Antariksa, Dharma Putra PN', 'Linda Gozali', 'Magma Entertainment, Legacy Pictures, Komet Productions, Skop Productions Sdn. Bhd.', '[{"name":"Marthino Lio","character":"Darso"},{"name":"Clara Bernadeth","character":"Arini"},{"name":"Derby Romero","character":"Jamil"},{"name":"Dayinta Melira","character":"Darsi"},{"name":"Khiva Iskak","character":"Billy"},{"name":"Vonny Anggraini","character":"Yu Tini"},{"name":"Totos Rasiti","character":"Lik Badrun"},{"name":"Akbar Kobar","character":"Andul"},{"name":"Barry Prima","character":"Ki Kamboja"},{"name":"José Rizal Manua","character":"Mbah Kaum"}]'::jsonb, '17+', null),
(1574961, 'Warkop DKI: ViRaLiN dOoOoNg..!!', 'Komedi', 120, 'NR', 'Three best friends, Dono, Kasino, and Indro, want to get quickly rich by becoming content creators. After numerous failed attempts, they try making a horror-drama video in a remote village. However, their fake plan turns into reality when they are actually haunted by vengeful spirits. To survive, they must uncover the spirits'' tragic pasts and help them get justice. Although their horror project fails, their hilarious failed videos make them viral and famous.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/w9B66TqXL0WGw2roQOk3ohxJQWM.jpg', 'https://image.tmdb.org/t/p/w1280/dyBfej8BJJe2XHWGnYCmHNA9uyi.jpg', 5.5, 'niv-Nr5xMGw', '2026-06-11', 4.557, 2, 'tt38865049', null, null, null, 'Komedi', 'Herwin Novianto', 'Theo Arnoldy, Daryl Wilson, Herwin Novianto, Dany Beler', 'Frederica', 'Falcon Pictures', '[{"name":"Deddy Mahendra Desta","character":"Dono"},{"name":"Vino G. Bastian","character":"Kasino"},{"name":"Tora Sudiro","character":"Indro"},{"name":"Indro Warkop","character":"Papi Yulia"},{"name":"Marsha Timothy","character":"Yulia"},{"name":"Asri Welas","character":"Nenek Yulia / Tante Hotel / Mayat Nenek"},{"name":"Indy Barends","character":"Mami Yulia"},{"name":"Ivan Gunawan","character":"Pablo"},{"name":"Andre Taulany","character":"Palagede"},{"name":"Dicky Difie","character":"Reza"}]'::jsonb, '13+', null),
(1616674, 'Aku Sebelum Aku', 'Drama', 127, 'NR', 'A young student battling pressure, panic and a demanding father uses a class project to discover that truth — not trophies — might finally set him free.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/xmwPr0YOFS6vC3aydnE85gxp36t.jpg', 'https://image.tmdb.org/t/p/w1280/1QiFfqaAhZi4HMlJNMvJVXOovc6.jpg', 6.7, null, '2026-07-11', 3.675, 22, 'tt39370887', null, null, null, 'Drama', 'Gina S. Noer', 'Gina S. Noer', 'Sigit Pratama, Anna Melani', 'Wahana Kreator Nusantara', '[{"name":"Bimasena","character":"Jati"},{"name":"Ringgo Agus Rahman","character":"Jaya"},{"name":"Widuri Puteri","character":"Asa"},{"name":"Prastiwi Dwiarti","character":"Ambu Asih"},{"name":"Aming Sugandhi","character":"Mr. Juned / Mr. Zai"},{"name":"Ronal Surapradja","character":"Uwa Geni"},{"name":"Ashila Husnia Fitriani","character":"Meranti"},{"name":"Candil","character":"Uwa Yayan"},{"name":"M. Yusuf Ozkan","character":"Echo"},{"name":"Darin Fauzi","character":"Dali"}]'::jsonb, '13+', null),
(1599729, 'Semua Akan Baik-Baik Saja', 'Drama', 113, 'NR', 'After their mother Mentari passes away, a group of estranged siblings must move in with their older brother Langit, forcing them to confront their personal struggles and heal old wounds to rediscover the true meaning of family.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/wWM8EqNeEfIVnqfQ3FLTYbTZO1K.jpg', 'https://image.tmdb.org/t/p/w1280/fZO7SGfX4mraJdMxrB7O8XYXGPU.jpg', 7.2, 'M4_0sOryPkU', '2026-05-13', 3.888, 3, 'tt39213727', 7.9, 81, null, 'Drama, Komedi', 'Baim Wong', 'Oka Aurora, Eurico Kevin Pratama, Baim Wong', 'Baim Wong', 'Tiger Wong Entertainment, Legacy Pictures, RANS Entertainment, Role Entertainment', '[{"name":"Reza Rahadian","character":"Langit"},{"name":"Christine Hakim","character":"Ibu Wida"},{"name":"Raihaanun","character":"Bintang"},{"name":"Happy Salma","character":"Mentari"},{"name":"Ari Irham","character":"Banyu"},{"name":"Aquene Aziz Djorghi","character":"Malikha"},{"name":"Malika Shaquena","character":"Syaffa"},{"name":"Alim","character":"Alim"},{"name":"Asri Welas","character":"Sarah"},{"name":"Teuku Rifnu Wikana","character":"Ilham"}]'::jsonb, '13+', null),
(1519340, 'Jangan Buang Ibu', 'Drama', 119, 'NR', 'A single mother struggles to raise her three children while burdened by debt after her husband abandons the family, straining their relationships as her children try to rebuild their bond with her before it is too late.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/kN0ZKAhZX0yPDyD8jg6cd0QJyKH.jpg', 'https://image.tmdb.org/t/p/w1280/sBwhJiHNOssdvQ4BFoAEh0zq9oI.jpg', 6.5, 'zAVD0_P_3Hk', '2026-06-25', 3.686, 2, 'tt39307081', null, null, null, 'Drama, Keluarga', 'Hadrah Daeng Ratu', 'Wahyu Derapriyangga, Widya Arifianti', 'Agung Saputra', 'Leo Pictures, Legacy Pictures, Narasi Semesta, TIX ID', '[{"name":"Nirina Zubir","character":"Ristiana"},{"name":"Refal Hady","character":"Tama"},{"name":"Amanda Manopo","character":"Dewi"},{"name":"Saputra Kori","character":"Tria"},{"name":"Dwi Sasono","character":"Ridho"},{"name":"Fadly Faisal","character":"Hanif"},{"name":"Saskia Chadwick","character":"Rani"},{"name":"Erika Carlina","character":"Asti"},{"name":"Basmalah Gralind","character":"Marsha"},{"name":"Farrell Rafisqy","character":"Zayn"}]'::jsonb, '13+', null),
(1773587, 'Skenario Sang Jenderal', 'Dokumenter', 89, 'NR', 'When a young officer is murdered inside a general''s home, a high-stakes investigation exposes a web of corruption and a cover-up reaching the highest ranks of the National Police.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/vAxYdcUh1MlZbidvGtYEHj0yLc2.jpg', 'https://image.tmdb.org/t/p/w1280/9bTTbUP8HAZt94D0hEGMVPC5kUq.jpg', 6.7, null, '2026-09-18', 2.866, 3, 'tt46084824', 6.3, 119, 'TV-MA', 'Dokumenter', 'Rob Sixsmith', 'Rob Sixsmith', 'Nana Riskhi, Jessica Lee Chu En', 'Beach House Pictures', '[{"name":"Rosti Simanjuntak","character":"Self"},{"name":"Ito Sumardi","character":"Self"},{"name":"Poengky Indarti","character":"Self"},{"name":"Arry Gautama","character":"Recreation Cast"},{"name":"Exan Zen","character":"Recreation Cast"},{"name":"Faudiyah Sari Chaniago","character":"Recreation Cast"},{"name":"Fitra Wijaya","character":"Recreation Cast"},{"name":"Putri Permata","character":"Recreation Cast"},{"name":"Rangga Saputro","character":"Recreation Cast"},{"name":"Vitta Mariana","character":"Recreation Cast"}]'::jsonb, '17+', null),
(1581587, 'Gudang Merica', 'Komedi', 98, 'NR', 'Belum diketahui.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/nwriVQsL2IlWktj8jafKs5qbrgi.jpg', 'https://image.tmdb.org/t/p/w1280/ymyCANhZD7Bhuvbc2KQeB3sEqwI.jpg', 5.5, '1weXCXIYrWs', '2026-05-21', 3.235, 2, 'tt41423961', 5.8, 8, null, 'Komedi, Kengerian, Misteri', 'Imam Darto', 'Imam Darto, Sesa Nasution, Warman Nasution', 'Raam Punjabi', 'MVP Pictures, Pabrik Cerita, Folago Pictures', '[{"name":"Ardhito Pramono","character":"Razi"},{"name":"Arla Ailani","character":"Rindu"},{"name":"Fatih Unru","character":"Adit"},{"name":"Zulfa Maharani","character":"Tanti"},{"name":"Benidictus Siregar","character":"Sidik"},{"name":"Rizky Inggar","character":"Suster Ella"},{"name":"Angga Nggok","character":"Tukang Bubur"},{"name":"Melly Manuhutu","character":"Nenek"},{"name":"Rizky Teguh","character":"Adul"},{"name":"Bonar Manalu","character":"Gunawan"}]'::jsonb, '17+', null),
(1590909, 'Ibuku', 'Drama', 95, 'NR', 'A destitute widow and former traditional dancer defies social ostracization to embark on a desperate international journey, seeking a final reconciliation with her estranged daughter who faces execution abroad for the murder of an abusive employer.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/zYwxtzF9wIAPybLfU4s7sADX3ZG.jpg', 'https://image.tmdb.org/t/p/w1280/4HnXizTOzGJYc1FaHslow31dzZu.jpg', null, 'ItgV0HrDh9Q', '2026-10-08', 3.23, 0, 'tt38773544', null, null, null, 'Drama', 'Eddie Cahyono', 'Eddie Cahyono', 'Tika Bravani, 山口晋', 'ANP Talenta Media, Memorieslight Pictures, Yasa Buana Film, Chinese Shadows', '[{"name":"Christine Hakim","character":"Sumiati"},{"name":"Ayushita Nugraha","character":"Sri"},{"name":"Landung Simatupang","character":""},{"name":"Tika Bravani","character":""},{"name":"Udik Supriyanta","character":""},{"name":"Sriwidiyanti","character":""},{"name":"Nano Asmorodono","character":""},{"name":"Rendra Bagus Pamungkas","character":""},{"name":"Liek Suyanto","character":""},{"name":"Intan Kemalasari","character":""}]'::jsonb, null, null),
(1263153, 'Forza', 'Drama', 90, 'NR', 'An impoverished thirteen-year-old adolescent from the slums of Bali finds his aspirations of professional football within reach after forming an unlikely partnership with a veteran athlete on the verge of retirement, culminating in an unprecedented trial with the AC Milan Youth Academy in Italy.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/2zdJXARQ5hACMuNXKRPrtRLzMwl.jpg', 'https://image.tmdb.org/t/p/w1280/gMxec0LJrphjAkfv0iCyikqzOs3.jpg', null, null, '2026-10-25', 2.76, 0, 'tt31411099', null, null, null, 'Drama, Keluarga', 'Marco Balsamo', 'Marco Balsamo', 'Marco Balsamo, Tara Sibel', 'RIVA Studios, Adhya Pictures, Laser Film, Coevolution', '[{"name":"Teuku Rifnu Wikana","character":"Soleh"},{"name":"Atiqah Hasiholan","character":"Indah"},{"name":"Arie Kriting","character":"Heri"},{"name":"Yoriko Angeline","character":"Dewi"},{"name":"Ruth Marini","character":"Annisa"},{"name":"Oka Antara","character":""},{"name":"Ghazi Alhabsy","character":"Bima"},{"name":"Marco Balsamo","character":"Marco"},{"name":"Tio Pakusadewo","character":"Arief"},{"name":"Tara Sibel","character":"Sibel"}]'::jsonb, 'SU', null),
(1283515, 'Verity', 'Misteri', 117, 'NR', 'Lowen Ashleigh, hired to ghostwrite for best-selling author Verity Crawford, uncovers Verity''s autobiographical notes, and becomes involved in what may prove to be a lethal conspiracy.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/rmaNMA1seHqpjtnYKzyynFAr1g8.jpg', 'https://image.tmdb.org/t/p/w1280/cKetrF2dAnQ0AMV5i4BMOs41I5P.jpg', 6.9, 'xdPMKhjMSFs', '2026-09-30', 235.311, 562, 'tt32261958', null, null, 'R', 'Misteri, Cerita Seru', 'Michael Showalter', 'Nick Antosca, Colleen Hoover', 'Alex Hedlund, Nick Antosca, Michael Showalter, Jordana Mollick', 'Eat the Cat, Semi-Formal Productions, Somewhere Pictures, Shiny Penny Productions', '[{"name":"Dakota Johnson","character":"Lowen Ashleigh"},{"name":"Anne Hathaway","character":"Verity Crawford"},{"name":"Josh Hartnett","character":"Jeremy Crawford"},{"name":"Brady Wagner","character":"Crew Crawford"},{"name":"Ismael Cruz Cordova","character":"Corey"},{"name":"Ірина Дворовенко","character":"Anna"},{"name":"Sienna Kulovitz","character":"Harper Crawford"},{"name":"K.K. Moggie","character":"Amanda Thomas"},{"name":"Tom Galantich","character":"Barron Stephens"},{"name":"Lou Martini Jr.","character":"Limo Driver"}]'::jsonb, '17+', 9728),
(1400940, 'Clayface', 'Kengerian', 109, 'NR', 'Matt Hagen''s meteoric rise from Gotham street kid to Hollywood leading man is tragically cut short when a local crime boss''s actions leave him horribly disfigured. Abandoned by his team and with nothing left, Matt seeks out a cutting edge treatment that miraculously returns him to his former self… but also unexpectedly affects his grip on reality, spiraling him down a destructive path of all-consuming revenge.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/9l1NuFjel2j89hiuiJbsxfblqjy.jpg', 'https://image.tmdb.org/t/p/w1280/xSDoxv4pHvs4xZjvTb0Iqg1A6ro.jpg', 7.4, 'f7jlCqdtwdM', '2026-10-19', 149.096, 351, 'tt34890576', 7.5, 37372, 'R', 'Kengerian, Cerita Seru, Cerita Fiksi', 'James Watkins', 'Bill Finger, Bob Kane, Mike Flanagan, حسین امینی', 'James Gunn, Peter Safran, Matt Reeves, Lynn Harris', 'DC Studios, Domain Entertainment, 6th & Idaho Motion Picture Company, Troll Court Entertainment', '[{"name":"Tom Rhys Harries","character":"Matt Hagen / Clayface"},{"name":"Naomi Ackie","character":"Caitlyn Corr"},{"name":"Eddie Marsan","character":"Frank Fitzpatrick"},{"name":"Max Minghella","character":"John Borrelli"},{"name":"David Dencik","character":"Markos Szabo"},{"name":"Francesca Corney","character":"Rosie"},{"name":"Ruby Sear","character":"Theresa"},{"name":"Wil Coban","character":"Bones"},{"name":"Joshua James","character":"Corey Bowery"},{"name":"Jake Curran","character":"Patches"}]'::jsonb, '17+', 2764),
(1465063, 'Forgotten Island', 'Animasi', 109, 'NR', 'While celebrating their last night together, high school graduates and best friends Jo and Raissa stumble upon a mysterious portal that transports them to the fantastical island of Nakali. When they discover that the memories of their entire friendship are the price for returning home, Jo and Raissa must race to find a way to leave the island before they forget each other forever.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/myd1K3gefdNAWFsGNRDdMeiK9Qg.jpg', 'https://image.tmdb.org/t/p/w1280/cNICUho5uiAGkfCAQq1ihyaMla4.jpg', 8, 'PhgY8cOJiQA', '2026-09-10', 118.51, 195, 'tt36583977', 7.7, 1331, 'PG', 'Animasi, Petualangan, Fantasi, Komedi, Keluarga', 'Januel Mercado, Joel Crawford', 'Joel Crawford, Januel Mercado', 'Mark Swift', 'DreamWorks Animation', '[{"name":"H.E.R.","character":"Jo (voice)"},{"name":"Liza Soberano","character":"Raissa (voice)"},{"name":"Dave Franco","character":"Raww (voice)"},{"name":"Jenny Slate","character":"Batiba (voice)"},{"name":"Manny Jacinto","character":"Bungi Tiyanak (voice)"},{"name":"Lea Salonga","character":"Manang (voice)"},{"name":"Dolly de Leon","character":"Lola (voice)"},{"name":"Jo Koy","character":"Datu (voice)"},{"name":"Ronny Chieng","character":"King Truffle Wuffle (voice)"},{"name":"Kevin McCann","character":"Prince Mermahn (voice)"}]'::jsonb, '13+', 2670),
(1153576, 'Street Fighter', 'Aksi', 120, 'NR', 'In 1993, estranged Street Fighters Ryu and Ken Masters are thrown back into combat when the mysterious Chun-Li recruits them for the next World Warrior Tournament: a brutal clash of fists, fate, and fury. But behind this battle royale lies a deadly conspiracy that forces them to face off against each other and the demons of their past. And if they don''t, it''s GAME OVER!', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ccxdepKqORLwccbzvO4eAGkN0IC.jpg', 'https://image.tmdb.org/t/p/w1280/qRN8eqYwG6HPSy0i3fKzuLrUOhp.jpg', 6.3, 'U6sbm1OaJb8', '2026-10-13', 82.54, 211, 'tt27419420', 6.2, 1231, 'PG-13', 'Aksi, Fantasi', 'Kitao Sakurai', 'Dalan Musson, Gary Dauberman, T.J. Fixman, Kitao Sakurai', 'Mary Parent, Cale Boyter, Jason Momoa, Takayuki Nakayama', 'Capcom, Legendary Pictures', '[{"name":"Andrew Koji","character":"Ryu"},{"name":"Noah Centineo","character":"Ken Masters"},{"name":"Callina Liang","character":"Chun-Li"},{"name":"David Dastmalchian","character":"M. Bison"},{"name":"Andrew Schulz","character":"Dan Hibiki"},{"name":"Joe Anoa''i","character":"Akuma"},{"name":"Cody Rhodes","character":"Guile"},{"name":"Jason Momoa","character":"Blanka"},{"name":"Eric André","character":"Don Sauvage"},{"name":"50 Cent","character":"Balrog"}]'::jsonb, '13+', 1337),
(1400837, 'Other Mommy', 'Kengerian', 93, 'NR', 'Young Bela forms a relationship with a sinister entity in her home that looks uncannily like her own mother, drawing her into a terrifying and increasingly dark world.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/fGRNCssTRrhYZxNzykGGCoMsAVq.jpg', 'https://image.tmdb.org/t/p/w1280/ncm7djsVTHQQMX2HEbEVxMUFchG.jpg', 5.8, '-mnTITqqiT0', '2026-10-07', 87.501, 184, 'tt36586020', null, null, 'R', 'Kengerian', 'Rob Savage', 'Josh Malerman, Nathan Elston', 'James Wan', 'Spin a Black Yarn, Blumhouse Atomic Monster', '[{"name":"Jessica Chastain","character":"Mommy / Other Mommy"},{"name":"Jay Duplass","character":"Daddo"},{"name":"Arabella Olivia Clark","character":"Bela"},{"name":"Karen Allen","character":"Grandma Ruth"},{"name":"Arian Moayed","character":"Uncle Frank"},{"name":"Dichen Lachman","character":"Lois Anthony"},{"name":"Sean Kaufman","character":"Kelvin"},{"name":"Adam Silver","character":"Brian"},{"name":"Alec Secăreanu","character":"Ruiss"},{"name":"Millie Wood","character":"Little Girl"}]'::jsonb, '17+', null),
(1263337, 'Heart of the Beast', 'Petualangan', 101, 'NR', 'After a harrowing plane crash, Special Forces officer James Belmont and his combat dog, Odin, find themselves stranded deep in the Alaskan wilderness. Together, they are forced into a brutal fight for survival against the elements.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/1ApfSA8JTqeha3GTFEY8syV4auq.jpg', 'https://image.tmdb.org/t/p/w1280/bicMU6xVD5deVyKP2azpyx7xkmH.jpg', 7.3, 'UkMuGKqAux4', '2026-09-19', 78.207, 373, 'tt7526136', 7.5, 542, 'PG-13', 'Petualangan, Cerita Seru', 'David Ayer', 'Cameron Alexander', 'Olivia Hamilton, David Ayer, Marty Bowen, Brad Pitt', 'Paramount Pictures, Wild Chickens Productions, Temple Hill Entertainment, Domain Entertainment', '[{"name":"Brad Pitt","character":"James Belmont"},{"name":"J.K. Simmons","character":"Watkins"},{"name":"Anna Lambe","character":"Amber"},{"name":"Justin Melnick","character":"Military Soldier"},{"name":"Shaun DeZern","character":"Military Soldier"}]'::jsonb, '13+', null),
(299534, 'Avengers: Endgame', 'Petualangan', 181, 'NR', 'Terdampar di luar angkasa tanpa persediaan makanan dan minuman, Tony Stark berusaha mengirim pesan untuk Pepper Potts dimana persediaan oksigen mulai menipis. Sementara itu para Avengers yang tersisa harus menemukan cara untuk mengembalikan 50% mahluk di seluruh dunia yang telah dilenyapkan oleh Thanos.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/jtDv3lCnST0fZRvdYFwR5CVwK2x.jpg', 'https://image.tmdb.org/t/p/w1280/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', 8.2, 'L2NAh3CIdig', '2019-04-24', 68.28, 29195, 'tt4154796', 8.4, 1497908, 'PG-13', 'Petualangan, Cerita Fiksi, Aksi', 'Joe Russo, Anthony Russo', 'Steve Gan, Jim Starlin, Joe Simon, Keith Giffen', 'Kevin Feige', 'Marvel Studios', '[{"name":"Robert Downey Jr.","character":"Tony Stark / Iron Man"},{"name":"Chris Evans","character":"Steve Rogers / Captain America"},{"name":"Mark Ruffalo","character":"Bruce Banner / Hulk"},{"name":"Chris Hemsworth","character":"Thor"},{"name":"Scarlett Johansson","character":"Natasha Romanoff / Black Widow"},{"name":"Jeremy Renner","character":"Clint Barton / Hawkeye"},{"name":"Josh Brolin","character":"Thanos"},{"name":"Don Cheadle","character":"James Rhodes / War Machine"},{"name":"Paul Rudd","character":"Scott Lang / Ant-Man"},{"name":"Benedict Cumberbatch","character":"Doctor Strange"}]'::jsonb, '13+', 920),
(1248832, 'Digger', 'Komedi', 129, 'NR', 'The most powerful man in the world embarks on a frantic mission to prove he is humanity''s savior before the disaster he''s unleashed destroys everything.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1ATXKrIPJyKNwnJ6lcG088Sa6zi.jpg', 'https://image.tmdb.org/t/p/w1280/vC5IxhgO6cVmw9O4QgkraRzfHvh.jpg', 7.5, 'job8V254NAE', '2026-09-28', 63.352, 492, 'tt31450459', null, null, null, 'Komedi, Drama', 'Alejandro G. Iñárritu', 'Alejandro G. Iñárritu, Sabina Berman, Jez Butterworth, Alexander Dinelaris', 'Alejandro G. Iñárritu, Tom Cruise, Mary Parent, Michael Sharp', 'Warner Bros. Pictures, Legendary Pictures, Domain Entertainment', '[{"name":"Tom Cruise","character":"Digger Rockwell"},{"name":"Riz Ahmed","character":"Dr. Nirav Ganesh"},{"name":"John Goodman","character":"President Compson"},{"name":"Sandra Hüller","character":"Emma Rockwell"},{"name":"Michael Stuhlbarg","character":"Vice President Eddie"},{"name":"Jesse Plemons","character":"Kenny Rockwell"},{"name":"Robert John Burke","character":"General Fitzgerald"},{"name":"Emma D''Arcy","character":"Lina"},{"name":"Burn Gorman","character":"Defense Secretary Amos"},{"name":"Sophie Wilde","character":"Hannah"}]'::jsonb, '17+', null),
(1255833, 'Whalefall', 'Cerita Seru', 106, 'NR', 'Following the death of his father, Jay Gardiner goes diving off the central Coast of California in search of his remains, but is swallowed by a massive sperm whale. While trapped inside its belly with only one hour of oxygen left, Jay comes to realize that the hard-earned lessons his father imparted may be the key to his escape.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/vjTYUTgh9nO88i6HZ4YPRhiFL05.jpg', 'https://image.tmdb.org/t/p/w1280/shW2jHkQLZVv4Fko2rJDqTGU0gx.jpg', 6.6, 'Dw-5ZGapGTQ', '2026-10-14', 61.625, 135, 'tt28535715', null, null, null, 'Cerita Seru', 'Brian Duffield', 'Brian Duffield, Daniel Kraus', 'Allan Mandelbaum, Ron Howard, Brian Grazer, Brian Duffield', 'Imagine Entertainment, 20th Century Studios, Jurassic Party', '[{"name":"Austin Abrams","character":"Jay Gardiner"},{"name":"Josh Brolin","character":"Mitt Gardiner"},{"name":"Elisabeth Shue","character":"Zara Gardiner"},{"name":"John Ortiz","character":"Hewey"},{"name":"Jane Levy","character":"Eva Gardiner"},{"name":"Emily Rudd","character":"Nan Gardiner"},{"name":"Kamy D. Bruder","character":"Whale Watcher Man"},{"name":"Mark Meloro Jr.","character":"Whale Watcher Man"},{"name":"Sam Franich","character":"Jay at 10"},{"name":"Nicholas Gould","character":"US Coast Guard Petty Officer Third Class Whaley"}]'::jsonb, '13+', null),
(1281331, 'The Social Reckoning', 'Drama', 113, 'NR', 'Frances Haugen, a young Facebook engineer, enlists the help of Jeff Horwitz, a Wall Street Journal reporter, to go on a dangerous journey that ends up blowing the whistle on the social network''s most guarded secrets.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/7jK6NuxVg1XuEV7UdNa6KO03IgZ.jpg', 'https://image.tmdb.org/t/p/w1280/wXTaGcqX3jvdXSKCJAkl5jZyrKp.jpg', 7, 'R8ANzYpaZaY', '2026-10-07', 44.926, 134, 'tt37510326', null, null, null, 'Drama, Cerita Seru', 'Aaron Sorkin', 'Aaron Sorkin', 'Aaron Sorkin, Todd Black, Peter Rice, Stuart M. Besser', 'Columbia Pictures, Alcon Entertainment, TSG Entertainment', '[{"name":"Mikey Madison","character":"Frances Haugen"},{"name":"Jeremy Allen White","character":"Jeff Horwitz"},{"name":"Jeremy Strong","character":"Mark Zuckerberg"},{"name":"Betty Gilpin","character":"Kris"},{"name":"Bill Burr","character":"Charlie Garrigan"},{"name":"Wunmi Mosaku","character":"Raya"},{"name":"Billy Magnussen","character":"Teddy Marks"},{"name":"Gbenga Akinnagbe","character":"Andy"},{"name":"Anna Lambe","character":"Morgan"},{"name":"Aidan Laprete","character":"Zach"}]'::jsonb, 'R', null),
(1594914, 'Lucky Strike', 'Kejahatan', 102, 'NR', 'A wounded American soldier fights to survive behind enemy lines during WWII''s Battle of the Bulge against the Germans, relying on his instinct, spy craft and a hand-radio to evade capture and find his way back to his unit.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/kzRAd7mj39ZY3FGNrDdZjqx56tn.jpg', 'https://image.tmdb.org/t/p/w1280/uujYvxE9s6KY4SbBZ0ZFN3oBJhW.jpg', 6.6, 'vtEnjikCXyA', '2026-06-26', 32.339, 65, 'tt19035928', null, null, null, 'Kejahatan, Aksi', 'Rod Lurie', 'Rod Lurie, Marc Frydman', 'Marc Frydman, Yariv Lerner, Les Weldon, Jonathan Yunger', 'Perfection Hunter Productions, Millennium Media, BondIt Media Capital', '[{"name":"Scott Eastwood","character":"Castle"},{"name":"Colin Hanks","character":"Colonel Neale"},{"name":"Aunjanue Ellis-Taylor","character":"Mrs. Caldwell"},{"name":"Taylor John Smith","character":"Bellingham"},{"name":"Lorne MacFadyen","character":"Major Barrett"},{"name":"Atanas Srebrev","character":"General Lauer"},{"name":"Alfie Stewart","character":"Burt Miller"},{"name":"Jonathan Yunger","character":"Cash"},{"name":"Timothy Blore","character":"Wilhelm"},{"name":"Laurent Maurel","character":"Georges Marsaud"}]'::jsonb, '13+', null),
(1234139, 'ஜெயிலர் 2', 'Aksi', 163, 'NR', 'When a dangerous syndicate expands its reach to threaten his family''s peace, retired jailer Tiger Muthuvel Pandian goes undercover as a driver. Operating from the shadows, he takes on ruthless new enemies to protect his home.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/upwdEyhhYZ7pT2hD535fr2MGfpx.jpg', 'https://image.tmdb.org/t/p/w1280/m0ks2o59mOAz6WdCybJ5FAUNTOU.jpg', 8, null, '2026-10-14', 27.465, 21, 'tt33318732', null, null, null, 'Aksi, Komedi, Drama', 'நெல்சன் திலீப்குமார்', 'நெல்சன் திலீப்குமார்', 'Kalanithi Maran', 'Sun Pictures', '[{"name":"Rajinikanth","character":"Muthuvel ''Tiger'' Pandian"},{"name":"S. J. Suryah","character":"Bodhi Kalpak"},{"name":"Suraj Venjaramoodu","character":"Dileep"},{"name":"Ramya Krishnan","character":"Vijayalakshmi ''Viji'' Pandian"},{"name":"Vidya Balan","character":"Kantha Kalpak"},{"name":"Namo Narayana","character":"Moorthi"},{"name":"யோகி பாபு","character":"Vimal"},{"name":"Mirnaa","character":"Swetha Pandian"},{"name":"Rithvik","character":"Rithvik ''Rithu'' Pandian"},{"name":"Hakeem Shajahan","character":"Sharva Kalpak"}]'::jsonb, '21+', null),
(1381071, 'ゴジラ-0.0', 'Cerita Fiksi', 135, 'NR', 'War reduced Japan to zero, and Godzilla plunged it into minus. Two years have passed since then, and the country has faced agonizing struggles to achieve recovery and finally reclaim its daily life. Just as humanity managed to cling to a hard-won peace, a new threat strikes, crushing hope in an instant. There is no third time. Everything ends here.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/zpcoFlZwyLnBt7bb5wmvGDCdg06.jpg', 'https://image.tmdb.org/t/p/w1280/oqrYIDH4tvfEzPe1yqT4jzmAWHQ.jpg', 9.3, 'pWJjYoqVSjQ', '2026-11-03', 38.71, 5, 'tt34384661', null, null, null, 'Cerita Fiksi, Kengerian, Aksi', 'Takashi Yamazaki', 'Takashi Yamazaki', '岸田一晃, 守屋圭一郎, 阿部豪', 'TOHO, Robot Communications, TOHO Studios', '[{"name":"神木隆之介","character":"Koichi Shikishima"},{"name":"浜辺美波","character":"Noriko Oishi"},{"name":"山田裕貴","character":"Shiro Mizushima"},{"name":"Kuranosuke Sasaki","character":"Seiji Akitsu"},{"name":"Jun Kunimura","character":""},{"name":"田中美央","character":"Captain Tatsuo Hotta"},{"name":"安藤サクラ","character":"Sumiko Ota"},{"name":"長澤まさみ","character":"Aoyama"},{"name":"田中泯","character":"Kanji Murakami"},{"name":"吉岡秀隆","character":"Kenji Noda"}]'::jsonb, 'R', null),
(1269325, 'दृश्यम: आखिरी हिस्सा', 'Cerita Seru', 148, 'NR', 'Years after outsmarting the police, Vijay Salgaonkar''s past resurfaces when a new evidence threatens to expose his secret. As the investigation reopens, he must outwit the system once again to save his family.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/7T62GSduOWDMB0gGDBs9pmtLTSB.jpg', 'https://image.tmdb.org/t/p/w1280/nq73eRdEooripf3k0XHLtX14zyC.jpg', 7.6, 'MFQFxsDWbA8', '2026-10-02', 12.796, 11, 'tt27050858', null, null, null, 'Cerita Seru, Drama, Misteri, Kejahatan', 'Abhishek Pathak', 'Abhishek Pathak, Aamil Keyan Khan, Parveez Shaikh', 'Kumar Mangat Pathak, Alok Jain, Ajit Andhare, Abhishek Pathak', 'Viacom18 Studios, Panorama Studios, Pen Studios', '[{"name":"Ajay Devgan","character":"Vijay Salgaonkar"},{"name":"Jaideep Ahlawat","character":"SP Rajveer Singh Tomar"},{"name":"Tabu","character":"Meera Deshmukh"},{"name":"శ్రియా శరణ్","character":"Nandini Salgaonkar"},{"name":"Rajat Kapoor","character":"Mahesh Deshmukh"},{"name":"ప్రకాష్ రాజ్","character":"Public Prosecutor Indrajith Shetty"},{"name":"Ishita Dutta","character":"Anju Salgaonkar"},{"name":"Mrunal Jadhav","character":"Anu Salgaonkar"},{"name":"Kamlesh Sawant","character":"Laxmikant Gaitonde"},{"name":"Saurabh Shukla","character":"Murad Ali"}]'::jsonb, 'NR', null),
(1375156, 'उड़ता तीर', 'Komedi', 137, 'NR', 'An amnesiac Pakistani spy wakes up believing he is a patriotic Indian counter-terrorism officer.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/tvICKypVlW7Iio4KVs7NousbSKi.jpg', 'https://image.tmdb.org/t/p/w1280/ncVecUcDZe1EOWtHaU2f8BFvbx4.jpg', 6.1, null, '2026-10-23', 11.712, 5, 'tt31806773', null, null, null, 'Komedi, Aksi', 'Aakash Kaushik', 'Aakash Kaushik', 'Guneet Monga, Karan Johar, Achin Jain, Apoorva Mehta', 'Dharma Productions, Sikhya Entertainment', '[{"name":"Ayushmann Khurrana","character":"Vikrant Thapar / Bilal Ahmad"},{"name":"Sara Ali Khan","character":"Yamini"},{"name":"Rahul Bose","character":"M D Burman"},{"name":"Supriya Pilgaonkar","character":"Maa"},{"name":"Brijendra Kala","character":"K K Srivastav"},{"name":"Ram Kapoor","character":"Niyazi"},{"name":"Mukul Dev","character":"Azhar Maqsood"},{"name":"Suhail Nayyar","character":"Dhruv Kumar Singh"},{"name":"Sandeep Anand","character":"Shambhu"},{"name":"Gulshan Grover","character":"General Mir"}]'::jsonb, '17+', null),
(1755291, 'NAZA', 'Dokumenter', 77, 'NR', 'Filmed at night from Tel Aviv rooftops, this investigative documentary examines the civilian casualties of Israel''s military operations in Gaza and the systems behind targeted killings of Palestinians.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bYfN1EKVyj2O7KXwuWDDCc47B5T.jpg', 'https://image.tmdb.org/t/p/w1280/inju8joDtL7KHtlFEGjFZ2UuqFa.jpg', 8.1, '40KW6knYMo4', '2026-09-25', 10.926, 127, 'tt44766123', 7.9, 3173, null, 'Dokumenter, Kejahatan', 'Yuval Abraham, רחל שור', null, 'James Wilson, Lindsay Poulton, Harry Davies', 'The Guardian, JW Films, Placeholder Films, Unseen Hand', '[{"name":"Yuval Abraham","character":"Self"},{"name":"Benjamin Netanyahu","character":"Self (archive footage) (uncredited)"}]'::jsonb, '17+', null),
(1400499, '近畿地方のある場所について', 'Kengerian', 103, 'NR', 'After an editor of an occult magazine suddenly vanishes, his friend Chihiro and his co-worker Yusei set out to discover the reason behind his disappearance.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/4JRRsGFmk1rkifiHErwP2ML96QV.jpg', 'https://image.tmdb.org/t/p/w1280/e0vwcf5R1yU2Uz2mTO4KbCxL5tT.jpg', 6.4, null, '2025-08-08', 10.441, 31, 'tt34969899', 6.3, 836, null, 'Kengerian, Misteri', '白石晃士', '背筋, 白石晃士, 大石哲也', '櫛山慶, 伊藤裕史', 'Warner Bros. Japan, AX-ON, Nippon Television Network Corporation, Yomiuri Telecasting Corporation', '[{"name":"菅野美穂","character":"Seno Chihiro"},{"name":"赤楚衛二","character":"Ozawa Yusei"},{"name":"夙川アトム","character":"Sayama Takeshi"},{"name":"佐藤京","character":"Nagano Haruka"},{"name":"のせりん","character":"Meguro Yuji"},{"name":"木村圭作","character":"Tanemura Eisaku"},{"name":"山田暖絆","character":"Takami Ryo"},{"name":"菅野莉央","character":"Morota Miya"},{"name":"福井裕子","character":"Omori Hideko"},{"name":"久保山智夏","character":"Sasayama Chie"}]'::jsonb, null, null),
(1414413, 'Brothers Under Fire', 'Aksi', 99, 'NR', 'Captain Jordan Wright''s squadron on leave for a wedding in Mexico encounters a murderous cartel. As Jordan tries to lead survivors to safety, war erupts between his squad and the cartel, forcing him into a battle to save his men.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/e5EKqk9V7N3w0WvYFhl6wSVrMp0.jpg', 'https://image.tmdb.org/t/p/w1280/6D2NsU3FIQVthPgjT6RAsX58qZ6.jpg', 5.9, '4R6mxR53m10', '2026-04-15', 8.45, 68, 'tt32394984', 4.9, 1992, null, 'Aksi, Cerita Seru, Misteri, Drama', 'Justin Chadwick', 'Delbert Hancock, Ian Mackenzie Jeffers', 'Griff Furst, James Keach, Nik Bower, Robert Stein', 'Highland Film Group, Align', '[{"name":"Kiefer Sutherland","character":"Capt. Jordan Wright"},{"name":"Tommy Martinez","character":"Alberto"},{"name":"Ashton Sanders","character":"Carson"},{"name":"Solly McLeod","character":"Danny"},{"name":"Laura Osma","character":"Isabella"},{"name":"Omar Chaparro","character":"Baker"},{"name":"Orlando Pineda","character":"Miguel"},{"name":"Laird Akeo","character":"Marco"},{"name":"Flora Martínez","character":"Angelica"},{"name":"Sebastián sierra","character":"Belisario"}]'::jsonb, null, null),
(961214, '부활남: 더 레드', 'Aksi', 102, 'NR', 'Despite unwavering support from his best friend Young-ha and the unwavering support of his younger sister Ye-rin, job seeker Seok Hwan just can''t seem to land a job, repeatedly failing interviews. One night, after yet another disastrous interview, he returns home only to be attacked by a group of strangers and killed. But 72 hours after his death, Seok Hwan suddenly opens his eyes as if nothing happened. He soon discovers that he possesses a special ability: no matter how many times he dies, he comes back to life. But there''s little time to process his extraordinary new power before a mysterious figure known as Black, who has discovered Hwan''s existence, begins hunting him down. Yet with each resurrection, Seok Hwan grows stronger, unleashing powers beyond anything he could have imagined!', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/nLsyRK3SmtdIftozpCd8sGQMRGD.jpg', 'https://image.tmdb.org/t/p/w1280/kiDd05NykJBIoEvJPSG5SOd7qc6.jpg', 5, 'FU3hfOVkPYI', '2026-09-30', 7.994, 1, 'tt29452783', null, null, null, 'Aksi, Fantasi, Komedi', '백종열', '강선주, 박성신', '임승용', 'Yong Film, Superfiction, YLAB, STUDIO NU:NGIL', '[{"name":"구교환","character":"Seok Hwan / Red"},{"name":"신승호","character":"Black"},{"name":"강기영","character":"Young-ha"},{"name":"김시아","character":"Cha Ye-rin"},{"name":"김성령","character":"Mi-joo"},{"name":"김인우","character":"Cha Hyeong-seok"},{"name":"김지율","character":""},{"name":"Justin Harvey","character":""},{"name":"김승범","character":"Bully 1"},{"name":"황근형","character":"Bully 4"}]'::jsonb, '17+', null),
(1706702, 'Daniel and the Fiery Furnace', 'Drama', 108, 'NR', 'During the Jewish exile to Babylon, Daniel and his friends face trials as Babylon''s armies conquer Jerusalem. Under King Nebuchadnezzar, they gain royal favor but make enemies. Their faith is tested at the fiery furnace.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/leE7dixdbzHXUBJdQgW1fFHz0ru.jpg', 'https://image.tmdb.org/t/p/w1280/4EoROOIIvrOLarSmM3EcCVxtaDl.jpg', 6.7, 'hLhsAThjo4c', '2026-09-18', 6.068, 6, 'tt37542993', null, null, null, 'Drama', 'Matthew Kooman, Daniel Kooman', 'Matthew Kooman, Daniel Kooman', 'Daniel Kooman, Matthew Kooman, Mena Massoud, Travis Mann', 'Pinnacle Peak Pictures, Unveil Studios, EKKL', '[{"name":"Mena Massoud","character":"Daniel"},{"name":"Elijah Alexander","character":"King Nebuchadnezzar"},{"name":"Sophia Decaro","character":"Susanna"},{"name":"Vladimir Angelove","character":"Hilkiah"},{"name":"Zaki Ali","character":"Azariah"},{"name":"Oncel Camci","character":"Hananiah (Son of Azzur)"},{"name":"Sunjay Midda","character":"Hananiah"},{"name":"Edward J. Marsh","character":"Yuval"},{"name":"Adam Lahraoui","character":"Mishael"},{"name":"Jazz Lintott","character":"Zaid"}]'::jsonb, '13+', null),
(607833, '인턴', 'Drama', 132, 'NR', 'A story about what happens when Sun-woo, the CEO of a fashion company who is more passionate than anyone when it comes to work, hires Ki-ho, who has a wealth of life experience, as a silver intern.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/9PX4rGgP1pXRlGcHkxzRsgvll8f.jpg', 'https://image.tmdb.org/t/p/w1280/OroFBNgB2RBzj2X65CweVhhQQG.jpg', 6.6, 'XMp9ietHc8A', '2026-09-16', 5.014, 5, 'tt43741215', 5.7, 59, null, 'Drama, Komedi', '김도영', '김도영, 왕혜지', '최재원, 송순호', 'Anthology Studios, Warner Bros. Korea', '[{"name":"최민식","character":"Kim Ki-ho"},{"name":"한소희","character":"Lee Sun-woo"},{"name":"김준한","character":"Young-hwan"},{"name":"류혜영","character":"Choi Min-ah"},{"name":"김금순","character":"Hee-sook"},{"name":"김요한","character":"Ju-seong"},{"name":"박예니","character":"Yu-jin"},{"name":"윤상정","character":"Yoon-hee"},{"name":"강태오","character":"Min-wook"},{"name":"한지은","character":"Lu-da"}]'::jsonb, '13+', null),
(1394740, '타짜: 벨제붑의 노래', 'Kejahatan', 130, 'NR', 'Jang Taeyoung, who believes he has everything after building a successful online casino business, loses it all to his former best friend and namesake, Park Taeyoung. The two reunite on the international poker circuit for a high-stakes battle of revenge.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ueigb5zra1tj6FTK9yhh2P33P9B.jpg', 'https://image.tmdb.org/t/p/w1280/w5OX3u2SpMVRU0sol0mtIaf4LSI.jpg', 7.3, 'qRIuZlQuh30', '2026-09-23', 5.618, 4, 'tt39233100', null, null, null, 'Kejahatan, Drama', '최국희', '최국희, 김현', '조혜정, 이진욱', 'Sidus, MCMC', '[{"name":"변요한","character":"Jang Taeyoung"},{"name":"노재원","character":"Park Taeyoung"},{"name":"三吉彩花","character":"Kaneko"},{"name":"조우진","character":"Kwak Dongwook"},{"name":"윤경호","character":"Cho Joonghwan"},{"name":"스윙스","character":"Abraham"},{"name":"Stephanie Lee","character":"Linda Park"},{"name":"김민호","character":"Hippo"},{"name":"임세미","character":"Jang Taehee"},{"name":"伊原剛志","character":"Sasaki"}]'::jsonb, '17+', null),
(1388805, 'LINKIN PARK: UNSHATTER', 'Musik', 108, 'NR', 'After a seven-year hiatus following the devastating loss of their beloved bandmate Chester Bennington, LINKIN PARK''S remaining members struggled to find their way forward. Their shared history and enduring friendship, combined with the fresh perspective of two new band members Emily Armstrong and Colin Brittain spark a renewed creative energy that leads them on a transformative journey of artistic reinvention. Following the band from intimate 2022 studio sessions through their explosive FROM ZERO album release and concert in São Paulo, this documentary weaves together rare vault footage, electrifying performances from sold-out shows, and candid interviews with band members and fans—capturing the raw, honest story of what it means to start over.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/kHNrz7DBVPrtyMhJxmBm2poS2l9.jpg', 'https://image.tmdb.org/t/p/w1280/uL1HCc4wmcFcSr1zS3kXX3CNUeE.jpg', 9.3, 'K9Lpxc7bVTM', '2026-09-30', 3.635, 14, 'tt43442522', 8.6, 875, null, 'Musik, Dokumenter', 'Joe Hahn', 'Igor Kovalik', 'Joe Hahn, Igor Kovalik, WL Boyd', 'CJ 4DPLEX, CJ 4DPLEX America, hungryman', '[{"name":"Mike Shinoda","character":"Self"},{"name":"Emily Armstrong","character":"Self"},{"name":"Joe Hahn","character":"Self"},{"name":"Dave Farrell","character":"Self"},{"name":"Colin Brittain","character":"Self"},{"name":"Alex Feder","character":"Self"},{"name":"Brad Delson","character":"Self"},{"name":"Mark Hoppus","character":"Self"}]'::jsonb, 'SU', null),
(1103857, 'Juliet & Romeo', 'Drama', 122, 'NR', 'Set at the dawn of the fourteenth century, a revisionist adaptation of history''s most celebrated star-crossed lovers rejects classical iambic pentameter in favor of a contemporary pop music score, charting their efforts to alter the course of their tragic destiny and expose a political truth crucial to the future of the Empire.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/4spOdjLgRAbIYO7mu22DQ2iInz7.jpg', 'https://image.tmdb.org/t/p/w1280/5vkYsIN0BpDlATvHCjufG5SimkU.jpg', 6, 'HLOfwe_0YsA', '2025-05-09', 3.709, 14, 'tt26597666', 3.9, 696, 'PG-13', 'Drama, Percintaan, Musik', 'Timothy Scott Bogart', 'Timothy Scott Bogart', 'Andrea Iervolino, Timothy Scott Bogart, Jessica Martins, Brad Bogart', 'Iervolino & Lady Bacardi Entertainment, Voltage Pictures, Hero Entertainment Partners', '[{"name":"Clara Rugaard","character":"Juliet Capulet"},{"name":"Jamie Ward","character":"Romeo Montague"},{"name":"Jason Isaacs","character":"Lord Montague"},{"name":"Dan Fogler","character":"The Apothecary"},{"name":"Rebel Wilson","character":"Lady Capulet"},{"name":"Rupert Everett","character":"Lord Capulet"},{"name":"Derek Jacobi","character":"The Friar"},{"name":"Lidia Vitale","character":"Lady Montague"},{"name":"Ferdia Walsh-Peelo","character":"Tybalt"},{"name":"Nicholas Podany","character":"Mercutio"}]'::jsonb, '13+', null),
(730251, 'HAPPYEND', 'Drama', 113, 'NR', 'In a near-future Japanese city bracing for a devastating earthquake, a group of teenage friends navigate personal struggles and fractured bonds amid rising tension.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/uaSmMj7kBP6elOp4CnpTsrF2AyL.jpg', 'https://image.tmdb.org/t/p/w1280/shWIpYYqbgpUUefpPj1VrYbPonE.jpg', 6.9, '8gWKm5eFo44', '2024-10-04', 4.007, 47, 'tt29279903', 6.8, 2304, null, 'Drama, Cerita Fiksi', '空音央', '空音央', 'Albert Tholen, Aiko Masubuchi, Alex C. Lo, 陳哲藝', 'Cineric Creative, Cinema Inutile, Zakkubalan, K-Garage', '[{"name":"栗原颯人","character":"Yūta"},{"name":"Yukito Hidaka","character":"Kō"},{"name":"林裕太","character":"Ata-chan"},{"name":"Shina Peng","character":"Ming"},{"name":"Arazi","character":"Tomu"},{"name":"祷キララ","character":"Fumi"},{"name":"中島歩","character":"Okada"},{"name":"矢作優","character":"Taira"},{"name":"PUSHIM","character":"Fukuko"},{"name":"渡辺真起子","character":"Yoko"}]'::jsonb, '13+', null),
(1433568, '粽邪4：坤蒂拉娜', 'Cerita Seru', 120, 'NR', 'When a forbidden Indonesian exorcism is broadcast live online, it unleashes a legendary demonic entity across Asia, forcing the grieving son of a Taiwanese victim to trace the curse back to its ancient, blood-soaked roots in rural Indonesia before it consumes everyone in its digital wake.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/6u8F23BammMeCWLvWITbFM2Nwbe.jpg', 'https://image.tmdb.org/t/p/w1280/2VDV1ZBHV1PKKBcWjRRCydZO1YR.jpg', null, null, '2026-08-27', 3.1, 0, 'tt38633224', null, null, null, 'Cerita Seru, Misteri, Kengerian', '廖士涵', '高鳴晟, 黃致凱', '鄒介中', 'WOWING Entertainment Group', '[{"name":"陳博正","character":""},{"name":"許安植","character":"Jia-min"},{"name":"陳雪甄","character":"Yu-Lan"},{"name":"劉國劭","character":"A-Guai"},{"name":"胡語恆","character":""},{"name":"Ferry Salim","character":""},{"name":"Rana Audi Marissa","character":""},{"name":"Fandy Christian","character":""},{"name":"Dito Darmawan","character":""},{"name":"Andovi da Lopez","character":""}]'::jsonb, null, null),
(1319525, 'จีบซ้ำซ้ำ เฮนรี่จำไม่ได้', 'Komedi', 115, 'NR', 'Lucy, a woman who''s living her first date on repeat with Henry, a good-natured, animal-loving guy with a bizarre condition: every time he wakes up, he can''t remember anything from the day before.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/qlw9WtySGW6AUdbkwgWUltvIAf3.jpg', 'https://image.tmdb.org/t/p/w1280/luQZKJZmp92kiwUZeXOpp0SrinL.jpg', 6, '2Ul_Vuzk1_g', '2026-09-17', 2.701, 2, 'tt37846333', 7.5, 135, null, 'Komedi, Percintaan', 'เมษ ธราธร', 'Benjamaporn Srabua, เมษ ธราธร, ทศพล ทิพย์ทินกร', 'วรรณฤดี พงษ์สิทธิ์ศักดิ์, เมษ ธราธร', 'GDH 559, Sony Pictures International Productions', '[{"name":"ณเดชน์ คูกิมิยะ","character":"Henry"},{"name":"มินนี่","character":"Lucy"},{"name":"เกียรติ กิจเจริญ","character":"Dad"},{"name":"เบิ้ล ปทุมราช","character":"Kanoon"},{"name":"ทิพากร ไชยประสิทธิ์","character":"Auntie Su"}]'::jsonb, '13+', null),
(1797226, '하이브 치어링 파티', 'Musik', 60, 'NR', 'The heat of cheering for HYBE artists unfolds in cinemas! Sing along with your favorite HYBE Artists in 3D! A one-of-a-kind game-like cheering screening is coming, where fans can chant fan cheers and wave their light sticks while watching the music videos of BTS, SEVENTEEN, TOMORROW X TOGETHER, ENHYPEN, LE SSERAFIM, &TEAM, BOYNEXTDOOR, TWS, ILLIT, KATSEYE, aoen, CORTIS, and SANTOS BRAVOS on the big screen. Join this unforgettable celebration filled with diverse music, passionate fan energy, and a dazzling wave of Light Sticks!', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/8udWFUoL5NxqKR1xtYinhcxY3gn.jpg', 'https://image.tmdb.org/t/p/w1280/rUzXvbNRIEs9r5qkh2reIGyPHCN.jpg', null, 'q0XKUFGn_M4', '2026-10-24', 1.901, 0, 'tt46659669', null, null, null, 'Musik', 'Park Sang-geun, Kim Jin-eui', null, 'Kim Ga-in', 'HYBE', '[{"name":"알엠","character":"Self (archive footage)"},{"name":"진","character":"Self (archive footage)"},{"name":"슈가","character":"Self (archive footage)"},{"name":"제이홉","character":"Self (archive footage)"},{"name":"지민","character":"Self (archive footage)"},{"name":"뷔","character":"Self (archive footage)"},{"name":"정국","character":"Self (archive footage)"},{"name":"에스쿱스","character":"Self (archive footage)"},{"name":"정한","character":"Self (archive footage)"},{"name":"조슈아","character":"Self (archive footage)"}]'::jsonb, '13+', null),
(791523, 'Wildwood', 'Animasi', 132, 'NR', 'After her baby brother is abducted by a murder of crows, headstrong teenager Prue McKeel launches a desperate rescue mission into the Impassable Wilderness, an enchanted forest hidden just beyond Portland, Oregon. Joined by her hapless but loyal classmate Curtis Mehlberg, Prue navigates a world of talking animals, bandits, and powerful figures driven by grief and ambition. As the pair is drawn into a conflict threatening the balance of the forest itself, Prue must discover the strength and belief she never knew she possessed.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/8g7q6o54WfKWRmUQ0Ye8OskevUY.jpg', 'https://image.tmdb.org/t/p/w1280/sl5NJ1vtyhP9Vr88bB4blULsJYp.jpg', 8.6, 'bJQGtSeLPII', '2026-10-19', 1868.814, 159, 'tt2056785', 8.7, 15186, 'PG-13', 'Animasi, Petualangan, Fantasi', 'Travis Knight', 'Chris Butler, Colin Meloy, Carson Ellis', 'Travis Knight, Arianne Sutner, Samuel Wilson', 'LAIKA', '[{"name":"Peyton Elizabeth Lee","character":"Prue McKeel (voice)"},{"name":"Jacob Tremblay","character":"Curtis Mehlberg (voice)"},{"name":"Carey Mulligan","character":"Alexandra (voice)"},{"name":"Mahershala Ali","character":"Brenden (voice)"},{"name":"Richard E. Grant","character":"Owl Rex (voice)"},{"name":"Angela Bassett","character":"The General (voice)"},{"name":"Awkwafina","character":"Septima (voice)"},{"name":"Amandla Stenberg","character":"Niamh (voice)"},{"name":"Tom Waits","character":"Maxim (voice)"},{"name":"Charlie Day","character":"Dmitri (voice)"}]'::jsonb, 'PG-13', 1168),
(1058424, 'Hope', 'Cerita Fiksi', 156, 'NR', 'Sebuah penemuan misterius terjadi di pinggiran kota pelabuhan kecil. Para penduduk mendapati diri mereka dalam kondisi perjuangan putus asa untuk bertahan hidup melawan sesuatu yang belum pernah mereka temui sebelumnya.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ptqlN6mDIAqJjVA86J5eOoG82zc.jpg', 'https://image.tmdb.org/t/p/w1280/j96rurZqmBjyY37Fncl3IB0qJNe.jpg', 6.8, 'OFaJzL83y0Q', '2026-07-15', 472.21, 448, 'tt27369017', 6.9, 4367, 'R', 'Cerita Fiksi, Misteri, Aksi', '나홍진', '나홍진', '나홍진, 김새미, Saerom Kim', 'Forged Films, Plus M Entertainment, Westworld Story', '[{"name":"황정민","character":"Go Bum-seok"},{"name":"조인성","character":"Go Sung-ki"},{"name":"정호연","character":"Lim Sung-ae"},{"name":"Alicia Vikander","character":"J''aur"},{"name":"Michael Fassbender","character":"Ma''veyyo"},{"name":"Taylor Russell","character":"Ai''dovor"},{"name":"Cameron Britton","character":"Va''migere"},{"name":"이상희","character":"Nak-yeon"},{"name":"음문석","character":"Yang-bae"},{"name":"임현식","character":"Hae-sul"}]'::jsonb, '13+', 2873),
(1596275, 'Drive – The Pretenders', 'Percintaan', 103, 'NR', 'A young mechanic fakes an engagement with racing''s most scandalous star — officially for his reputation, secretly for her own shot behind the wheel. But soon the lie threatens to destroy everything — including what''s already become so much more than just a deal.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/o1amTBOej7F2wdrTSKzGE6eG2CT.jpg', 'https://image.tmdb.org/t/p/w1280/hbz4aeVsjnKb2HRoFbbr46Egh8y.jpg', 7.7, '-sV69CJwUwU', '2026-10-27', 295.895, 93, 'tt37180686', null, null, null, 'Percintaan, Cerita Seru', 'Sergej Moya', 'Chris Silber, Malina Nwabuonwor, Tamara Lush', null, 'Bavaria Fiction', '[{"name":"Lisa-Marie Koroll","character":"Sarah Jenkins"},{"name":"Amin Baahmed","character":"Dante Annunziata"},{"name":"Gustav Schmidt","character":"Ruben Laroch"},{"name":"Mišel Matičević","character":"Alexander Bronson"},{"name":"Lucie Heinze","character":"Tanya Stein"},{"name":"Frederic Linkemann","character":"Jack Schroder"},{"name":"Inka Friedrich","character":"Irene Jenkins"},{"name":"Jeanette Hain","character":"Sofia Annunziata"},{"name":"Philippe Brenninkmeyer","character":"Dr. Frederic Richter"},{"name":"Leslie Malton","character":"Eva Maria Fischer"}]'::jsonb, 'R', 2446),
(1507696, 'Apocalipsis Z: Nuevo mundo', 'Aksi', 96, 'NR', 'The Canary Islands have become Europe’s last refuge following the outbreak of the TSJ virus. When a special mission sets out for the mainland in search of vital supplies, Roberto joins the team with questionable intentions. The dangerous operation turns into a desperate race for survival, and Roberto and his companions find themselves caught between hordes of infected and divided loyalties.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/c5LakPnLfzydW4YFUKfPeiODiWu.jpg', 'https://image.tmdb.org/t/p/w1280/o3XwuDUj0n8qnK91p6q8LKfr6rj.jpg', 6, 'BIEzwpyawtw', '2026-10-09', 293.603, 79, 'tt37522541', null, null, null, 'Aksi, Cerita Seru, Kengerian', 'Carles Torrens', 'Manel Loureiro, Ángel Agudo', 'Adrián Guerra, Núria Valls', 'Nostromo Pictures', '[{"name":"Carlos Alcaide","character":"Roberto"},{"name":"Julia Martínez","character":"Marina"},{"name":"José María Yázpik","character":"Pritchenko"},{"name":"Mónica López","character":"Castro"},{"name":"Tamara Casellas","character":"Comillas"},{"name":"Berta Vázquez","character":"Lucía"},{"name":"Santiago Vaca Narvaja","character":"Core"},{"name":"Mario Mayo","character":"Comandante De Luna"},{"name":"Javier Godino","character":"González-Escalona"},{"name":"Pedro Hernández","character":"Guzmán"}]'::jsonb, 'R', 2977),
(1101412, 'Fall 2: Deadpoint', 'Cerita Seru', 98, 'NR', 'On a perilous climb across Thailand''s Mount Kwan, two climbers become trapped thousands of feet above the ground, where vertigo-inducing heights, sheer exposure, and impossible odds turn every moment into a fight for survival.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/fgSm5ylwiXbIHn8UbUXDjk9RRu4.jpg', 'https://image.tmdb.org/t/p/w1280/nGau0KBOaRILSK5MqFcuTfv7GMl.jpg', 7.3, 'Krs0VDIjhmE', '2026-09-01', 249.529, 735, 'tt31192372', 5.7, 1565, 'PG-13', 'Cerita Seru', 'Michael Spierig, Peter Spierig', 'Scott Mann, Jonathan Frank', 'Mark Lane, James Harris, Christian Mercuri, Scott Mann', 'Tea Shop Productions, Capstone Pictures, Flawless Production, Cousin Jones', '[{"name":"Harriet Slater","character":"Jax Hunter"},{"name":"Arsema Thomas","character":"Luce"},{"name":"Tom Brittney","character":"Jon Platt"},{"name":"สหจักร บุญธนกิจ","character":"Thai Barman"},{"name":"Korakod Yensuk","character":"Large Woman"},{"name":"Jordan Coleman","character":"Real Luce"},{"name":"Maryna Bennett","character":"Female Teenager"},{"name":"Noen Perez","character":"Male Teenager"},{"name":"Nattapon Sukphiam","character":"Thai Climber 1"},{"name":"Charlie Ruedpokanon","character":"Thai Climber 2"}]'::jsonb, '17+', 1390),
(1657630, 'El despertar', 'Kengerian', 96, 'NR', 'An elite military unit on a mission in the South American jungle encounters a deadly supernatural force revealing an ancient presence that continues to claim anyone who dares enter its domain.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/w3YJx1PPPC6aiVKusxfc9QA0uYS.jpg', 'https://image.tmdb.org/t/p/w1280/4pYKqctQvvdyhuGjiK4szH9jEv9.jpg', 6.6, 'hj6Cer6bJUI', '2026-10-29', 243.753, 90, 'tt39120306', null, null, null, 'Kengerian, Aksi, Kejahatan, Fantasi, Cerita Seru', 'Jaime Osorio Márquez', 'Jaime Osorio Márquez', 'Luis F Peraza, Gabriela Remirez, Paul Drago, Roberto Rios', 'Rhayuela Films', '[{"name":"Claudio Cataño","character":""},{"name":"Alejandro Buitrago","character":""},{"name":"Hector Sánchez","character":""},{"name":"Andrea Olaya","character":""},{"name":"Quique Sanmartin","character":""},{"name":"Jaisson Jeack","character":""},{"name":"Carlos Mariño","character":""},{"name":"Andres Londono","character":""},{"name":"Salvador Bridges","character":""},{"name":"Sebastian Velasquez","character":""}]'::jsonb, 'NR', null),
(1514026, 'Buddy', 'Kengerian', 96, 'NR', 'Inside the colorful world of "It''s Buddy!", a group of children spend their days singing, dancing, and helping Buddy - bright orange unicorn - spread happiness. But when one child refuses to play along, Buddy is not pleased and cracks begin to appear in this seemingly perfect world.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/1BdZbNvl1SfrrX8J9X5tQzN6Ivu.jpg', 'https://image.tmdb.org/t/p/w1280/ytoLEl5yDaxB8AtZ52uKWjaQ9ql.jpg', 7, null, '2026-08-27', 191.571, 231, 'tt37281055', 7.1, 5019, 'R', 'Kengerian, Komedi, Fantasi', 'Casper Kelly', 'Casper Kelly, Jamie King', 'Tyler Davidson, J.D. Lifshitz, Raphael Margules, Drew Sykes', 'BoulderLight Pictures, Low Spark Films, SIPUR, Substance', '[{"name":"Keegan-Michael Key","character":"Buddy / Dark Buddy (voice)"},{"name":"Delaney Quinn","character":"Freddy"},{"name":"Tristan Borders","character":"Oliver"},{"name":"Madison Skyy Polan","character":"Hannah"},{"name":"Caleb Williams","character":"Wade"},{"name":"Cristin Milioti","character":"Grace"},{"name":"Topher Grace","character":"Ben"},{"name":"Patton Oswalt","character":"Strappy (voice)"},{"name":"Michael Shannon","character":"Willie (voice)"},{"name":"Clint Howard","character":"George"}]'::jsonb, 'R', 3466),
(1232569, 'Pinocchio: Unstrung', 'Kengerian', 82, 'NR', 'Influenced by a sinister Cricket and created by Geppetto, Pinocchio launches a violent crusade to carve himself into a real boy like his brother James, one piece at a time.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/hJNdizFlxOW89edX3Rzr6OliSFI.jpg', 'https://image.tmdb.org/t/p/w1280/7RsPdXLDNugDIlwXPVeeprNfMx.jpg', 6.4, 'Y4lZewE6JMI', '2026-07-22', 167.151, 156, 'tt30887701', 5.4, 4534, 'R', 'Kengerian, Fantasi, Misteri', 'Rhys Frake-Waterfield', 'Carlo Collodi, Rhys Frake-Waterfield', 'Scott Chambers, Rhys Frake-Waterfield', 'Jagged Edge Productions', '[{"name":"Jude Evan Lloyd","character":"Pinocchio (voice)"},{"name":"Cameron Bell","character":"James"},{"name":"Richard Brake","character":"Geppetto"},{"name":"Jessica Balmer","character":"Mia"},{"name":"Jack Art Gray","character":"Dudley"},{"name":"Robert Englund","character":"Cricket (voice)"},{"name":"Emma Tate","character":"Woodmother (voice)"},{"name":"Toni Olabanji","character":"Trey"},{"name":"Luca Marandola","character":"Logan"},{"name":"Karolina Ugrenyuk","character":"Amanda"}]'::jsonb, 'R', null),
(1294189, 'The Mongoose', 'Aksi', 99, 'NR', 'A falsely accused war hero with nothing to lose leads police on an epic televised cross-country car chase, helped by members of his former Special Forces Army battalion and closely monitored by a fascinated public rooting for his safe getaway.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/eSS5mvSG84UUuvtbHel5Yu3Wik4.jpg', 'https://image.tmdb.org/t/p/w1280/iRIhPqqoUHiFBxn8oYf3gCQnaKk.jpg', 7.5, 'aHrMFtt40_Q', '2026-10-29', 160.603, 11, 'tt13611778', null, null, null, 'Aksi, Cerita Seru', 'Mark Vanselow', 'Thompson Evans', 'Al Corley, Eugene Musso, Bart Rosenblatt', 'Code Entertainment, The Solution', '[{"name":"Liam Neeson","character":"Ryan ''Fang'' Flanagan"},{"name":"Marisa Tomei","character":"Tara"},{"name":"Ving Rhames","character":"Tanker"},{"name":"Marcus Thomas","character":"Munch"},{"name":"Michael Chiklis","character":"Major Walter Pope"},{"name":"Maurice Marvel Meredith","character":"Major James Tilton"},{"name":"Brett Tucker","character":"Todd"},{"name":"Ryan Morgan","character":"Wiz"},{"name":"Laura Coates","character":"Laura Coates"},{"name":"Geoff Morrell","character":"Ernie"}]'::jsonb, 'R', 919),
