(1571955, 'Colisión', 'Cerita Seru', 122, 'NR', 'Spain, 2013. After robbing a bank, a getaway crash reveals the hidden side of each thief, exposing betrayals and lies that began long before the heist.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/sMPIiaOoyTr5o6s602KIVMJX3P2.jpg', 'https://image.tmdb.org/t/p/w1280/uI3kWI7kGW5E0F8WduewgQYPt34.jpg', 6.6, '8hVLhaK619k', '2026-10-30', 153.101, 40, 'tt38793125', null, null, null, 'Cerita Seru, Drama, Kejahatan', 'Daniel Sánchez Arévalo', 'Daniel Sánchez Arévalo, Ramón Campos', 'Ramón Campos, Víctor Fandiño', 'Bambú Producciones', '[{"name":"Laia Costa","character":"Carla Mencía"},{"name":"Karra Elejalde","character":"Pedro"},{"name":"Luis Zahera","character":"Ernesto"},{"name":"Tamar Novas","character":"Tomás"},{"name":"Álvaro Cervantes","character":"Raúl"},{"name":"Lluís Homar","character":"Luis"},{"name":"Luz Valdenebro","character":"Lola"},{"name":"Víctor Duplá","character":"Pablo"},{"name":"Jorge Cabrera","character":"Turrientes"},{"name":"Mónica Miranda","character":"Lucía"}]'::jsonb, 'R', 841),
(1228834, 'The Fix', 'Aksi', 142, 'NR', 'Disillusioned by the end of the war in Afghanistan, a group of disgraced, war-torn ex-CIA operatives set out to Tehran to take down a life-changing score.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/jlP8XDjZN89GrpM3je5Uf8Grqx8.jpg', 'https://image.tmdb.org/t/p/w1280/dJTWIecL2vxsCRl5G0lRhPsfrhc.jpg', 6.1, 'l5Luvr9TRRc', '2026-09-10', 132.042, 85, 'tt9601292', null, null, null, 'Aksi, Cerita Seru', 'Guy Moshe', 'Guy Moshe, Mark Bacci', 'Bazzel Baz, Wendy Hinton Sweetmore, Matthew G. Zamias, Marina Grasic', 'Astral Future, Dreamtime Entertainment, Oakhurst Entertainment, BondIt Media Capital', '[{"name":"Zachary Levi","character":"Tucker"},{"name":"Liam Neeson","character":"Larry"},{"name":"Wes Chatham","character":"Alex"},{"name":"Titus Welliver","character":"James"},{"name":"Navid Negahban","character":"Qasim"},{"name":"Annet Mahendru","character":"Sophie"},{"name":"Grant Harvey","character":"Matt"},{"name":"Augusto Aguilera","character":"Bruce"},{"name":"Numan Acar","character":"Nadir"},{"name":"Elnaaz Norouzi","character":"Zara"}]'::jsonb, 'R', 631),
(1376400, 'Crawlers', 'Kengerian', 80, 'NR', 'Tenants at Paradiso Palms apartments fight a deadly spider invasion while the cunning building manager might be their only hope for survival.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/lNXeEpg4yLSRwXwOeR5lbPgwbqL.jpg', 'https://image.tmdb.org/t/p/w1280/ayJsUQ4bEG6yY0UB6lMboiaDfYE.jpg', 6.2, '4DowjB87tRE', '2026-09-24', 131.312, 49, 'tt32329539', 4.8, 72, 'R', 'Kengerian, Cerita Seru', 'Ángel Gómez Hernández', 'Jayson Rothwell', 'Alexandra Milchan, Jayson Rothwell, Andrew Schwartzberg, Jon Shiffman', 'Badlands, Thunder Road, Sagesse Productions, Fresco Film', '[{"name":"Matilda Lutz","character":"Serena"},{"name":"Gary Anthony Stennette","character":"Dr. Woodward"},{"name":"Elena Sanz","character":"Dr. Callan"},{"name":"Andrea Scott Méndez","character":"Molly"},{"name":"Isabella Marie Egizi","character":"Bernice"},{"name":"Sam Lucas Smith","character":"Lance"},{"name":"Gregg Sulkin","character":"Bradley"},{"name":"Melina Matthews","character":"Lady Lash"},{"name":"William Miller","character":"Mr. Rossmore"},{"name":"Lex Salvador","character":"Tonya"}]'::jsonb, 'R', 684),
(1148365, 'Matchbox the Movie', 'Aksi', 127, 'NR', 'Ketika sekelompok mantan teman masa kecil bertemu kembali, reuni mereka menjadi kacau saat tak sengaja menemukan konspirasi internasional yang berbahaya dan kini mereka harus menyelamatkan dunia.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/aHhHRz6nOpwkqJs5ASeRGAdK2dt.jpg', 'https://image.tmdb.org/t/p/w1280/jdJsnhHfkIi3J7jwfiCFT4gXNx5.jpg', 7.6, '7xfqITrMDcI', '2026-10-05', 119.573, 585, 'tt28498219', null, null, 'PG-13', 'Aksi, Komedi, Petualangan', 'Sam Hargrave', 'David Coggeshall', 'Dana Goldberg, David Ellison, Robbie Brenner, Don Granger', 'Mattel Studios, Skydance Media', '[{"name":"John Cena","character":"Sean"},{"name":"Jessica Biel","character":"Aimee"},{"name":"Arturo Castro","character":"Ted"},{"name":"Sam Richardson","character":"Crosby"},{"name":"Teyonah Parris","character":"Charmaine"},{"name":"Danai Gurira","character":"Helen"},{"name":"گلشیفته فراهانی","character":"Robbie"},{"name":"Corey Stoll","character":"Mosier"},{"name":"Daniel Bernhardt","character":"Falko"},{"name":"Randeep Hooda","character":"Mustafa"}]'::jsonb, '17+', 1946),
(9479, 'The Nightmare Before Christmas', 'Fantasi', 76, 'NR', 'Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack''s rag-doll girlfriend, Sally, tries to foil his misguided plans.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', 'https://image.tmdb.org/t/p/w1280/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', 7.9, 'IoYahD_xNR0', '1993-10-09', 127.361, 10872, 'tt0107688', 7.9, 416592, 'PG', 'Fantasi, Animasi, Keluarga', 'Henry Selick', 'Caroline Thompson, Tim Burton', 'Tim Burton, Denise Di Novi, Don Hahn', 'Touchstone Pictures, Skellington Productions', '[{"name":"Danny Elfman","character":"Jack Skellington (singing) / Barrel / Clown with the Tear away Face (voice)"},{"name":"Chris Sarandon","character":"Jack Skellington (voice)"},{"name":"Catherine O''Hara","character":"Sally / Shock (voice)"},{"name":"William Hickey","character":"Dr. Finkelstein (voice)"},{"name":"Glenn Shadix","character":"Mayor (voice)"},{"name":"Paul Reubens","character":"Lock (voice)"},{"name":"Ken Page","character":"Oogie Boogie (voice)"},{"name":"Edward Ivory","character":"Santa Claus (voice)"},{"name":"Susan McBride","character":"Big Witch / WWD. (voice)"},{"name":"Debi Durst","character":"Corpse Kid / Corpse Mom / Small Witch (voice)"}]'::jsonb, 'PG', 2128),
(1780005, 'Contra el huracán', 'Drama', 97, 'NR', 'Two estranged brothers struggle to survive Hurricane Otis in Acapulco, where their bond and courage turn adversity into hope.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/lFaMt4I8LiQAGW9Rb5gfGFXbvOY.jpg', 'https://image.tmdb.org/t/p/w1280/cpNMIRCrDl0sxDL1tHBzfWi0UZC.jpg', 7.6, 'qC0HZLUXRXw', '2026-10-23', 124.392, 113, 'tt37961714', null, null, null, 'Drama', 'Jorge Michel Grau', 'Venancio Villalobos, Jorge Michel Grau, Jose Leonor Alejandro', null, 'Perro Azul', '[{"name":"Benny Emmanuel","character":"Wirpul"},{"name":"Kristyan Ferrer","character":"Candi"},{"name":"Mónica del Carmen","character":""},{"name":"Mónica Jiménez","character":""},{"name":"Andrew Leland Rogers","character":"Nico"},{"name":"Gonzalo Vega Jr.","character":"Napo"},{"name":"Daira Mendoza","character":"Mujer Turista"}]'::jsonb, 'R', 781),
(1204680, 'Coyote vs. Acme', 'Komedi', 103, 'NR', 'After Acme products fail him one too many times in his dogged pursuit of the Roadrunner, Wile E. Coyote decides to hire a billboard lawyer to sue the Acme Corporation.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg', 'https://image.tmdb.org/t/p/w1280/rueyXwlewVPAP5NkqCUJx4RjhqB.jpg', 8.2, 'kMsiD1Nky5I', '2026-08-20', 119.108, 1278, 'tt1756855', 7.6, 18537, 'PG', 'Komedi, Petualangan, Keluarga, Animasi', 'Dave Green', 'Samy Burch', 'Christopher DeFaria, James Gunn', 'Troll Court Entertainment, Keylight Pictures, Warner Animation Group, Warner Bros. Pictures', '[{"name":"Will Forte","character":"Kevin Avery"},{"name":"Lana Condor","character":"Paige Avery"},{"name":"John Cena","character":"Buddy Crane"},{"name":"Tone Bell","character":"Sal Maltese"},{"name":"Martha Kelly","character":"Dottie Jones"},{"name":"Luis Guzmán","character":"Judge Troppogrosso"},{"name":"P.J. Byrne","character":"Bill Pellicanos"},{"name":"John Early","character":"Henry Heslop"},{"name":"Nancy Linehan Charles","character":"Cherry"},{"name":"Kenneth Choi","character":"Oscar Jeon"}]'::jsonb, 'PG', 2089),
(1727734, 'Ali G: Who Iz I?', 'Komedi', 89, 'NR', 'After twenty years spent "chillin'', tokin'' and bonin''", Ali G is shocked to discover that his long-term girlfriend, Julie, is 8 months pregnant. Faced with an extra mouth to feed, he gets off his batty and heads to America to reclaim his former glory… but soon encounters adversaries who will ultimately threaten his and his child''s very existence.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/uTyVxPeWX8Ai30IQoyDDQONNcq.jpg', 'https://image.tmdb.org/t/p/w1280/hJcGJLi34zE4RhzsiDR6f7pw50K.jpg', 5.8, 'pV32AcPa-iA', '2026-10-22', 111.794, 126, 'tt43655467', null, null, 'R', 'Komedi', 'Sacha Baron Cohen', 'Sacha Baron Cohen, Anthony Hines, Peter Baynham, Dan Swimer', 'Sacha Baron Cohen, Dan Mazer, Andrew Eaton, Kevin Loader', 'Four by Two Films, Amazon MGM Studios, Working Title', '[{"name":"Sacha Baron Cohen","character":"Ali G / Nira Cain-N''Degeocello / Erran Morad"},{"name":"Morgana Robinson","character":"Julie"},{"name":"Alpha Miknas","character":"Manu"},{"name":"Clive Russell","character":"Malcolm ''Rocky'' Atkins"},{"name":"A$AP Rocky","character":"A$AP Rocky"},{"name":"Rihanna","character":"Rihanna"},{"name":"Tiffany Haddish","character":"Lab Technician"},{"name":"DJ Jazzy Jeff","character":"DJ Jazzy Jeff"},{"name":"C. Stewart Rodeheaver","character":"(uncredited)"},{"name":"Allan Lichtman","character":"(uncredited)"}]'::jsonb, 'R', 5787),
(1339713, 'Obsession', 'Kengerian', 109, 'NR', 'Setelah menghancurkan "One Wish Willow" yang misterius untuk memenangkan hati gebetannya, seorang romantis yang putus asa menemukan dirinya mendapatkan apa yang dia minta tetapi segera menemukan bahwa beberapa keinginan datang dengan harga yang gelap dan menyeramkan.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', 'https://image.tmdb.org/t/p/w1280/5lTZyuBTNOfawsfPT8Q0cIg6qAF.jpg', 8.2, 'gMC8kkwbIQQ', '2026-05-13', 116.54, 6469, 'tt37287335', 7.8, 392842, 'R', 'Kengerian, Cerita Seru', 'Curry Barker', 'Curry Barker', 'James Harris, Christian Mercuri, Haley Nicole Johnson, Roman Viaris-de-Lesegno', 'Tea Shop Productions, Under the Shell, Capstone Pictures, Blumhouse Productions', '[{"name":"Michael Johnston","character":"Bear"},{"name":"Inde Navarrette","character":"Nikki"},{"name":"Cooper Tomlinson","character":"Ian"},{"name":"Megan Lawless","character":"Sarah"},{"name":"Andy Richter","character":"Carter"},{"name":"Haley Fitzgerald","character":"Viola"},{"name":"Darin Toonder","character":"Harry"},{"name":"Anthony Pavone","character":"Reggie"},{"name":"Justice","character":"Joe"},{"name":"Anthony Casabianca","character":"Chris"}]'::jsonb, '17+', 3070),
