(1561726, 'Masterplan', 'Aksi', 110, 'NR', 'Saat seorang pencuri legendaris mengincar Mona Lisa, dia merekrut dua orang asing: Chiara, pakar kejahatan siber asal Italia, dan Jay, ahli bahan peledak asal Prancis. Dia lalu mengaku sebagai ayah mereka. Terjebak dalam reuni keluarga yang kacau, keluarga baru ini harus belajar bekerja sama dan berusaha tak saling bunuh demi melancarkan pencurian terbesar abad ini.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/5xmXVd7nCK3tAo34XkO58SxUCip.jpg', 'https://image.tmdb.org/t/p/w1280/fAlQZsCOCvxOj0PmFmt4i8IWR2u.jpg', 6.9, 'gc0t8AfMP6k', '2026-10-16', 101.287, 220, 'tt38672588', null, null, null, 'Aksi, Cerita Seru', 'Thomas Vincent', 'Giacomo Durzi, Alessandro Fabbri, Alberto Vignati, Thomas Vincent', 'Sidonie Dumas', 'Amazon MGM Studios, Gaumont', '[{"name":"Stanley Tucci","character":"Roger"},{"name":"Simona Tabasco","character":"Chiara"},{"name":"Victor Belmondo","character":"Jay"},{"name":"Eliott Margueron","character":""},{"name":"Barbara Lo Gaglio","character":"Professor"},{"name":"Etienne Guillou-Kervern","character":"French Spook Officer"},{"name":"Srbo Markovic","character":"Bruno''s Bodyguard"},{"name":"Julia Messina","character":"TV Reporter"},{"name":"מארק איווניר","character":"Bruno"}]'::jsonb, 'R', 1934),
(1288445, 'Mutiny', 'Aksi', 96, 'NR', 'After witnessing his billionaire boss'' murder and being framed for the crime, Cole Reed boards a cargo ship on a one-man crusade to avenge his boss'' death only to discover an international conspiracy.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/pu2VxGlpGwffOx292w18b1tv96j.jpg', 'https://image.tmdb.org/t/p/w1280/e2QAGrEmbpmZpMymDRkDisJkvg9.jpg', 7.7, '2Iqvbe98Gb4', '2026-08-19', 95.444, 1016, 'tt32338669', 5.7, 17192, 'R', 'Aksi, Cerita Seru', 'Jean-François Richet', 'Lindsay Michel, J.P. Davis', 'Jason Statham, Marc Butan', 'Punch Palace Productions, MadRiver Pictures', '[{"name":"Jason Statham","character":"Cole Reed"},{"name":"Annabelle Wallis","character":"Angie Ellis"},{"name":"Roland Møller","character":"Captain Marko Madsen"},{"name":"Ramon Tikaram","character":"Tibu Campallo"},{"name":"Arnas Fedaravičius","character":"Mateo Pineda"},{"name":"Jason Wong","character":"Taran"},{"name":"Adrian Lester","character":"Captain Adam Spencer"},{"name":"Chaneil Kular","character":"Kameron Campallo"},{"name":"Andrew John Tait","character":"BK Lobby Businessman"},{"name":"Simon Kluth","character":"Jaran Daniles"}]'::jsonb, '17+', 966),
