(1290418, 'The Cycle', 'Kengerian', 111, 'NR', 'A daughter unravels her father''s dark past after his body, missing for 36 years, is found at a horrific crime scene.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/n5gSNf55KWfDc9hqP4H1KCCSutE.jpg', 'https://image.tmdb.org/t/p/w1280/bgHW6AJl2SdKzxglvf9tshXbI84.jpg', 6.7, 'm8vcBN8uza8', '2026-09-24', 81.254, 112, 'tt32358390', null, null, null, 'Kengerian, Cerita Seru, Misteri', 'Jordan Downey', 'Jordan Downey, Kevin Stewart', 'Michael W. Downey, James Harris, Mark Lane', 'Tea Shop Productions, Buffalo 8, BondIt Media Capital', '[{"name":"Deborah Ann Woll","character":"Meg"},{"name":"Jeffrey Donovan","character":"Marks"},{"name":"Gretchen Corbett","character":"Joni"},{"name":"Jack Doolan","character":"Lenny"},{"name":"Will Hochman","character":"Ian"},{"name":"Dana Millican","character":"Fran"},{"name":"Phillip Andre Botello","character":"Daniel"},{"name":"Don Keith Opper","character":"Frank"},{"name":"Carl W. Crudup","character":"Lou Bishop"},{"name":"Danika Golombek","character":"Katie"}]'::jsonb, 'R', 3493),
(1629051, 'ネバーアフターダーク', 'Kengerian', 104, 'NR', 'A traveling psychic who helps lost souls cross over encounters a powerful entity at a remote house. While investigating its origins, she uncovers dark secrets and faces a deadly threat from an unexpected source.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/4rDgzOCBREeTaqZvTeFtEcnrju8.jpg', 'https://image.tmdb.org/t/p/w1280/o73vpmtXq89bfSUMcAulLVN4TKP.jpg', 7.3, 'fu33xTw654A', '2026-06-05', 94.335, 22, 'tt38589433', null, null, null, 'Kengerian', 'Dave Boyle', 'Dave Boyle', '賀来賢人, Dave Boyle, Kosuke Tsutsumi', 'signal181, United Lounge Tokyo, TOHO Next, XYZ Films', '[{"name":"穂志もえか","character":"Airi"},{"name":"稲垣来泉","character":"Miku"},{"name":"賀来賢人","character":"Gunji"},{"name":"木村多江","character":"Teiko"},{"name":"吉岡睦雄","character":"Mysterious Man"},{"name":"正名僕蔵","character":"Police Officer"}]'::jsonb, null, 664),
(1503762, 'Sense and Sensibility', 'Percintaan', 132, 'NR', 'A charming, witty, and deeply relatable story of love and sisterhood.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/czsyPHosFNbh4PPqXfqWu1aBXnA.jpg', 'https://image.tmdb.org/t/p/w1280/tIcONOFK9D3F89ETK8DBS1hIwVF.jpg', 7.2, 'OFLyW0lxFU0', '2026-09-23', 83.752, 128, 'tt13609648', 7.2, 1752, 'PG', 'Percintaan, Drama, Sejarah', 'Georgia Oakley', 'Jane Austen, Diana Reid', 'Tim Bevan, Eric Fellner, India Flint, Jo Wallett', 'Focus Features, Working Title, November Pictures, Kiddo Films', '[{"name":"Daisy Edgar-Jones","character":"Elinor Dashwood"},{"name":"Esmé Creed-Miles","character":"Marianne Dashwood"},{"name":"Caitríona Balfe","character":"Mrs. Dashwood"},{"name":"Frank Dillane","character":"John Willoughby"},{"name":"Herbert Nordrum","character":"Colonel Brandon"},{"name":"George MacKay","character":"Edward Ferrars"},{"name":"Fiona Shaw","character":"Mrs. Jennings"},{"name":"Bodhi Rae Breathnach","character":"Margaret Dashwood"},{"name":"Stacy Martin","character":"Fanny Dashwood"},{"name":"Tom Brooke","character":"John Dashwood"}]'::jsonb, 'PG', 1391),
(1377237, 'Runner', 'Aksi', 97, 'NR', 'A former soldier is thrown into a brutal race against time when a critical medical delivery makes him and his unlikely partner the targets of a ruthless cartel. As the mission spirals into a deadly manhunt, every detour, delay, and bullet pushes them closer to failure. With betrayal closing in from every side, they must survive the chase and deliver their cargo to save the life of a little girl.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/vJk2TW1QZAmBiD7oj9ZF9EPTYY1.jpg', 'https://image.tmdb.org/t/p/w1280/npXZNWjOEYrqdMDPQ11SGBrXqAG.jpg', 8.3, 'B6Z9MM1LhEA', '2026-09-07', 88.169, 789, 'tt31349844', 6.6, 493, 'PG-13', 'Aksi, Komedi', 'Scott Waugh', 'Tommy White, Miles Hubley', 'Todd Garner, Alan Ritchson, Mark Fasano, Jeffrey Greenstein', 'Broken Road Productions, AllyCat Entertainment, Nickel City Pictures, A Higher Standard', '[{"name":"Alan Ritchson","character":"Hank Malone"},{"name":"Owen Wilson","character":"Ben Bishop"},{"name":"Rodrigo Santoro","character":"Damian Zaldivar"},{"name":"Leila George","character":"Kate Baker"},{"name":"Kate Box","character":"Dr. Ainsley"},{"name":"Peta Sergeant","character":"Nurse Julie"},{"name":"Cecilia Toussaint","character":"Donna Zaldivar"},{"name":"Geraldine Hakewill","character":"Monica"},{"name":"Goran D. Kleut","character":"Luke"},{"name":"Scarlett Crabtree","character":"Ellie Baker"}]'::jsonb, '17+', 2777),
(1765072, 'You Can See Everything', 'Dokumenter', 174, 'NR', 'Thirty-four days before she''s sent to prison, notorious Silicon Valley founder Elizabeth Holmes invites a skeptical film crew to document her every move. What begins as an intimate portrait of an enigmatic felon becomes a mind-bending three-year journey into the abyss.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/Ap8QwmKfSjYbWC4XIP8w9pdn72O.jpg', 'https://image.tmdb.org/t/p/w1280/nhIL3O4W9h5V5JbNQm7yjoDk3So.jpg', 8.9, 'IEx8D1Wb__U', '2026-10-16', 79.501, 76, 'tt45368240', 7.9, 165, 'R', 'Dokumenter', 'Nathan Fielder, Lance Oppenheim', null, 'Lance Oppenheim, Nathan Fielder, Tatiana Bears, Maggie Ambrose', 'Blow Out Productions, To Be Formed, A24', '[{"name":"Elizabeth Holmes","character":"Self"},{"name":"Nathan Fielder","character":"Self"},{"name":"Billy Evans","character":"Self"},{"name":"Amanda Seyfried","character":"Self / Elizabeth Holmes"},{"name":"Christopher Abbott","character":"Billy Evans"},{"name":"Lance Oppenheim","character":"Self"},{"name":"Christian Rasmus Holmes IV","character":"Self"},{"name":"Noel Anne","character":"Self"},{"name":"Gary Wilmes","character":"A24 Executive"},{"name":"Phillip Andre Botello","character":"A24 Executive"}]'::jsonb, 'R', 1382),
(1187326, 'Tadeo Jones y La Lámpara Maravillosa', 'Animasi', 94, 'NR', 'Tadeo, his girlfriend Sara, and his friends Momia, Jeff, and Belzoni embark on an adventure after Tadeo accidentally unleashes an ancient spell.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/71G1b8bqa7gzP9yU7q2fgNf2t0D.jpg', 'https://image.tmdb.org/t/p/w1280/zbpimMxf6Ms96v3Zypuv8WltMSO.jpg', 8.2, '8-Bjo_rXCkM', '2026-08-26', 84.167, 84, 'tt36164852', 6.5, 184, null, 'Animasi, Komedi, Keluarga', 'Enrique Gato', 'Josep Gatell, Manuel Burque', null, 'Mediaset España, Ikiru Films, Anangu Grup, Lightbox Animation Studios', '[{"name":"Óscar Barberán","character":"Tadeo Jones (voice)"},{"name":"Michelle Jenner","character":"Sara Lavrof (voice)"},{"name":"Luis Posada","character":"Momia (voice)"},{"name":"Joseph Balderrama","character":"Mummy / Tupac (voice)"},{"name":"Trevor White","character":"Tad (voice)"}]'::jsonb, null, null),
(1275779, 'Disclosure Day', 'Cerita Fiksi', 146, 'NR', 'Jika Anda mengetahui bahwa kita tidak sendirian, jika seseorang menunjukkannya kepada Anda, membuktikannya kepada Anda, apakah itu akan membuat Anda takut?', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/AnJ8IQJI23hNpYXVNaythu061Ru.jpg', 'https://image.tmdb.org/t/p/w1280/1e0KDRYKRPHiVNj8yQKYuU2jVyQ.jpg', 7.4, 'icDuEHSxE-w', '2026-06-10', 80.234, 3934, 'tt15047880', 6.4, 164418, 'PG-13', 'Cerita Fiksi, Cerita Seru', 'Steven Spielberg', 'Steven Spielberg, David Koepp', 'Kristie Macosko Krieger, Steven Spielberg', 'Universal Pictures, Amblin Entertainment', '[{"name":"Emily Blunt","character":"Margaret Fairchild"},{"name":"Josh O''Connor","character":"Dr. Daniel Kellner"},{"name":"Colin Firth","character":"Noah Scanlon"},{"name":"Eve Hewson","character":"Jane Blakenship"},{"name":"Colman Domingo","character":"Hugo Wakefield"},{"name":"Wyatt Russell","character":"Jackson"},{"name":"Henry Lloyd-Hughes","character":"Casper Boyd"},{"name":"Elizabeth Marvel","character":"Sister Maura"},{"name":"Hettienne Park","character":"Serena"},{"name":"Tommy Martinez","character":"Santiago"}]'::jsonb, '13+', 1473),
(1284046, 'Onslaught', 'Aksi', 92, 'NR', 'When a rogue squad of genetically engineered super soldiers break loose in the desert, a badass Army sniper must unleash hell to protect her young daughter.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/eAs7G3yFaULpfwfVdGvPo5HmFJS.jpg', 'https://image.tmdb.org/t/p/w1280/pmPXXniQlb4EdYY0gVZO90rf54F.jpg', 5.6, 'AMLCbpM1fRQ', '2026-09-02', 74.585, 140, 'tt32268691', 6.2, 1404, 'R', 'Aksi, Cerita Seru, Kengerian', 'Adam Wingard', 'Simon Barrett, Adam Wingard', 'Jeremy Platt, Alexander Black, Simon Barrett, Andrew Swett', 'A24, Ryder Picture Company, Lyrical Media, Breakaway Civilization', '[{"name":"Adria Arjona","character":"Celeste"},{"name":"Dan Stevens","character":"Hans Kammler"},{"name":"Eric Wareheim","character":"Kovacks"},{"name":"Reginald VelJohnson","character":"Josiah"},{"name":"Michael Biehn","character":"Baylor"},{"name":"Blake Kennedy","character":"Daisy"},{"name":"Alex Pereira","character":"The Butcher"},{"name":"Drew Starkey","character":"Cyrus"},{"name":"Rebecca Hall","character":"Hanna Kammler"},{"name":"Jacob Scipio","character":"Griffin"}]'::jsonb, 'R', null),
(1375646, '군체', 'Kengerian', 123, 'NR', 'Professor Se-jeong is thrust into a bloody nightmare when a rapidly mutating virus is released during a biotech conference causing authorities to seal the facility. Trapped inside with no escape, Se-jeong along with a small group of survivors must fight to stay alive while the infected undergo horrific transformations.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/hDPGsJxo8xX0OyqcMB8xI3RdaF3.jpg', 'https://image.tmdb.org/t/p/w1280/iGViga8sDCET1S6GfwOlAbuhSGQ.jpg', 8.2, 'LW6dpj1uCK8', '2026-05-21', 67.961, 1507, 'tt34385135', 6.5, 18328, 'R', 'Kengerian, Aksi, Cerita Fiksi', '연상호', '연상호, 최규석', '김연호', 'Wow Point, Smilegate Entertainment, Midnight Studio', '[{"name":"전지현","character":"Kwon Se-jeong"},{"name":"구교환","character":"Seo Young-cheol"},{"name":"지창욱","character":"Choi Hyun-seok"},{"name":"김신록","character":"Choi Hyun-hee"},{"name":"신현빈","character":"Kong Seol-hee"},{"name":"고수","character":"Han Kyu-seong"},{"name":"이중옥","character":"Lee Bong-seok"},{"name":"김종태","character":"Kang Woo-cheol"},{"name":"황재열","character":"Citizen"},{"name":"이담희","character":"Lee So-eun"}]'::jsonb, '13+', 710),
(1398505, 'Desember Jani', 'Drama', 101, 'NR', 'Sepuluh hari setelah Julia pergi dari rumah tanpa pamit, Jani (13 tahun) cuma ingin kakaknya itu pulang. Ia tahu ibunya, Winnie, adalah penyebab Julia pergi. Hubungan mereka makin renggang, sementara Winnie sibuk bekerja untuk menutupi rasa bersalahnya. Hanya Oma yang bisa menghibur Jani. Diam-diam, Jani masih berhubungan dengan Julia. Selama empat hari di bulan Desember, Jani harus memilih: tetap diam atau menghadapi ibunya.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/rmF3JezLg5ZpFmvOXy50gTwGaWE.jpg', null, null, '9eQFxRmw9g8', '2026-12-10', 4.815, 0, 'tt39673642', null, null, 'TV-G', 'Drama, Keluarga', 'Ariani Darmawan', 'Cyntha Hariadi, Ariani Darmawan', 'Meiske Taurisia, Muhammad Zaidy', 'Palari Films, Role Entertainment', '[{"name":"Chempa Puteri","character":"Jani"},{"name":"Sigi Wimala","character":"Winnie"},{"name":"Tutie Kirana","character":"Oma"},{"name":"Hyori Mika","character":"Julia"}]'::jsonb, 'SU', null),
(1675781, 'Harga Teman', 'Komedi', 119, 'NR', 'After getting fired, Uji, a graphic designer, teams up with her three closest friends to start a creative agency. Amid client demands, family expectations, and friendship dilemmas, she hopes this could be a new beginning. But deeper she goes, the more she realizes: every relationship has its price, friendship included.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/oakfm5GZbxI1U32WC3eudQJq0D8.jpg', 'https://image.tmdb.org/t/p/w1280/c7Y2J5fPvUsj125icXshzCPbxq9.jpg', null, null, '2027-01-21', 4.033, 0, 'tt41941030', null, null, null, 'Komedi, Drama, Percintaan', 'Andrew Kose', 'Debora Danisa, Alicia Angelina, Andrew Kose, Thariq Akbar', 'Wregas Bhanuteja, Anandita Devitarianti, Iman Usman, Amalia Fitriani Rusdi', 'Rekata Studio, Masih Belajar Pictures, IDN Pictures, Juni Records', '[{"name":"Freya Jayawardana","character":"Uji"},{"name":"Devano Danendra","character":"Julian"},{"name":"Emir Mahira","character":"Boshi"},{"name":"Diandra Agatha","character":"Sunny"},{"name":"Jourdy Pranata","character":"Adam"},{"name":"Vonny Anggraini","character":"Puspita Nawang Bulan (Puji''s Mother)"},{"name":"Wyan Sonatha","character":"Purnomo (Puji''s Father)"}]'::jsonb, '13+', null),
(1691495, 'Hajatan Setan', 'Kengerian', 100, 'NR', 'A young woman returns to her hometown after being away for years. However, her homecoming reopens old wounds and triggers a series of strange events that slowly engulf the villagers in suspicion and fear.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/dCVBqPxyV4eUsUEn1JsBxBebBBz.jpg', 'https://image.tmdb.org/t/p/w1280/kOtozhUgLfjPeCTit6X4hMVzaq4.jpg', null, null, '2026-12-03', 2.956, 0, null, null, null, null, 'Kengerian', 'Bambang Drias, Eko Kristianto', 'Andhy Pulung, B.W. Purbanegara, Vidya Talisa Ariestya', 'Rendy Gunawan, Marlia Nurdiyanti', 'Multi Buana Kreasindo, Drias Production', '[{"name":"Ari Irham","character":""},{"name":"Alika Jantinia","character":""},{"name":"Gisellma Firmansyah","character":""},{"name":"Karina Suwandi","character":""},{"name":"Asri Welas","character":""},{"name":"Indra Birowo","character":""},{"name":"Tanta Ginting","character":""},{"name":"Bima Zeno","character":""},{"name":"Sita Permata Sari","character":""},{"name":"Abigail Gabriella","character":""}]'::jsonb, null, null),
(1103760, 'Hamka: Awal Mula Vol. 3', 'Drama', 100, 'NR', 'Set against the backdrop of West Sumatra, a passionate young rebel clashes with his strict scholar father, prompting a self-funded pilgrimage to Mecca where he discovers his destiny to reform Indonesian Islam and finds the love of his life.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/qj8Z3NALhDKQFvLIuawOFbb9YGs.jpg', 'https://image.tmdb.org/t/p/w1280/xxcARyeROB3r4W79Nd9ODicEZoD.jpg', null, 'GPSmy-MafEM', '2026-11-19', 3.436, 0, 'tt27246088', null, null, null, 'Drama, Sejarah', 'Fajar Bustomi', 'Alim Sudio, Cassandra Massardi', 'Chand Parwez Servia, Frederica', 'Majelis Ulama Indonesia, Starvision Plus, Falcon Pictures', '[{"name":"Vino G. Bastian","character":"Buya Hamka"},{"name":"Laudya Cynthia Bella","character":"Siti Raham"},{"name":"Donny Damara","character":"Haji Rasul"},{"name":"Desy Ratnasari","character":"Ummi Safiah"},{"name":"Ayu Laksmi","character":"Andung"},{"name":"Teuku Rifnu Wikana","character":"Kariman Amin"},{"name":"Reza Rahadian","character":"H.O.S. Tjokroaminoto"},{"name":"Marthino Lio","character":"Amir"},{"name":"Mathias Muchus","character":"Sutan Mansur"},{"name":"Donny Kesuma","character":"Kulsum''s Father"}]'::jsonb, 'SU', null),
(1642283, 'Filosofi Teras', 'Drama', 100, 'NR', 'Nea (Sherina Munaf) tulang punggung keluarga untuk ibunya; Ratih (Lydia Kandau), adiknya Runi (Zee Asadel), dan juga kakaknya Abi (Rangga Nattra) serta istrinya. Mendiang ayah mereka menjadikan rumahnya sebagai jaminan utang. Nea mengupayakan segala cara untuk membayarnya meskipun ia menyakiti orang yang ia sayangi. Namun, semakin keras Nea berusaha, semakin banyak pula masalah yang ia tidak bisa kendalikan. Bisakah Nea merelakan dan menyadari ia tidak bisa mengontrol semuanya?', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/mKBIwr6I4BP8vye3pklxwKBWu4J.jpg', 'https://image.tmdb.org/t/p/w1280/r4OFPR2SUCZ7Nx2xNRjeBCDdnSR.jpg', null, 'NSEh5W0Y4ek', '2026-12-24', 3.801, 0, 'tt40194341', null, null, null, 'Drama', 'Affandi Abdul Rachman', 'Widi Lestari, Haqi Achmad', 'Manoj Punjabi', 'MD Pictures', '[{"name":"Sherina Munaf","character":"Nea"},{"name":"Zee Asadel","character":"Runi"},{"name":"Lydia Kandou","character":"Ratih"},{"name":"Ge Pamungkas","character":"Dio"},{"name":"Dinda Kanyadewi","character":"Dita"},{"name":"Kiki Narendra","character":"Marwan"},{"name":"Rangga Nattra","character":"Abi"},{"name":"Givina Lukita","character":"Ayu"},{"name":"Adinda Cresheilla","character":"Citra"},{"name":"Baim D''Bill","character":"Eza"}]'::jsonb, null, null),
(1616687, 'Serangan Balik', 'Aksi', 137, 'NR', 'An ex-soldier and his grandchildren battle against ruthless criminals in a remote village. To survive, they must also confront their fears and regrets.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/9wypfSz5OyWnew6mt5hviGw6WhM.jpg', 'https://image.tmdb.org/t/p/w1280/umxN2kMcUm6VoxSOdcEcQoXuC4q.jpg', null, 'CALwAlglPIc', '2026-11-12', 3.43, 0, 'tt39370926', null, null, null, 'Aksi, Kejahatan, Drama, Cerita Seru', 'Sidharta Tata', 'Sidharta Tata, Khalid Kashogi', 'Edwin Nazir, Kimo Stamboel', 'Mowin Pictures', '[{"name":"Lukman Sardi","character":"Eyang Hari"},{"name":"Callista Arum","character":"Putri"},{"name":"Sulthan Hamonangan","character":"Dimas"},{"name":"Derby Romero","character":"Bastian"},{"name":"Donny Alamsyah","character":"Ulo"},{"name":"Ismi Melinda","character":"Jegeg"},{"name":"Laras Sardi","character":"Mayang"},{"name":"Dennis Adishwara","character":"Agus"},{"name":"Erick Estrada","character":"Iyang"},{"name":"M. N. Qomaruddin","character":"Bendot"}]'::jsonb, '17+', null),
(1632177, '23 Detik', 'Aksi', 94, 'NR', 'Wishnu (Pangeran Lantang) sudah lama membujuk ibunya, Sutji (Sutjiati Narendra), agar merestui pilihan hidupnya menjadi petarung pro. Sutji sendiri masih trauma kehilangan suami dan putra sulungnya, dalam bencana Tsunami di pantai Phuket, Thailand. Karir tarung Wishnu bersilang jalan dengan petarung asal Thailand, Somchit (Achilleur Ralli). Somchit berambisi menjadi juara dunia Mixed Martial Arts (MMA) karena ingin membalas budi ayah angkatnya. Di luar dugaan, memori traumatik masa kecil Somchit bangkit kembali di ring pertarungan.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/ciMiH9y3anv8CUiZhbPHIyth6Mm.jpg', null, null, 'il6LqSMsFMQ', '2027-01-14', 2.816, 0, 'tt37604514', null, null, null, 'Aksi', 'Peter Taslim', 'Peter Taslim, Tamawal Frans, Muhammad Faris Mukammil, Dedey Natalia', 'Peter Taslim', 'Dewa Pictures', '[{"name":"Pangeran Lantang","character":"Wisnu Bimantara"},{"name":"Achilleur Ralli","character":"Somchit"},{"name":"ธนพล จุกสีดา","character":"Pitchai"},{"name":"Jenny Zhang","character":"Mia"},{"name":"Supatjit Somkid","character":"Anna"},{"name":"Cecep Arif Rahman","character":"Irvan"},{"name":"Sutjiati Narendra","character":"Sutji / Wisnu''s Mother"},{"name":"Komang Ardiarta","character":""},{"name":"Peter Taslim","character":"Perry"},{"name":"Cornelio Sunny","character":"Ditto"}]'::jsonb, '13+', null),
(1637577, 'Gak Ada Matinya', 'Komedi', 121, 'NR', 'Di tengah kondisi keuangannya yang sedang berantakan, Binsar (Oki Rengga) tak tahu ini kabar baik atau buruk: Luhut (Mathias Muchus), bapaknya yang baru meninggal mewariskan asuransi 2 miliar. Namun di dalam mobil jenazah, Luhut tiba-tiba bangkit lagi. Binsar pun harus menyembunyikan bapaknya, - terutama dari Fahri (Fedi Nuril), seorang investigator asuransi, setidaknya sampai santunan asurasinya cair.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/8ErJ8LI5HDEktGsOTaak51V6iiU.jpg', 'https://image.tmdb.org/t/p/w1280/vP5DmgPo9eVB8K4jnJh2dMb3EFZ.jpg', null, '1qc9k_ubAMk', '2026-11-05', 2.926, 0, 'tt39961089', null, null, null, 'Komedi, Drama', 'Etienne Caesar', 'Ridho Brado', 'Manoj Punjabi, Muhadkly Acho', 'MD Pictures', '[{"name":"Oki Rengga","character":"Binsar"},{"name":"Mikha Tambayong","character":"Viona"},{"name":"Fedi Nuril","character":"Fahri"},{"name":"Lolox","character":"Robert"},{"name":"Yoshi Sudarso","character":"Reza"},{"name":"Mathias Muchus","character":"Mr. Luhut"},{"name":"Benidictus Siregar","character":"Bahlil"},{"name":"Gita Bhebhita","character":"Lisa"},{"name":"Aci Resti","character":"Murni"},{"name":"Arief Didu","character":"Uncle Feri"}]'::jsonb, '13+', null),
(1616675, 'Tajemnice', 'Drama', 130, 'NR', 'Former sex worker Parni built a peaceful life for her daughter, but her abusive ex resurfaces, threatening to destroy everything she fought to protect.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/j1MVrfow1MbA0nLQ8rlvD8FYz4k.jpg', 'https://image.tmdb.org/t/p/w1280/kIRulLmC9Q4UlQXqs5om4LxS40Y.jpg', null, null, '2026-12-03', 3.1, 0, null, null, null, null, 'Drama, Cerita Seru', 'Ravi L. Bharwani', 'Rayya Makarim', 'Wilza Lubis', 'Buddy Buddy Pictures', '[{"name":"Sha Ine Febriyanti","character":"Parni"},{"name":"Abimana Aryasatya","character":""},{"name":"Shenina Cinnamon","character":""}]'::jsonb, '17+', null),
(1168320, 'Sara', 'Drama', 99, 'NR', 'Sara, a transgender woman goes back to her remote hometown to attend her father’s funeral. She finds the village has changed greatly, and that the villagers have become extremely religious. Added to that, her mother suffers from dementia and treats her like a complete stranger.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/ucI5ChEvFEXPtm3RYoGeoVqJFDm.jpg', 'https://image.tmdb.org/t/p/w1280/oxwOhVlEw3KY1pPeRYk3WO2MNIq.jpg', null, '808wWv_8GT0', '2026-12-10', 3.174, 0, 'tt29470765', null, null, null, 'Drama', 'Ismail Basbeth', 'Ismail Basbeth', 'Lyza Anggraheni, Charlie Meliala', 'Bosan Berisik Lab, Ruang Basbeth Bercerita, Visionari Capital', '[{"name":"Asha Smara Darra","character":"Sara"},{"name":"Christine Hakim","character":"Muryem"},{"name":"Mian Tiara","character":"Ayu"},{"name":"Jajang C. Noer","character":"Saidah"},{"name":"Landung Simatupang","character":"Ustad Said"},{"name":"Bambang Paningron","character":""},{"name":"Tri Sudarsono","character":""},{"name":"Haru Sandra","character":""},{"name":"El Ghifari Raka","character":""}]'::jsonb, null, null),
(1590677, 'Putri, Jangan Gentayangan Lagi', 'Drama', 104, 'NR', 'Putri had run away from home about a year prior. When she was finally found by her mother, Mak Elli, and her younger sister, Alana, Putri was ill following childbirth; she had originally fled after becoming pregnant by her boyfriend. Mak Elli insisted that Putri and her baby, Raman, return home to reunite with the family. After moving back, however, Putri’s condition deteriorated, and she passed away. Since then, local residents have complained about sightings of Putri’s wandering spirit, which appears to be lingering as if there is unfinished business.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/lOJKHkg5JxKlzFVjx5jELbXO6UO.jpg', 'https://image.tmdb.org/t/p/w1280/qqFhMPVsiwvKBLvgqzLqh7uUtsB.jpg', null, 'lvAfNWOXlUM', '2026-11-05', 2.643, 0, 'tt45381985', null, null, null, 'Drama, Kengerian', 'Rizal Mantovani', 'Alim Sudio, Lentera Malam', 'Raam Punjabi', 'MVP Pictures, Show Token, Folago Pictures, PK Films', '[{"name":"Kawai Labiba","character":"Ananda Rizki Saputri"},{"name":"Kinaryosih","character":"Mak Elli"},{"name":"Fadi Alaydrus","character":"Wira"},{"name":"Bintang Agara","character":"Taufik"},{"name":"Denisha","character":"Alana"},{"name":"Matacha Parengkuan","character":"Nindy"},{"name":"Derry Oktami","character":""},{"name":"Moh Iqbal Sulaiman","character":"Heri"},{"name":"Mirza Ali","character":""},{"name":"M. N. Qomaruddin","character":"Pak Jono"}]'::jsonb, '13+', null),
(1627840, 'Zona Merah', 'Aksi', 100, 'NR', 'Virus merebak di kota Rimbalaya. Orang-orang terjangkit, dan jadi mayit. Maya (Aghny Haque) adalah penyintas yang bertahan hidup bersama adik dan orang-orang terdekatnya di kamp pengungsian. Namun, wabah mayit pun mengacau kamp tersebut. Mereka harus kabur dan mempertahankan nyawa, baik dari serangan mayit maupun orang-orang yang mencurigai mereka juga sudah terinfeksi. Kemelut politik yang memanas, dan disinformasi yang disebar untuk menenangkan masyarakat juga semakin memperkeruh suasana. Akankah Maya dan kelompoknya mendapat pertolongan untuk segera keluar dari zona merah?', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ne1BqlBNJbwNjqgsRGjYIe6yBod.jpg', null, null, null, '2027-01-14', 2.632, 0, 'tt39555302', null, null, null, 'Aksi, Fantasi, Kengerian, Cerita Seru', 'Sidharta Tata, Fajar Martha Santosa', 'Dinda Putri Anjani, Sidharta Tata', 'Wicky V. Olindo', 'Screenplay Films, Emtek Media, Surya Citra Media, Rapi Films', '[{"name":"Aghniny Haque","character":"Maya"},{"name":"Andri Mashadi","character":"Risang"},{"name":"Devano Danendra","character":"Adi"},{"name":"Maria Theodore","character":"Ella"},{"name":"Myesha Lin","character":"Olivia"},{"name":"Bryan Domani","character":"Omar"},{"name":"Shindy Huang","character":"Hana"},{"name":"Luna Maya","character":"Jenny"},{"name":"Lukman Sardi","character":"Zaenal Effendi"},{"name":"Derby Romero","character":"Tommy"}]'::jsonb, null, null),
(1551036, 'Seporsi Mie Ayam Sebelum Mati', 'Drama', 125, 'NR', 'If today were your last day, what one small thing would you really want to do? For Ale, the answer is simple: enjoy a bowl of his favorite chicken noodles before he truly gives up on life. But when his regular food cart is closed, that situation leads him into a series of unexpected encounters.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/wqfi1Cicqj1Y6sDxQYSaRihw6IJ.jpg', 'https://image.tmdb.org/t/p/w1280/rQD4rMpygqw3z9ZJMSkz6h6tSJ4.jpg', null, 'yESY1GP1mfQ', '2026-11-12', 2.557, 0, 'tt45292829', null, null, null, 'Drama', 'Kuntz Agus', 'Brian Khrisna, Alim Sudio, Kuntz Agus', 'Philip Lesmana, Ardina Atles', 'Sinergi Pictures, Ben Film, AZ Films, Nuon', '[{"name":"Benidictus Siregar","character":"Ale / Blek"},{"name":"Teuku Rifnu Wikana","character":"Murad"},{"name":"Zulfa Maharani","character":"Juleha"},{"name":"Tika Panggabean","character":"Mami Louise"},{"name":"Fajar Nugra","character":"Ipul"},{"name":"Chicco Kurniawan","character":"Pram"},{"name":"Jourdy Pranata","character":"Gilang"},{"name":"Alex Abbad","character":"Samson"},{"name":"Pangeran Lantang","character":"Bima"},{"name":"Ence Bagus","character":"Pak Uju"}]'::jsonb, '17+', null),
(1590752, 'Pulang Kampung', 'Komedi', 100, 'NR', 'Dalam rangka menjadi Caleg sesuai perintah ayahnya, Daniel, pemuda Batak kelahiran Jakarta, terpaksa pulang kampung untuk belajar budaya Batak ditemani Uli, sepupunya yang tinggal di Danau Toba. Masalah muncul ketika Daniel ternyata bukan cuma jatuh cinta pada budaya Batak, tapi juga pada Uli.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/wsipU0tvTmrSTsBh7pe6r8pk58z.jpg', 'https://image.tmdb.org/t/p/w1280/stSmFcKu1RzPh1YC9kc9FVH2JWm.jpg', null, 'JkiJTQXe8Lo', '2026-11-26', 2.367, 0, 'tt39073352', null, null, null, 'Komedi, Drama, Musik, Percintaan', 'Bene Dion Rajagukguk', 'Bene Dion Rajagukguk', 'Ernest Prakasa, Dipa Andika', 'Imajinari, Jagartha, Trinity Entertainment Network, Miles Films', '[{"name":"Axelo Nababan","character":"Daniel"},{"name":"Vanessa Zee","character":"Uli"},{"name":"Lea Simanjuntak","character":"Daniel''s Mom"},{"name":"Paulus Simangunsong","character":"Daniel''s Father"},{"name":"Judika Sihotang","character":"Uli''s Father"},{"name":"Rita Matumona","character":"Oppung Dio"},{"name":"Indra Jegel","character":""},{"name":"Boris Bokir","character":""},{"name":"Oki Rengga","character":""},{"name":"David Saragih","character":""}]'::jsonb, null, null),
(1707669, 'Festival Hantu Lapar', 'Komedi', 100, 'NR', 'After inadvertently violating a sacred ancestral taboo during the Hungry Ghost Festival, an adopted young man and his friends must break a relentless supernatural curse before the spiritual gates close permanently.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/dzRfi07uuPGyBVh0PIQBdvPTmc.jpg', 'https://image.tmdb.org/t/p/w1280/wa39eElPw7UWDZeQrzm8qglbqN0.jpg', null, '5XcAn0TLlGY', '2026-11-26', 1.899, 0, 'tt43611167', null, null, null, 'Komedi, Kengerian', 'Imam Darto', 'Celvin Jaya Hadi, Imam Darto, Warman Nasution', 'Raam Punjabi', 'MVP Pictures, PK Films, Show Token, Grab Holdings', '[{"name":"Endy Arfian","character":"Raka"},{"name":"Aci Resti","character":"Tintin"},{"name":"Fajar Nugra","character":"Bobi"},{"name":"Jenny Zhang","character":""},{"name":"Augie Fantinus","character":"Bo Kiat"},{"name":"Sarah Beatrix","character":"Bella"},{"name":"Rizky Inggar","character":""},{"name":"Alvin Adam","character":""},{"name":"Oka Sugawa","character":""},{"name":"Oki DM","character":""}]'::jsonb, null, null),
(1763585, 'Lagi Probation: Kerja Ngejar Apa Sih?', 'Komedi', 90, 'NR', 'Bintang harus cari kerjaan untuk hidupin keluarga dan dirinya sendiri. Setelah berjuang sana-sini, kesempatan langka akhirnya datang: Bintang diterima jadi anak probation alias magang di perusahaan bumbu dapur besar, bersama Bima si Cumlaude, Velma si Asbun, Damai si Cari Muka, Mika si Pewaris, dan Claudia si Robot Korporat. Tapi, baru juga bonding sama teman-teman barunya, eh ternyata cuma satu yang akan lolos probation dan jadi karyawan tetap. Seketika, teamwork berubah jadi team-war, teman jadi saingan, kolaborasi jadi kompetisi. 6 orang, 1 posisi. Siapa yang akan berhasil?', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/4glDFxFmu3GyX9N50EtiLk0k8zp.jpg', 'https://image.tmdb.org/t/p/w1280/olkdII9tRfrQ84ne8d44h7LrXbz.jpg', null, 'QA8NwVVZguw', '2026-11-12', 2.278, 0, 'tt46594641', null, null, null, 'Komedi, Drama', 'Archie Hekagery', 'Archie Hekagery, Rifki Ardisha', 'Shanty Harmayn, Aoura Lovenson Chandra, Tanya Yuson', 'BASE Entertainment, Laspro, ARENDI', '[{"name":"Aurora Ribero","character":"Bintang"},{"name":"Rey Bong","character":"Bima"},{"name":"Gabriella Ekaputri","character":"Claudia"},{"name":"Daffa Wardhana","character":"Mika"},{"name":"Arafah Rianti","character":"Velma"},{"name":"Lutfi Afansyah","character":"Damai"},{"name":"Wafda Saifan Lubis","character":"Chandra"},{"name":"Abirama Putra Andresta","character":"Bintang''s Little Brother"},{"name":"Indra Birowo","character":"Bintang''s Father"},{"name":"Lolox","character":"Bibit Pujakesuma"}]'::jsonb, '13+', null),
(1607692, '5 cm: Revolusi Hati', 'Petualangan', 100, 'NR', 'Four inseparable companions pledge lifelong solidarity upon entering secondary education, only for their collective bond to undergo severe emotional and structural strain when the introduction of romantic interests and an transformative journey outside the metropolis force them to confront the inevitable realities of maturity.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/84APhzDJT8v1AkPyufxOe8KEat2.jpg', null, null, null, '2026-12-24', 1.937, 0, null, null, null, null, 'Petualangan, Drama', 'Emil Heradi', 'Donny Dhirgantoro, Rza Kumar, Sunil Soraya', 'Sunil Soraya', 'Soraya Intercine Films', '[{"name":"Roman King","character":"Zafran"},{"name":"Rachel Aseelah","character":"Azizah"},{"name":"Ronggo Vercaemer","character":"Riko"},{"name":"Olivia Morrison","character":"Astri"},{"name":"Ali Fikry","character":"Asep"},{"name":"Bimasena","character":"Ariwibowo"},{"name":"Kaemi Lalwani","character":""},{"name":"Ersa Mayori","character":""},{"name":"Alexandra Gottardo","character":"Riko’s Mother"},{"name":"Cut Keke","character":"Azizah’s Mother"}]'::jsonb, null, null),
(1604413, 'Banyak Anak Banyak Rejeki yang Harus Dicari', 'Drama', 111, 'NR', 'Gravedigger Babe Rojali lives in poverty with his wife Siti Juleha and their three children. During a heavy rain, as he was busy bailing out water from his leaky house, a neighborhood watchman arrived and asked him to dig a grave that night, at the request of the neighborhood head. Reluctantly, he set out, accompanied by his younger brother Abdul. While digging the grave, Babe Rojali prayed and asked God to make him rich. That prayer seemed to be answered because he later found a lump of gold in the ground of the grave he had dug. From that moment on, Babe Rojali’s life changed completely.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/paaHFAsoeEOlK0KvQuqQW7LkvM.jpg', null, null, null, '2027-01-14', 2.215, 0, null, null, null, null, 'Drama, Komedi', 'Tyas Asko', 'Kaka Endi', null, 'Black White Pictures', '[{"name":"Opie Kumis","character":"Babe Rojali"},{"name":"Fadli Fuad","character":"Hendrik Rojali"},{"name":"Elina Joerg","character":"Ningsih Beethoven"},{"name":"Elvy Sukaesih","character":"Siti Juleha"},{"name":"Revaldo","character":"Ari Rojali"},{"name":"Mandy Edenia","character":"Laila Rojali"},{"name":"Ali Gohom","character":"Abdul"},{"name":"Hanif MZ","character":"Little Hendrik"},{"name":"Hafi Badali","character":"Little Ari"},{"name":"Noia Oren","character":"Little Laila"}]'::jsonb, 'SU', null),
(1763612, 'Orang Sebelah', 'Kengerian', 86, 'NR', 'This film is based on one of the well-known, spine-chilling myths circulating around the IPB University campus area that haunts the students living in the campus dorms.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/kmM5kbjlD46Hon1oUG3I0BbTFxz.jpg', null, null, null, '2026-11-26', 1.945, 0, null, null, null, null, 'Kengerian', 'Chiska Doppert', 'Erik Supit', 'Jhony Fam, Maya Savitri', 'Avantgarde Production', '[{"name":"Cassandra Sheryl Lee","character":""},{"name":"Esta Pramanita","character":""},{"name":"Luna Fathia","character":""},{"name":"Sadiya Aisye","character":""},{"name":"Ryuken Lie","character":""},{"name":"Yando Adrian","character":""},{"name":"Monique Henry","character":""},{"name":"Arry Febrian","character":""},{"name":"Ananda George","character":""},{"name":"Turaekhan Roy","character":""}]'::jsonb, '17+', null),
(1679486, 'People Pleaser: Si Paling Gak Enakan', 'Komedi', 100, 'NR', 'Karina is a young woman who always puts others first and finds it difficult to say "no." This habit leaves her exhausted and causes her to sacrifice her own dreams.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/j2oxt48zdUPbJdnoiCTCOURIj22.jpg', 'https://image.tmdb.org/t/p/w1280/saHUIv7DClJ0fLDc4lfxHdSxBm1.jpg', null, 'rtBBEtosXMc', '2026-11-19', 1.797, 0, null, null, null, null, 'Komedi, Drama, Percintaan', 'Bobby Prasetyo', 'Evelyn Afnilia', 'Marcella Daryanani, Andi Suryanto', 'Lyto Pictures', '[{"name":"Mawar Eva De Jongh","character":"Karina"},{"name":"Ardit Erwandha","character":"Raka"},{"name":"Ummi Quary","character":"Dilla"},{"name":"Fatih Unru","character":"Dino"},{"name":"Vonny Cornellya","character":"Mrs. Nana"},{"name":"Surya Saputra","character":"Mr. Hadi"},{"name":"Cut Mini","character":"Aunt Tati"},{"name":"Amel Carla","character":"Gina"},{"name":"Taskya Namya","character":"Renata"},{"name":"Fira Maringka","character":"Hannah"}]'::jsonb, null, null),
(1300968, 'The Hunger Games: Sunrise on the Reaping', 'Cerita Fiksi', 159, 'NR', 'Return to the world of Panem 24 years before the events of The Hunger Games, starting on the morning of the reaping of the 50th Hunger Games, also known as the Second Quarter Quell.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/jNcZH8yplxttRlf0wwqfGGMKHxX.jpg', 'https://image.tmdb.org/t/p/w1280/aqFZcr2dxSZ2UwWSo1WC6C0rwDf.jpg', null, 'Dr060OLTodE', '2026-11-18', 37.859, 0, 'tt32558705', null, null, null, 'Cerita Fiksi, Aksi, Petualangan', 'Francis Lawrence', 'Suzanne Collins, Billy Ray, Michael Lesslie', 'Nina Jacobson, Brad Simpson, Francis Lawrence', 'Lionsgate, Color Force, about:blank, Studio Babelsberg', '[{"name":"Joseph Zada","character":"Haymitch Abernathy"},{"name":"Mckenna Grace","character":"Maysilee Donner / Merrilee Donner"},{"name":"Maya Hawke","character":"Wiress"},{"name":"Ralph Fiennes","character":"President Coriolanus Snow"},{"name":"Jesse Plemons","character":"Plutarch Heavensbee"},{"name":"Elle Fanning","character":"Effie Trinket"},{"name":"Kieran Culkin","character":"Caesar Flickerman"},{"name":"Glenn Close","character":"Drusilla Sickle"},{"name":"Lili Taylor","character":"Mags Flanagan"},{"name":"Kelvin Harrison Jr.","character":"Beetee Latier"}]'::jsonb, 'PG-13', null),
(656908, 'रामायणम्', 'Fantasi', 167, 'NR', 'An ancient epic follows a young prince and princess whose marriage and subsequent exile mark the beginning of a legendary journey. Their story of love, duty and destiny sets the stage for greater challenges ahead.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/gOWnXaBxqT6k2y40hKfYU6c0Ym.jpg', 'https://image.tmdb.org/t/p/w1280/bkhPaFOiqc9GeLMdf1D44KbozRH.jpg', 10, 'AYkPRN874m8', '2026-11-06', 29.766, 1, 'tt27988879', null, null, null, 'Fantasi, Aksi, Petualangan', 'Nitesh Tiwari', 'Shridhar Raghavan, Nitesh Tiwari', 'Namit Malhotra', 'Monster Mind Creations, Prime Focus Studios, DNEG', '[{"name":"रणबीर कपूर","character":"Prince Ram / Parshuram / Lord Vishnu"},{"name":"Yash","character":"Ravana"},{"name":"Sai Pallavi","character":"Sita"},{"name":"Ravi Dubey","character":"Lakshman"},{"name":"अरुण गोविल","character":"King Dashrath"},{"name":"Rakul Preet Singh","character":"Surpanakha"},{"name":"लारा दत्ता","character":"Kaikeyi"},{"name":"इंदिरा कृष्णन","character":"Kaushalya"},{"name":"Sonal Jha","character":"Sumitra"},{"name":"Adinath Kothare","character":"Bharata"}]'::jsonb, 'PG-13', null),
(1457866, 'THE FURTHER MIS-ADVENTURES OF CLIFF BOOTH', 'Drama', 100, 'NR', 'Eight years after the events of Once Upon a Time in... Hollywood, Cliff Booth returns to a changing Los Angeles. Now working as a fixer in the shadows of the Hollywood studio system, Cliff finds himself entangled in a dangerous web of secrets, crimes and betrayals that will test everything he knows about loyalty and survival.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/44iyquHYfSInzp7rYYQyRV1Ndtk.jpg', 'https://image.tmdb.org/t/p/w1280/aRO4TuqF8dkRCb5tPlsSlpJbmQD.jpg', null, 'RjEZaUBbUvU', '2026-11-25', 11.963, 0, 'tt36408401', null, null, null, 'Drama, Komedi, Cerita Seru', 'David Fincher', 'Quentin Tarantino', 'David Heyman, Shannon McIntosh, Stacey Sher, Quentin Tarantino', 'Heyday Films, Netflix, Plan B Entertainment', '[{"name":"Brad Pitt","character":"Cliff Booth"},{"name":"Elizabeth Debicki","character":"Karen Crosby"},{"name":"Scott Caan","character":"Charlie Peters"},{"name":"Carla Gugino","character":"Toni Peters"},{"name":"Yahya Abdul-Mateen II","character":"Roderick ''Hot Rod'' Harrison"},{"name":"Peter Weller","character":"Gus Booth"},{"name":"Matt Groove","character":"Mr. Verdusco"},{"name":"JB Tadena","character":"Mr. Verdusco"},{"name":"Corey Fogelmanis","character":""},{"name":"Karren Karagulian","character":""}]'::jsonb, null, null),
(1591675, 'ルックバック', 'Drama', 100, 'NR', 'Popular, outgoing Fujino is celebrated by her classmates for her funny comics in the class newspaper. One day, her teacher asks her to share the space with Kyomoto, a truant recluse whose beautiful artwork sparks a competitive fervor in Fujino. What starts as jealousy transforms when Fujino realizes their shared passion for drawing.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/6eXDHPwPDTZTgf4wuGIP49bxxJV.jpg', 'https://image.tmdb.org/t/p/w1280/ceOdqFmZy5kKImbGThuDHuifGpm.jpg', 7.9, 'ILBDFlYMGAY', '2026-11-18', 5.235, 20, 'tt39094466', 7.6, 820, null, 'Drama', '是枝裕和', '是枝裕和', '小出大樹', 'K2 Pictures, Shueisha', '[{"name":"出口夏希","character":"Fujino"},{"name":"蒔田彩珠","character":"Kyomoto"},{"name":"七瀬ふうり","character":"Young Fujino"},{"name":"岡田六花","character":"Young Kyomoto"},{"name":"Masaki Suda","character":"Maeda"},{"name":"宮藤官九郎","character":"Tamai"},{"name":"野呂佳代","character":"Akari"},{"name":"池田良","character":"Hitoshi"},{"name":"佐々木みゆ","character":"Megumi"},{"name":"山田真歩","character":"Manabe"}]'::jsonb, null, null),
(1545057, '최종면접', 'Misteri', 108, 'NR', 'Six college students meet at the final interview of a global IT company. Growing closer as they prepare for the group discussion, they dare to dream that all six might make it — until the day before the interview, when the company announces its verdict: only one will be hired. On the day of the interview, mysterious envelopes arrive, each containing one of their secrets — and suspicion begins to take hold. Who among the six is the liar?', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/wImwvRmbR28hPNDmaj5W7zvxk0T.jpg', 'https://image.tmdb.org/t/p/w1280/zAaCSWZCs9IgEn7GiUkDuEtYQKf.jpg', null, 'mDqVXcgZKAM', '2026-11-06', 3.394, 0, 'tt44980509', null, null, null, 'Misteri', '김정훈', 'Akinari Asakura, 권오광', '최정환, 이영한', 'Covenant Pictures', '[{"name":"조이현","character":"Moon Hye-in"},{"name":"Kim Jae-won","character":"Han Jin-woo"},{"name":"신승호","character":"Baek Seung-bin"},{"name":"강유석","character":"Lee Hee-chan"},{"name":"곽동연","character":"Jeon Yo-han"},{"name":"배강희","character":"Cha Ju-won"}]'::jsonb, '13+', null),
(1760134, 'Piye To Kih?', 'Komedi', 108, 'NR', 'A broken heart drives Mukidi to prove that he is worthy of marrying the woman of his dreams. He works hard until he is able to buy an inexpensive house, which turns out to hold a mystery. In that house, he meets Sukma, a mysterious woman from the spirit world who has a different religion and background, yet manages to help Mukidi get over his heartbreak. Strange events begin to unfold, dragging his two best friends, Gendut (Sutrisno Agung) and Penyok (Eko Dunung), into the chaos.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/jCUgxw5XvyBP9sENPBbHD26nns.jpg', null, null, 'kNyubnlatO4', '2026-11-19', 2.187, 0, 'tt46065793', null, null, null, 'Komedi, Drama, Kengerian', 'Ito Mavin', 'Endik Koeswoyo, Ito Mavin', 'Ito Mavin', 'Miracle Pictures', '[{"name":"Dara Sarasvati","character":"Sukma"},{"name":"Heri Chandra","character":"Mukidi"},{"name":"Sutrisno Agung","character":"Gendut"},{"name":"Eko Dunung","character":"Penyok"},{"name":"Wiyono","character":"Pak Nggalino"},{"name":"Gabriella Desta","character":"Bunga"},{"name":"TJ Ruth","character":"Bu Yeyen"},{"name":"Ibnu Widodo","character":"Pak RT"},{"name":"Marwoto","character":"Pak Gino"},{"name":"Ivonne Dahler","character":"Bu Tinah"}]'::jsonb, '13+', null),
(1384216, 'The Dog Stars', 'Aksi', 119, 'NR', 'After the world''s population has been ravaged by a pandemic, a man lives a lonesome existence in a Colorado airplane hangar with his dog and a dour gunman he has befriended. When a mysterious transmission comes through on the radio while he’s flying his old Cessna, it sparks a hunt for the provenance of the sound.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/5O616X9vmRzQdB68PHzBewPittd.jpg', 'https://image.tmdb.org/t/p/w1280/3k7GzxOdLZkN3eZsuhLi2eRzkXO.jpg', 7.2, '-xSxaE1ClEE', '2026-08-26', 189.668, 818, 'tt21285562', 6.5, 13521, 'R', 'Aksi, Cerita Seru, Cerita Fiksi', 'Ridley Scott', 'Mark L. Smith, Peter Heller', 'Mark L. Smith, Cliff Roberts, Michael Pruss, Ridley Scott', '20th Century Studios, Scott Free Productions', '[{"name":"Jacob Elordi","character":"Hig"},{"name":"Josh Brolin","character":"Bangley"},{"name":"Margaret Qualley","character":"Cima"},{"name":"Guy Pearce","character":"Pops"},{"name":"Benedict Wong","character":"Aaron"},{"name":"Allison Janney","character":"Darlene"},{"name":"Ewen Bremner","character":"Crossbow Hunter"},{"name":"Sam Spruell","character":"John"},{"name":"James Craze","character":"Logan"},{"name":"Sai Bennett","character":"Melissa"}]'::jsonb, '17+', 10862),
(969681, 'Spider-Man: Brand New Day', 'Cerita Fiksi', 145, 'NR', 'Empat tahun setelah peristiwa Spider-Man: No Way Home, Peter Parker sudah tidak ada lagi dan Spider-Man kini berada di puncak kemampuannya dalam menjaga Kota New York tetap aman. Semuanya berjalan dengan baik hingga serangkaian kejahatan yang tidak biasa menyeret Spider-Man ke dalam jaring misteri yang lebih besar dari apa pun yang pernah ia hadapi sebelumnya. Untuk menghadapi apa yang akan datang, Spider-Man tidak hanya harus berada dalam kondisi fisik dan mental terbaiknya, tetapi juga harus siap menghadapi konsekuensi dari masa lalunya!', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', 'https://image.tmdb.org/t/p/w1280/4tjxYg2AbOzzG9G1YuiT2NzYhlH.jpg', 8.5, 'P3uI5sLosKU', '2026-07-29', 377.189, 6483, 'tt22084616', 8, 327986, 'PG-13', 'Cerita Fiksi, Aksi, Petualangan', 'Destin Daniel Cretton', 'Steve Ditko, Stan Lee, Erik Sommers, Chris McKenna', 'Kevin Feige, Amy Pascal, Rachel O''Connor, Avi Arad', 'Marvel Studios, Columbia Pictures, Pascal Pictures, TSG Entertainment', '[{"name":"Tom Holland","character":"Peter Parker / Spider-Man"},{"name":"Sadie Sink","character":"Jean Grey"},{"name":"Tramell Tillman","character":"William ''Bill'' Metzger"},{"name":"Zendaya","character":"MJ"},{"name":"Jacob Batalon","character":"Ned Leeds"},{"name":"Jon Bernthal","character":"Frank Castle / Punisher"},{"name":"Mark Ruffalo","character":"Bruce Banner / Hulk"},{"name":"Florence Pugh","character":"Yelena Belova / Black Widow"},{"name":"Liza Colón-Zayas","character":"Detective Jean DeWolff"},{"name":"Marisa Tomei","character":"May Parker"}]'::jsonb, '13+', 6819),
(1101383, 'The End of Oak Street', 'Cerita Fiksi', 100, 'NR', 'After a mysterious cosmic event rips Oak Street from suburbia and transports their neighborhood to someplace unknown, the Platt family soon discovers that their very survival depends on them sticking together as they navigate their now unrecognizable surroundings.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/nlC0I1cCemzfNLYPnAhdydpOYOi.jpg', 'https://image.tmdb.org/t/p/w1280/b9q9VmbXDvJmTziRqkwdEmFdwhr.jpg', 7.1, 'u4tgctWuHc0', '2026-08-12', 59.475, 2309, 'tt27165187', 6.5, 39062, 'PG-13', 'Cerita Fiksi, Misteri, Cerita Seru', 'David Robert Mitchell', 'David Robert Mitchell', 'J.J. Abrams, David Robert Mitchell, Matt Jackson, Hannah Minghella', 'Warner Bros. Pictures, Domain Entertainment, Bad Robot, Jackson Pictures', '[{"name":"Anne Hathaway","character":"Denise Platt"},{"name":"Ewan McGregor","character":"Greg Platt"},{"name":"Maisy Stella","character":"Audrey Platt"},{"name":"Christian Convery","character":"Brian Platt"},{"name":"Jordan Alexa Davis","character":"Jeannette Christiansen"},{"name":"P.J. Byrne","character":"Mel Jacobs"},{"name":"Hudson Meek","character":"Kaden Tucker"},{"name":"Anne Gee Byrd","character":"Mrs. Huddleston"},{"name":"Emily Kuroda","character":"Mrs. Valcourt"},{"name":"Simms May","character":"Zachary"}]'::jsonb, '13+', 2367),
(1288069, 'Tenzing', 'Drama', 126, 'NR', 'Seorang pria yang gigih memulai misi berisiko tinggi, dan menaklukkan rintangan yang tampak mustahil, demi mewujudkan impiannya menjadi orang pertama yang mencapai puncak Gunung Everest.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/eI0QW02PYqhnmIvLRdn9vrfVVP7.jpg', 'https://image.tmdb.org/t/p/w1280/9MdxBPjI58xkzA7RtKX9xRKvlZp.jpg', 8.3, 'KkYCY5YR12U', '2026-10-09', 46.252, 250, 'tt6262770', 7.7, 289, 'PG', 'Drama, Sejarah', 'Jennifer Peedom', 'Luke Davies, Jennifer Peedom', 'Luke Davies, Iain Canning, Emile Sherman, Liz Watts', 'Cross City Films, See-Saw Films, Apple Studios', '[{"name":"更登彭措","character":"Tenzing Norgay"},{"name":"Tom Hiddleston","character":"Ed Hillary"},{"name":"Willem Dafoe","character":"John Hunt"},{"name":"Samdrup Dorje Lama","character":"Boy Tenzing (9 Yrs)"},{"name":"Bhuchung Kata","character":"Sherpa"},{"name":"Johnny Flynn","character":"George Mallory"},{"name":"Lhakpa Tsamchoe","character":"Kinzom"},{"name":"Jampa Kalsang Tamang","character":"Mingma"},{"name":"Elizabeth Blackmore","character":"Mrs Ingram"},{"name":"Brandon McClelland","character":"Mr Ingram"}]'::jsonb, '13+', 2941),
(1302904, 'Practical Magic 2', 'Percintaan', 130, 'NR', 'The Owens sisters must confront the dark curse that threatens to unravel their family once and for all.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ogwQOLbCfncjvBhFb5l0OmQH8KC.jpg', 'https://image.tmdb.org/t/p/w1280/oIglj0Jy9duG4LnrRUpH8n001Pk.jpg', 7.2, 'Ho10_4IX1jE', '2026-09-09', 98.872, 359, 'tt32588798', null, null, 'PG-13', 'Percintaan, Fantasi, Komedi', 'Susanne Bier', 'Akiva Goldsman, Georgia Pritchett, Kelly Marcel, Alice Hoffman', 'Denise Di Novi, Sandra Bullock, Nicole Kidman', 'Di Novi Pictures, Warner Bros. Pictures, Blossom Films, Fortis Films', '[{"name":"Sandra Bullock","character":"Sally Owens"},{"name":"Nicole Kidman","character":"Gillian Owens"},{"name":"Joey King","character":"Kylie"},{"name":"Maisie Williams","character":"Antonia"},{"name":"Xolo Maridueña","character":"Gideon"},{"name":"Lee Pace","character":"Ian Wright"},{"name":"Dianne Wiest","character":"Jet"},{"name":"Stockard Channing","character":"Franny"},{"name":"Solly McLeod","character":"Tom Lockland"},{"name":"Ema Cavolli","character":"Maria Owens"}]'::jsonb, '13+', 2848),
(1380417, 'By Any Means', 'Cerita Seru', 107, 'NR', 'In 1960s Mississippi, a young Black FBI agent is forced to partner with a notorious mafia hitman to investigate a wave of brutal civil rights murders.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/85CvGoeXAcSSWy6So2DRD8ItJAN.jpg', 'https://image.tmdb.org/t/p/w1280/nw9Q3idNO8EsTPnvr8vBJTpkWGA.jpg', 6.6, 'fvnyrBnUx4E', '2026-09-02', 27.253, 90, 'tt34379051', null, null, null, 'Cerita Seru, Sejarah, Kejahatan, Drama', 'Elegance Bratton', 'Sascha Penn', 'Alex Lebovici, Basil Iwanyk, Erica Lee, Chester Algernal Gordon', 'Hammerstone Studios, Thunder Road, Freedom Principle, Municipal Pictures', '[{"name":"Yahya Abdul-Mateen II","character":"Wayne Strider"},{"name":"Mark Wahlberg","character":"Gregory Scarpa"},{"name":"Nicole Beharie","character":"Allison Strider"},{"name":"Josh Lucas","character":"Special Agent Everett Rhodes"},{"name":"David Strathairn","character":"Special Agent Roy K. Moore"},{"name":"Giancarlo Esposito","character":"Vernon Dahmer"},{"name":"Ethan Embry","character":"Sam Bowers"},{"name":"LisaGay Hamilton","character":"Ms. Rebecca Brewer"},{"name":"LaChanze","character":"Hattie Dahmer"},{"name":"Biko Eisen-Martin","character":"Special Agent Archie Crawford"}]'::jsonb, '17+', 2416),
(687163, 'Project Hail Mary', 'Cerita Fiksi', 157, 'NR', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/iOb2fjXLbpJgyQXe46n1WtGCnaa.jpg', 'https://image.tmdb.org/t/p/w1280/8Tfys3mDZVp4tNoH2ktm06a0Tau.jpg', 8.6, 'NKYea63tQmI', '2026-03-15', 78.546, 8653, 'tt12042730', 8.2, 570200, 'PG-13', 'Cerita Fiksi, Petualangan', 'Phil Lord, Christopher Miller', 'Andy Weir, Drew Goddard', 'Rachel O''Connor, Ryan Gosling, Aditya Sood, Amy Pascal', 'Lord Miller, Amazon MGM Studios, Pascal Pictures, Open Invite Entertainment', '[{"name":"Ryan Gosling","character":"Ryland Grace"},{"name":"Sandra Hüller","character":"Eva Stratt"},{"name":"James Ortiz","character":"Rocky (voice)"},{"name":"Lionel Boyce","character":"Carl"},{"name":"Milana Vayntrub","character":"Olesya Ilyukhina"},{"name":"Ken Leung","character":"Yao"},{"name":"Priya Kansara","character":"Mary (voice)"},{"name":"Mia Soteriou","character":"Dr. Browne"},{"name":"Annelle Olaleye","character":"Olivia"},{"name":"Maya Eva Hosein","character":"Rekha"}]'::jsonb, '13+', 1676),
(1083381, 'Backrooms', 'Kengerian', 111, 'NR', 'Setelah pasien seorang terapis menghilang ke dimensi di luar realitas, dia harus menjelajah ke tempat yang tidak dikenal untuk menyelamatkannya.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', 'https://image.tmdb.org/t/p/w1280/QNE9Ihuas4duMHJYGQgAcuRtXz.jpg', 7, '0HjdiohVOik', '2026-05-27', 63.637, 3980, 'tt26657236', 6.7, 221583, 'R', 'Kengerian, Misteri, Cerita Fiksi', 'Kane Parsons', 'Will Soodik', 'Shawn Levy, Dan Cohen, Dan Levine, James Wan', 'Atomic Monster, 21 Laps Entertainment, A24, Phobos', '[{"name":"Chiwetel Ejiofor","character":"Clark"},{"name":"Renate Reinsve","character":"Mary"},{"name":"Finn Bennett","character":"Bobby"},{"name":"Lukita Maxwell","character":"Kat"},{"name":"Mark Duplass","character":"Phil"},{"name":"Avan Jogia","character":"Naren Warne"},{"name":"Robert Bobroczkyi","character":"Pirate Clark"},{"name":"Ember Ambrose","character":"Young Mary"},{"name":"Krista Kosonen","character":"Nora"},{"name":"Philip Granger","character":"Meterman"}]'::jsonb, '17+', 2121),
(950028, 'The Invite', 'Komedi', 107, 'NR', 'Joe and Angela''s marriage is on thin ice. When they invite their enigmatic upstairs neighbors for a dinner party, the night spirals into unexpected places. Have they reignited the spark or lit the match that burns it all down?', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/b7Dr8Chzse8VagexAporUu2RtLx.jpg', 'https://image.tmdb.org/t/p/w1280/lEwqBGNR65KZv6Ej5ufcmhZu2y2.jpg', 7.2, 'nelkiuezJxg', '2026-06-25', 29.944, 905, 'tt14173636', 7.5, 68555, 'R', 'Komedi, Drama, Percintaan', 'Olivia Wilde', 'Rashida Jones, Will McCormack', 'David Permut, Megan Ellison, Ben Browning, Saul Germaine', 'Annapurna Pictures, FilmNation Entertainment, Permut Presentations', '[{"name":"Olivia Wilde","character":"Angela"},{"name":"Seth Rogen","character":"Joe"},{"name":"Penélope Cruz","character":"Piña"},{"name":"Edward Norton","character":"Hawk"}]'::jsonb, 'R', 1934),
(1433583, 'The Weight', 'Drama', 112, 'NR', 'When Samuel is torn from his daughter and sent to a brutal prison, Warden Clancy offers him a high-stakes proposition: smuggle gold out of a remote mine with a dangerous crew of prisoners and he’ll win his freedom.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/8i5iZV50CoEtmDCFM7RSxCkpE8h.jpg', 'https://image.tmdb.org/t/p/w1280/4klejBUCWsq2F9GHB5EH5mQdFOg.jpg', 6.7, '7YpuMymmiJ8', '2026-09-16', 25.106, 86, 'tt10794054', null, null, null, 'Drama, Cerita Seru', 'Padraic McKinley', 'Shelby Gaines, Matthew Booi, Leo Scherman, Matthew Chapman', 'Simon Fields, Nathan Fields, Ryan Hawke, Jonas Katzenstein', 'Fields Entertainment, Under the Influence Productions, Augenschein Filmproduktion, Logical Content Ventures', '[{"name":"Ethan Hawke","character":"Samuel Murphy"},{"name":"Russell Crowe","character":"Warden Clancy"},{"name":"Julia Jones","character":"Anna"},{"name":"Austin Amelio","character":"Rankin"},{"name":"Avi Nash","character":"Singh"},{"name":"Lucas Lynggaard Tønnesen","character":"Olson"},{"name":"Sam Hazeldine","character":"Amis"},{"name":"George Burgess","character":"Letender"},{"name":"Jeff Hallman","character":"Big Prisoner"},{"name":"Alec Newman","character":"Taggert"}]'::jsonb, 'R', 2026),
(1381078, 'Love of Your Life', 'Percintaan', 109, 'NR', 'Disutradarai Rachel Morrison, LOVE OF YOUR LIFE mengikuti Maya, yang pertemuannya dengan Charlie memicu kisah cinta luar biasa dan masa depan di luar bayangannya. Saat masa depan itu berubah, Maya dihadapkan pada kehidupan baru yang tak terduga, memaksanya memahami siapa dirinya, apa yang diinginkannya, dan cara mencintai lagi.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/dL3Tcv4FU2K85bgnGRBgLjFSrLr.jpg', 'https://image.tmdb.org/t/p/w1280/4hneB0UFKOZAGJHqJ3VhDcG72uH.jpg', 6.8, 'HzGx48E64Xg', '2026-10-07', 50.136, 195, 'tt34384900', null, null, 'R', 'Percintaan, Drama', 'Rachel Morrison', 'Julia Cox', 'Ryan Gosling, Jessie Henderson', 'Amazon MGM Studios, Open Invite Entertainment', '[{"name":"Margaret Qualley","character":"Maya"},{"name":"Gabriel Basso","character":"Charlie"},{"name":"Aaron Pierre","character":"Felix"},{"name":"Patrick Schwarzenegger","character":"Jason"},{"name":"Catherine Keener","character":"Ruth"},{"name":"Tamara Lawrance","character":"Kali"},{"name":"Corey Johnson","character":"Kerry"},{"name":"Michael Shelford","character":"Colin"},{"name":"Adam Woodward","character":"Matt"},{"name":"Gayané Kaligian","character":"Armenian Family Member"}]'::jsonb, 'R', 1493),
(1368337, 'The Odyssey', 'Petualangan', 173, 'NR', 'Odysseus, raja legendaris Yunani dari Ithaca, memulai perjalanan panjang dan berbahaya untuk pulang setelah Perang Troya, yang mengisahkan perjumpaannya dengan makhluk-makhluk mitologis seperti Cyclops Polyphemus, para Siren, dan penyihir-dewi Circe.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/9EJDqzAQ0HoNvMDkOQuirXt1RCg.jpg', 'https://image.tmdb.org/t/p/w1280/iDiTY1wA35YWzTmXLTtqaxtN6tc.jpg', 8, 'AyIZ9tiiN8I', '2026-07-15', 208.308, 4326, 'tt33764258', 8.4, 477953, 'R', 'Petualangan, Aksi, Fantasi', 'Christopher Nolan', 'Christopher Nolan', 'Christopher Nolan, Emma Thomas', 'Universal Pictures, Syncopy', '[{"name":"Matt Damon","character":"Odysseus"},{"name":"Tom Holland","character":"Telemachus"},{"name":"Anne Hathaway","character":"Penelope"},{"name":"Robert Pattinson","character":"Antinous"},{"name":"Himesh Patel","character":"Eurylochus"},{"name":"Charlize Theron","character":"Calypso"},{"name":"John Leguizamo","character":"Eumaeus"},{"name":"Travis Scott","character":"Bard"},{"name":"Corey Hawkins","character":"Polybus"},{"name":"Jarreth J. Merz","character":"Leodes"}]'::jsonb, '13+', 1259),
(1291595, 'Insidious: Out of the Further', 'Kengerian', 106, 'NR', 'Gemma, a young mother raising her daughter in the house she grew up in, discovers she can travel into The Further, where she possesses an ability to bring what lives there back to the real world.', '#134e4a', '#1c1917', 'https://image.tmdb.org/t/p/w500/4tTrW9dXCByS5wt2pXVWb58zNjz.jpg', 'https://image.tmdb.org/t/p/w1280/p40lmrdI4blcAPZQMTPaiy5v5Ym.jpg', 7.7, 'gXjurDkYnEM', '2026-08-19', 167.766, 1007, 'tt32393988', 6.2, 13228, 'PG-13', 'Kengerian, Cerita Seru', 'Jacob Chase', 'Leigh Whannell, Jacob Chase, David Leslie Johnson-McGoldrick', 'Jason Blum, Leigh Whannell, James Wan, Oren Peli', 'Screen Gems, Stage 6 Films, Atomic Monster, TSG Entertainment', '[{"name":"Amelia Eve","character":"Gemma Hall"},{"name":"Island Austin","character":"Maya Hall"},{"name":"Brandon Perea","character":"Nick Mendoza"},{"name":"Lin Shaye","character":"Elise Rainier"},{"name":"Maisie Richardson-Sellers","character":"Clare"},{"name":"Sam Spruell","character":"Cyrus Lam"},{"name":"Joseph Lopez","character":"Lester"},{"name":"Robina Beard","character":"Edna"},{"name":"Susan Gray","character":"Patsy"},{"name":"Laura Gordon","character":"Ingrid Lilith Hall"}]'::jsonb, '13+', 1876),
(1137844, 'Mayday', 'Aksi', 111, 'NR', 'Saat seorang pilot Angkatan Laut AS dalam misi rahasia selama Perang Dingin terjebak di belakang garis musuh, satu-satunya peluang untuk bertahan hidup adalah menjalin aliansi dengan seorang mantan agen KGB eksentrik.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/hVXjX1jLZ1ljFSNGXpjJfbTUOa7.jpg', 'https://image.tmdb.org/t/p/w1280/g7Ccid5kuD7A8hXWlsQiNfwOxaD.jpg', 7.9, 'om5Un9X720M', '2026-09-03', 19.794, 1044, 'tt28014327', 6.9, 9404, 'PG-13', 'Aksi, Komedi', 'Jonathan Goldstein, John Francis Daley', 'Jonathan Goldstein, John Francis Daley', 'Don Granger, David Ellison, Johnny Pariseau, Dana Goldberg', 'Skydance Media, Maximum Effort, GoldDay', '[{"name":"Ryan Reynolds","character":"Troy Kelly"},{"name":"Kenneth Branagh","character":"Nikolai Ustinov"},{"name":"Marcin Dorociński","character":"Alexander Volkov"},{"name":"Мария Бакалова","character":"Anna Ustinov"},{"name":"David Morse","character":"Harold Kelly"},{"name":"Clark Johnson","character":"CDR Keith Hardwick"},{"name":"Wendy Crewson","character":"Assistant Director Karen Meadows"},{"name":"Louis Cancelmi","character":"Maj Pete Sanders"},{"name":"Josh Hamilton","character":"Consul General Dan Hennessy"},{"name":"Alex Mallari Jr.","character":"Danny ''Longshot'' Bowers"}]'::jsonb, '17+', 1240),
