(911916, 'Spider-Man: Beyond the Spider-Verse', 'Animasi', 100, 'NR', 'Hunted by Miguel O''Hara''s Spider Society and betrayed by his friends, Miles finds himself in the darkest corners of the Spider-Verse in search of a way home. Knowing that his family has been not only fractured but endangered by his calling, it''s a race against the clock for Miles to travel across the wildest reaches of time and space to fight for and reunite everything he holds most dear.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/9KAe39xqyZnv9J4W3DRGdQqX82h.jpg', 'https://image.tmdb.org/t/p/w1280/fUcT8bcJD3SZsy84Z9QRP6kOS7v.jpg', null, null, '2027-06-16', 6.881, 0, 'tt16360004', null, null, null, 'Animasi, Aksi, Petualangan, Cerita Fiksi', 'Bob Persichetti, Justin K. Thompson', 'Christopher Miller, Phil Lord, David Callaham', 'Amy Pascal, Christopher Miller, Phil Lord, Avi Arad', 'Columbia Pictures, Sony Pictures Animation, Lord Miller, Pascal Pictures', '[{"name":"Shameik Moore","character":"Miles Morales (voice)"},{"name":"Hailee Steinfeld","character":"Gwen Stacy (voice)"},{"name":"Oscar Isaac","character":"Miguel O''Hara (voice)"},{"name":"Jason Schwartzman","character":"Spot (voice)"},{"name":"Jake Johnson","character":"Peter B. Parker (voice)"},{"name":"Issa Rae","character":"Jessica Drew (voice)"},{"name":"Brian Tyree Henry","character":"Jeff Morales (voice)"},{"name":"Luna Lauren Vélez","character":"Rio Morales (voice)"},{"name":"Daniel Kaluuya","character":"Hobie Brown (voice)"},{"name":"Nicolas Cage","character":"Spider-Man Noir (voice)"}]'::jsonb, null, null),
