(1147572, 'Narnia: The Magician''s Nephew', 'Fantasi', 100, 'NR', 'Two children discover a wood full of pools leading to other worlds. One takes them to a dead city beneath a dying sun, where they wake a queen who exterminated its population and accidentally bring her back to London.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/yrqR0qquy4JOfqZCsFJV7vJoOSh.jpg', 'https://image.tmdb.org/t/p/w1280/3jA1wHHFl3lUcVdGXq4ZsBscHCU.jpg', null, 'gDJ-ini7fF0', '2027-02-10', 9.993, 0, 'tt9077514', null, null, null, 'Fantasi, Petualangan, Keluarga', 'Greta Gerwig', 'C. S. Lewis, Greta Gerwig', 'Amy Pascal, Mark Gordon, Greta Gerwig, Vincent Sieber', 'Pascal Pictures, C.S. Lewis Company, NB/GG Pictures, Midnight Road Entertainment', '[{"name":"Beatrice Campbell","character":"Polly Plummer"},{"name":"David McKenna","character":"Digory Kirke"},{"name":"Daniel Craig","character":"Andrew Ketterley"},{"name":"Carey Mulligan","character":"Mabel Kirke"},{"name":"Emma Mackey","character":"Jadis / The White Witch"},{"name":"Meryl Streep","character":"Aslan (voice)"},{"name":"Ciarán Hinds","character":""},{"name":"Kobna Holdbrook-Smith","character":"Frank"},{"name":"Denise Gough","character":""},{"name":"Susan Wokoma","character":""}]'::jsonb, 'PG', null),
