(1288438, 'Godzilla x Kong: Supernova', 'Cerita Fiksi', 100, 'NR', 'Godzilla and Kong return in an all-new adventure as Earth''s greatest titans face an unthinkable threat from beyond the stars. When a cosmic predator, Apex, sets its sights on Earth, only the combined might of monsters and humanity can avert total extinction.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/gEGDDG6QMDFZ1sV32CGxvzaVPnv.jpg', 'https://image.tmdb.org/t/p/w1280/gLjZC1YGcujC82DF5subtEXWg7F.jpg', null, null, '2027-03-25', 4.548, 0, 'tt32561550', null, null, null, 'Cerita Fiksi, Aksi, Petualangan', 'Grant Sputore', 'David Callaham', 'Mary Parent, Thomas Tull, Alex Garcia, Brian Rogers', 'Legendary Pictures', '[{"name":"Kaitlyn Dever","character":"Jesse Portman"},{"name":"Dan Stevens","character":"Travis \"Trapper\" Beasley"},{"name":"Jack O''Connell","character":"John Portman"},{"name":"Delroy Lindo","character":"Director Conway"},{"name":"Matthew Modine","character":"General Fulton"},{"name":"Alycia Debnam-Carey","character":""},{"name":"Sam Neill","character":""},{"name":"Harriet Joyce","character":"Young Jesse Portman"}]'::jsonb, null, null),
