(1567605, 'Ebenezer', 'Fantasi', 115, 'NR', 'An elderly miser embarks on a supernatural journey after visits from the ghost of his former business partner and the Spirits of Christmas Past, Present, and Yet to Come force him to confront his past and fight for a second chance at happiness.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/6H2N59jJW1hZEzn2ZdrMvJw5vNI.jpg', 'https://image.tmdb.org/t/p/w1280/oveb9ughaDh4GkjmVHvSgFnEzlM.jpg', null, 'l_Ozo1xUgbU', '2026-11-11', 20.351, 0, 'tt38773219', null, null, null, 'Fantasi, Komedi', 'Ti West', 'Nathaniel Halpern, Charles Dickens', 'Emma Watts', 'Paramount Pictures, Domain Entertainment, Wattsco, IN.2 FILM', '[{"name":"Johnny Depp","character":"Ebenezer Scrooge"},{"name":"Rupert Grint","character":"Bob Cratchit"},{"name":"Daisy Ridley","character":"Emily Cratchit"},{"name":"Andrea Riseborough","character":"Ghost of Christmas Past"},{"name":"Tramell Tillman","character":"Ghost of Christmas Present"},{"name":"Ian McKellen","character":"Jacob Marley"},{"name":"Sam Claflin","character":"Fred"},{"name":"Charlie Murphy","character":""},{"name":"Arthur Conti","character":"Young Ebenezer"},{"name":"Alfie Buck","character":"Child Ebenezer"}]'::jsonb, 'PG-13', null),
