(1306322, 'Spaceballs: The New One', 'Komedi', 100, 'NR', 'Forty years after the events of the first Spaceballs, the galaxy is once again under threat. A threat so evil, so unstoppable, so completely lacking in any original ideas, that it has vowed to bring back the past... every last bit of it. With Lone Starr in hiding, Queen Vespa on the throne, and the Schwartz stretched thinner than a franchise releasing TV episodes theatrically, the only hope for the galaxy is Vespa''s undisciplined son, Prince Starburst, and a mysterious Palace advisor named Destiny. Together, they must find Lone Starr, Yogurt, and any other iconic legacy characters fans are demanding before they discover the hard way that, while some threats you can fight, the reboot is not one of them.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/9usPcpMm8GhzkHIXqiklhPrflY3.jpg', 'https://image.tmdb.org/t/p/w1280/6dOmk6RoedeTSelTj2b473xThZH.jpg', null, null, '2027-04-22', 3.529, 0, 'tt32659463', null, null, null, 'Komedi, Cerita Fiksi, Petualangan', 'Josh Greenbaum', 'Dan Hernandez, Josh Gad, Benji Samit', 'Josh Gad, Brian Grazer, Jeb Brody, Mel Brooks', 'Brooksfilms, Imagine Entertainment, Amazon MGM Studios', '[{"name":"Bill Pullman","character":"Lone Starr"},{"name":"Rick Moranis","character":"Dark Helmet"},{"name":"Lewis Pullman","character":"Starburst"},{"name":"Daphne Zuniga","character":"Queen Vespa"},{"name":"Mel Brooks","character":"President Skroob / Yogurt"},{"name":"George Wyner","character":"Colonel Sandurz"},{"name":"Keke Palmer","character":"Destiny"},{"name":"Michael Winslow","character":"Radar Technician"},{"name":"Josh Gad","character":""},{"name":"Anthony Carrigan","character":""}]'::jsonb, null, null),
(1437511, 'How to Rob a Bank', 'Aksi', 122, 'NR', 'A crew of social media-savvy bank robbers broadcasts their daring heists, unaware that their growing viral fame has put them in the crosshairs of a veteran FBI agent and a brilliant software engineer. Despite the unlikely duo closing in, the crime ring pushes past their limits, putting everything on the line for their most ambitious heist yet.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/ifYDZkr2qkHFz87TNVvlxajOxl5.jpg', 'https://image.tmdb.org/t/p/w1280/xghtLO90cQPybH85aw1C3bZ2P3.jpg', null, 'MVvWKh336m4', '2026-11-11', 11.583, 0, 'tt35866986', null, null, 'R', 'Aksi, Kejahatan, Cerita Seru', 'David Leitch', 'Mark Bianculli', 'Kelly McCormick, David Leitch, Brian Grazer, Jeb Brody', '87North Productions, Imagine Entertainment, Amazon MGM Studios', '[{"name":"Nicholas Hoult","character":"Ryan"},{"name":"Zoë Kravitz","character":"Reagan Gardner"},{"name":"Anna Sawai","character":"Emi"},{"name":"Rhenzy Feliz","character":""},{"name":"Pete Davidson","character":"Vince"},{"name":"John C. Reilly","character":"Agent West"},{"name":"Christian Slater","character":"Walton"},{"name":"Tati Gabrielle","character":"Skyler"},{"name":"Young Mazino","character":""},{"name":"Michael Gandolfini","character":""}]'::jsonb, 'R', null),
(1078446, 'Violent Night 2', 'Aksi', 110, 'NR', 'When Santa forgets the true meaning of Christmas, he finds himself in the heart of a lively mall community in desperate need of his help. Sapped of his magic, he’ll need another way to take on the goons threatening the mall, and time is running out. Santa has to rediscover his faith in goodness and call in some last-minute reinforcements from the one person no baddie wants to tangle with: Mrs. Claus.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/7HPvgItDw9NgW3iy4tFRRuGNbuN.jpg', 'https://image.tmdb.org/t/p/w1280/78dChJs7doULSEhIiOvGUcXQRGU.jpg', null, 'FmM2giDwLAE', '2026-12-02', 4.973, 0, 'tt32432428', null, null, null, 'Aksi, Komedi, Fantasi', 'Tommy Wirkola', 'Pat Casey, Josh Miller', 'David Leitch, Kelly McCormick', '87North Productions, Universal Pictures', '[{"name":"David Harbour","character":"Santa Claus"},{"name":"Kristen Bell","character":"Mrs. Claus"},{"name":"Daniela Melchior","character":""},{"name":"Jared Harris","character":""},{"name":"Joe Pantoliano","character":""},{"name":"Maxwell Jacob Friedman","character":""},{"name":"Andrew Bachelor","character":""},{"name":"Maggie Robertson","character":"Duff"},{"name":"David Lawrence Brown","character":""},{"name":"Sarah Luby","character":"Lexi"}]'::jsonb, '17+', null),
(1538497, 'Hexed', 'Petualangan', 103, 'NR', 'An impulsive and unconventional teenage girl named Billie discovers secret magical abilities which, once unleashed, hurtle her into a spectacle-filled journey out of suburbia and into a vast witch realm called Hexe. Forced to team up with her cautious mother, Alice, they uncover family mysteries that could change the world of witches forever.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/3zxrelHqoPJwOP4oj4Wq1cNOUdG.jpg', 'https://image.tmdb.org/t/p/w1280/wZ9Me7OndzgBOEAa8nSBNPu3Sl4.jpg', null, 'IuosV-TRxDU', '2026-11-25', 20.244, 0, 'tt38077943', null, null, null, 'Petualangan, Animasi, Keluarga, Fantasi, Komedi', 'Jason Hand, ฝน วีระสุนทร', 'Dana Ledoux Miller, Jared Bush, Jon Robin Baitz, Josie Trinidad', 'Roy Conli, Yvett Merino', 'Walt Disney Animation Studios', '[{"name":"Hailee Steinfeld","character":"Billie Doe (voice)"},{"name":"Rashida Jones","character":"Alice Doe (voice)"},{"name":"Jodie Foster","character":"Queen Celeste (voice)"},{"name":"Walton Goggins","character":"Beef Roger Crummchuk (voice)"},{"name":"Tracey Ullman","character":"Ms. Quill (voice)"},{"name":"Stephen Fry","character":"Elias Quire (voice)"},{"name":"Henry Winkler","character":"Nigel (voice)"},{"name":"Dan Stevens","character":"Hieronymous (voice)"},{"name":"Brett Gelman","character":"(voice)"},{"name":"Samson Kayo","character":"(voice)"}]'::jsonb, 'PG', null),
(1523140, 'Man of Tomorrow', 'Aksi', 100, 'NR', 'Superman and Lex Luthor find themselves forced to work together—to a certain degree—against a much, much bigger threat when Brainiac sets his sights on Earth.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/ms7BhVucvjxV74HkX8JLmFlQ6p2.jpg', 'https://image.tmdb.org/t/p/w1280/lX2TpAZxdIus6cnMCDBOrs96NBY.jpg', null, null, '2027-07-07', 5.107, 0, 'tt37833661', null, null, null, 'Aksi, Cerita Fiksi, Petualangan', 'James Gunn', 'James Gunn, Joe Shuster, Jerry Siegel', 'Peter Safran, James Gunn', 'DC Studios, Troll Court Entertainment, The Safran Company', '[{"name":"David Corenswet","character":"Superman"},{"name":"Nicholas Hoult","character":"Lex Luthor"},{"name":"Rachel Brosnahan","character":"Lois Lane"},{"name":"Lars Eidinger","character":"Brainiac"},{"name":"Frank Grillo","character":"Rick Flag Sr."},{"name":"Isabela Merced","character":"Hawkgirl"},{"name":"Aaron Pierre","character":"John Stewart"},{"name":"Skyler Gisondo","character":"Jimmy Olsen"},{"name":"Sara Sampaio","character":"Eve Teschmacher"},{"name":"María Gabriela de Faría","character":"The Engineer"}]'::jsonb, null, null),
(1300926, 'The Angry Birds Movie 3', 'Animasi', 96, 'NR', 'Red faces his greatest challenge yet - surviving fatherhood - while saving the world.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/oxaW6X3xohnzdFSBKCrCjRDckMe.jpg', 'https://image.tmdb.org/t/p/w1280/ieAytQ8YcWEZGQpbBy7vHVddwd.jpg', null, 'a9DB_aUMzME', '2026-12-23', 8.342, 0, 'tt32557122', null, null, null, 'Animasi, Komedi, Keluarga', 'John Rice', 'Thurop Van Orman', 'Carla Connor, John Cohen, Dan Chuba, Namit Malhotra', 'Rovio Animation, SEGA of America, Flywheel Media, One Cool Films', '[{"name":"Jason Sudeikis","character":"Red (voice)"},{"name":"Josh Gad","character":"Chuck (voice)"},{"name":"Danny McBride","character":"Bomb (voice)"},{"name":"Rachel Bloom","character":"Silver (voice)"},{"name":"Emma Myers","character":"June (voice)"},{"name":"Walker Scobell","character":"Glider (voice)"},{"name":"Psalm West","character":"Olly (voice)"},{"name":"James Austin Johnson","character":"Fuzzy (voice)"},{"name":"Tim Robinson","character":"Porkchop (voice)"},{"name":"Lily James","character":"(voice)"}]'::jsonb, null, null),
(1286656, 'I Play Rocky', 'Drama', 128, 'NR', 'The electrifying true story about an unknown actor with an unshakable belief that he wasn''t just meant to write Rocky—he was meant to be Rocky Balboa. Told "no" at every turn, Sylvester Stallone bets everything on himself, holding the line on playing the lead against seemingly impossible odds.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/xE5tY3lppZUyG7WKKThsuYHuAHr.jpg', 'https://image.tmdb.org/t/p/w1280/1lnnjBCRLZzKRhQipK5zm61YkPe.jpg', null, 'jq5oCjhQtIc', '2026-11-06', 11.017, 0, 'tt11995650', null, null, null, 'Drama, Sejarah', 'Peter Farrelly', 'Peter Gamble', 'Toby Emmerich, Peter Farrelly, Christian Baha, Michele Weiss', 'Eden Rock Media, Baha Productions, Fireside Films, FilmNation Entertainment', '[{"name":"Anthony Ippolito","character":"Sylvester Stallone"},{"name":"AnnaSophia Robb","character":"Sasha Czack"},{"name":"P.J. Byrne","character":"Irwin Winkler"},{"name":"Toby Kebbell","character":"Robert Chartoff"},{"name":"Jay Duplass","character":"John Avildsen"},{"name":"Tracy Letts","character":"Sandy Maddox"},{"name":"Matt Dillon","character":"Frank Stallone Sr."},{"name":"Stephan James","character":"Carl Weathers"},{"name":"Kiki Seto","character":"Talia Shire"},{"name":"Robert Morgan","character":"Burgess Meredith"}]'::jsonb, 'PG-13', null),
(1497464, 'Gatto', 'Animasi', 100, 'NR', 'After years of maneuvering the canal-ridden, superstitious city of Venice, Italy, a scrappy black cat named Nero begins to question whether he’s lived the right lives. Indebted to Rocco, a ruthless local feline mob boss, Nero finds himself in a quandary and is forced to forge a truly unexpected friendship that may finally lead him to his purpose — unless Venice gets the better of him first.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/bgt6dSrwkJCMqdKWRpN4ZTAd1kL.jpg', 'https://image.tmdb.org/t/p/w1280/etB2OT0nUknOAPZV7EgbEbt6HJh.jpg', null, null, '2027-03-03', 5.997, 0, 'tt26443610', null, null, null, 'Animasi, Komedi, Kejahatan, Keluarga', 'Enrico Casarosa', null, 'Andrea Warren', 'Pixar', '[{"name":"Mark Ruffalo","character":"Nero (voice)"},{"name":"Laurence Fishburne","character":"Rocco (voice)"},{"name":"Enrico Casarosa","character":"Saverio (voice)"}]'::jsonb, null, null),
(1297467, 'The Exorcist: Martyrs', 'Kengerian', 100, 'NR', 'Thirteen years ago, New York City detective Julie Miller ended the terror reign of satanic serial killer Father Sunday. The case made her a hero, and she has thrown herself into her work ever since. Now a new killer scrawls her name in an altar boy''s blood on the walls of a church crypt, dragging her back into the darkness she believed she had buried with him.', '#14532d', '#0f172a', 'https://image.tmdb.org/t/p/w500/nituVk6sSSyOk1Q3SWjs5DmefVU.jpg', 'https://image.tmdb.org/t/p/w1280/e0pOcLgfYVDfeGDB1oEv8JUlc41.jpg', null, 'iIEYfH-jg1Y', '2027-03-10', 7.327, 0, 'tt32492552', null, null, null, 'Kengerian', 'Mike Flanagan', 'Mike Flanagan, William Peter Blatty', 'Mike Flanagan, Jason Blum, David Robinson', 'Red Room Pictures, Morgan Creek Entertainment, Universal Pictures, Blumhouse Atomic Monster', '[{"name":"Scarlett Johansson","character":"Det. Julie Miller"},{"name":"Sasha Calle","character":"Det. Gina Restrepo"},{"name":"Chiwetel Ejiofor","character":"Father William"},{"name":"John Leguizamo","character":"Father Sunday"},{"name":"Laurence Fishburne","character":"Father Nichol"},{"name":"Diane Lane","character":"Mary Miller"},{"name":"Jacobi Jupe","character":"Max Miller"},{"name":"Scoot McNairy","character":"Clay Silver"},{"name":"Rahul Kohli","character":""},{"name":"Gil Bellows","character":"Peter Nicks"}]'::jsonb, null, null),
(1425859, 'Remain', 'Percintaan', 100, 'NR', 'When reclusive architect Tate Gordon moves to small coastal town to complete his latest project, he encounters an alluring young woman who pulls him out of his shell, and into the center of a deadly mystery that hangs over the town.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/5hPNq5h2y8Ux6nPBRMEwZ8npVTp.jpg', 'https://image.tmdb.org/t/p/w1280/v7kL3an4ornAOWOxZucZilfTDbR.jpg', null, null, '2027-02-03', 4.99, 0, 'tt35621542', null, null, null, 'Percintaan, Misteri, Cerita Seru', 'M. Night Shyamalan', 'M. Night Shyamalan, Nicholas Sparks', 'Ashwin Rajan, M. Night Shyamalan, Marc Bienstock, Theresa Park', 'Blinding Edge Pictures', '[{"name":"Jake Gyllenhaal","character":"Tate Gordon"},{"name":"Phoebe Dynevor","character":"Wren"},{"name":"Ashley Walters","character":"Oscar"},{"name":"Julie Hagerty","character":"Louise"},{"name":"Jay O. Sanders","character":"Reece"},{"name":"Tracy Ifeachor","character":"Theresa"},{"name":"Hannah James","character":"Tessa"},{"name":"Caleb Ruminer","character":"Griffin"},{"name":"Kieran Mulcare","character":"Dax"},{"name":"Maria Dizzia","character":"Sydney"}]'::jsonb, null, null),
(1156621, 'Teenage Mutant Ninja Turtles: Mutant Mayhem 2', 'Aksi', 100, 'NR', 'Donnie, Raph, Leo, and Mikey are back for their next adventure with Master Splinter, the Mutants, April, and a new villain they have to face: The Shredder.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/yukp9qq3JmgatfMSGnxdyn6jtRX.jpg', 'https://image.tmdb.org/t/p/w1280/dYsXhu97sNCQbObZjq3awyrdoaf.jpg', null, null, '2027-08-12', 1.998, 0, 'tt31512072', null, null, null, 'Aksi, Animasi, Komedi, Keluarga, Cerita Fiksi', 'Jeff Rowe', null, 'James Weaver, Ramsay McBean, Evan Goldberg, Seth Rogen', 'Point Grey Pictures, Paramount Pictures, Nickelodeon Movies, Domain Entertainment', '[{"name":"Micah Abbey","character":"Donatello (voice)"},{"name":"Nicolas Cantu","character":"Leonardo (voice)"},{"name":"Brady Noon","character":"Raphael (voice)"},{"name":"Shamon Brown Jr.","character":"Michelangelo (voice)"},{"name":"成龍","character":"Splinter (voice)"},{"name":"Ayo Edebiri","character":"April O''Neil (voice)"}]'::jsonb, null, null),
(940009, 'Ray Gunn', 'Animasi', 119, 'NR', 'In Metropia, a gigantic city in an alternate future as seen from 1939, private eye Raymond Gunn is drawn into a case involving aliens, murder and a multimedia star named Venus Nova.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/rpP29aOKpHy1FhX8OZQdUICEs2j.jpg', 'https://image.tmdb.org/t/p/w1280/hhBoWDKmq9u8V2qi0Rtm3XGiydn.jpg', null, 'VL-xjzQFWsY', '2026-12-18', 6.405, 0, 'tt18270542', null, null, null, 'Animasi, Cerita Fiksi, Kejahatan, Misteri', 'Brad Bird', 'Brad Bird, Matthew Robbins', 'Brad Bird, John Lasseter, Lisa Beroud, David Ellison', 'Skydance Animation, Netflix Animation Studios', '[{"name":"Sam Rockwell","character":"Raymond Gunn (voice)"},{"name":"Scarlett Johansson","character":"Venus Nova (voice)"},{"name":"Tom Waits","character":"Eye-Ra (voice)"},{"name":"Matt Berry","character":"Francis ''Slugsy'' Xavier (voice)"},{"name":"Kathryn Hunter","character":"Vanzine Kaluta (voice)"},{"name":"Alan Tudyk","character":"Barry Vogel (voice)"},{"name":"Bobby Cannavale","character":"Arnold Dom (voice)"},{"name":"Michelle Rodriguez","character":"Roz Dexler (voice)"},{"name":"Faruq Tauheed","character":"Lou Blevins (voice)"},{"name":"Michael Chernus","character":"Sam Stelfreeze (voice)"}]'::jsonb, 'PG', null),
(1117898, 'The Cat in the Hat', 'Petualangan', 108, 'NR', 'Assigned his toughest mission yet, the Cat must cheer up siblings Gabby and Sebastian as they adjust to life in a new town. Known for pushing boundaries, this agent of chaos must prove himself or risk losing his magical hat forever.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/tYH4rQZlHtuFSeDS0bsV17khvJC.jpg', 'https://image.tmdb.org/t/p/w1280/9y9o686DsQg0KzPtERzcW7Cf8IE.jpg', 7.7, 'tkZpcypT8Z4', '2026-11-04', 24.898, 3, 'tt2321555', null, null, null, 'Petualangan, Animasi, Komedi, Keluarga, Fantasi', 'Erica Rivinoja, Alessandro Carloni', 'Alessandro Carloni, Erica Rivinoja, Caroline Goddard, Dr. Seuss', 'Daniela Mazzucato', 'DNEG, Dr. Seuss Enterprises, Warner Bros. Pictures Animation, A Stern Talking To', '[{"name":"Bill Hader","character":"The Cat in the Hat (voice)"},{"name":"Xochitl Gomez","character":"Gabby (voice)"},{"name":"Tiago Martinez","character":"Sebastian (voice)"},{"name":"Matt Berry","character":"Waffles the Fish (voice)"},{"name":"Quinta Brunson","character":"Sherrie (voice)"},{"name":"Bowen Yang","character":"Gary (voice)"},{"name":"America Ferrera","character":"Carmen (voice)"},{"name":"Paula Pell","character":"Patty (voice)"},{"name":"Tituss Burgess","character":"The Psychic Narwhal (voice)"},{"name":"Giancarlo Esposito","character":"Mr. Hoogeboom (voice)"}]'::jsonb, 'PG', null),
(1562642, 'Ghost Soldier', 'Aksi', 90, 'NR', 'Henry “Fitz” Fitzgerald has spent years living quietly off the grid, hiding from a past few people know anything about. But when a powerful foreign corporation moves into his hometown to seize his neighbors’ land for a massive payday, Fitz is forced to reveal who he really is: a former Special Forces soldier and advanced weapons developer. Armed with experimental technology, lethal combat skills, and an unwavering code of justice, Fitz wages a one-man war against an enemy that never saw him coming.', '#3b0764', '#0c0a09', 'https://image.tmdb.org/t/p/w500/8Y4oJ5iUs3hgPcDB3SIEmsNYjZk.jpg', 'https://image.tmdb.org/t/p/w1280/ggqvhSdAASrseKuMlzk51sbvbE8.jpg', 7, 'UKaWzMf9Ybc', '2026-11-04', 36.929, 1, 'tt38686316', null, null, null, 'Aksi, Cerita Seru', 'William Eubank', 'Chris Papasadero', 'David Zelon, William Sherak', 'Columbia Pictures, Mandalay Pictures, Project X Entertainment, TSG Entertainment', '[{"name":"Jim Caviezel","character":"Henry ''Fitz'' Fitzgerald"},{"name":"Olivia Thirlby","character":""},{"name":"Beau Knapp","character":""},{"name":"Garret Dillahunt","character":""},{"name":"Shea Whigham","character":""},{"name":"Alexej Manvelov","character":"Ty Bell"},{"name":"Ricky Whittle","character":"McNeil"},{"name":"Olivia Chenery","character":"Sarah Taran"},{"name":"Gunner Wright","character":"Jeff Hamilton"},{"name":"Jaina Lee Ortiz","character":""}]'::jsonb, 'PG-13', null),
(615121, 'The Thomas Crown Affair', 'Kejahatan', 100, 'NR', 'A debonair, adventuresome man believes he has pulled off the perfect multi-million dollar heist, only to match wits with an insurance investigator who will do anything to get her man.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/sT1TQeAy1PdRfPIb6rrM2DB7DB.jpg', 'https://image.tmdb.org/t/p/w1280/4IwoYgyFdBCELwCr9VmEH1u0wwF.jpg', null, 'gnm4HgIAVmU', '2027-03-04', 4.345, 0, 'tt5500064', null, null, null, 'Kejahatan, Percintaan, Cerita Seru', 'Michael B. Jordan', 'Alan Trustman, Drew Pearce, Jason Hall', 'Michael B. Jordan, Elizabeth Raposo, Patrick McCormick, Marc Toberoff', 'Outlier Society, AGBO, Atlas Entertainment, Amazon MGM Studios', '[{"name":"Michael B. Jordan","character":"Thomas Crown"},{"name":"Adria Arjona","character":""},{"name":"Kenneth Branagh","character":""},{"name":"Lily Gladstone","character":""},{"name":"Danai Gurira","character":""},{"name":"Pilou Asbæk","character":""},{"name":"Aiysha Hart","character":""}]'::jsonb, 'PG-13', null),
(621304, 'Children of Blood and Bone', 'Fantasi', 146, 'NR', 'In the world of Orïsha, a young woman goes on a quest to reclaim the magic that was violently stolen from her people. She and her brother ally with the daughter and son of the king to fight back against his brutal rule.', '#831843', '#1e1b4b', 'https://image.tmdb.org/t/p/w500/qxUPu92DF5Bo6jcCDhnMTHFPEEc.jpg', 'https://image.tmdb.org/t/p/w1280/iJHHwaFZumvMLx96apZPNhhIb1A.jpg', null, 'HnWvg90lQt8', '2027-01-13', 3.064, 0, 'tt6779038', null, null, null, 'Fantasi, Petualangan', 'Gina Prince-Bythewood', 'Tomi Adeyemi, Gina Prince-Bythewood', 'Wyck Godfrey, Karen Rosenfelt, Marty Bowen, Matt Jackson', 'Temple Hill Entertainment, Sunswept Entertainment, Paramount Pictures, Domain Entertainment', '[{"name":"Thuso Mbedu","character":"Zelie"},{"name":"Damson Idris","character":"Prince Inan"},{"name":"Amandla Stenberg","character":"Princess Amari"},{"name":"Tosin Cole","character":"Tzain"},{"name":"Viola Davis","character":"Mama Agba"},{"name":"Cynthia Erivo","character":"Admiral Kaea"},{"name":"Idris Elba","character":"Lekan"},{"name":"Lashana Lynch","character":"Jumoke"},{"name":"Chiwetel Ejiofor","character":"King Saran"},{"name":"Regina King","character":"Queen Nehanda"}]'::jsonb, null, null),
(347196, 'Wolf Creek: Legacy', 'Kengerian', 100, 'NR', 'A family of American tourists wander innocently into Taylor''s hunting grounds. When the parents sacrifice themselves to save their children, the kids find themselves alone, lost and hunted in the vast Australian wilderness.', '#7c2d12', '#1c1917', 'https://image.tmdb.org/t/p/w500/sp9EsXNB00frkLzXEkmFsHxIfuD.jpg', 'https://image.tmdb.org/t/p/w1280/sGQXzwy3C1s1CDcsLwea99dyNvI.jpg', null, null, '2027-03-18', 1.784, 0, 'tt4776944', null, null, null, 'Kengerian, Cerita Seru', 'Sean Lahiff', 'Greg McLean, Duncan Samarasinghe', 'Greg McLean, Kristian Moliere, Bianca Martino, Jeremy Bolt', 'Universum International Media Networks, GBC Production, Sky Productions, Emu Creek Pictures', '[{"name":"John Jarratt","character":"Mick Taylor"},{"name":"Ditch Davey","character":""},{"name":"Laura Gordon","character":""},{"name":"Stacy Clausen","character":""},{"name":"Charli Penton","character":""},{"name":"Anni Finsterer","character":""},{"name":"Meg Fraser","character":""},{"name":"Carlos Sanson Jr.","character":""},{"name":"Maria Thattil","character":""},{"name":"Connor Pullinger","character":""}]'::jsonb, null, null),
(1381273, 'Paper Tiger', 'Kejahatan', 115, 'NR', 'Two brothers become entangled in a scheme that turns out to be too good to be true. As they try to navigate their way through the dangerous world of the Russian mafia, family bonds begin to fray with life-altering consequences.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/p6oLmq5KmuWY6uRXBQBL2q30jia.jpg', 'https://image.tmdb.org/t/p/w1280/1VhgzeA0tBbd7GtAw1d2nL3UUBk.jpg', null, 'MLwTyQOhBkw', '2026-11-13', 6.336, 0, 'tt34385689', 7, 556, 'R', 'Kejahatan, Drama, Cerita Seru', 'James Gray', 'James Gray', 'Rodrigo Teixeira, Anthony Katagas, Raffaella Leone, Gary Farkas', 'RT Features, Leone Film Group, Keep Your Head Productions, Vixens', '[{"name":"Miles Teller","character":"Irwin Pearl"},{"name":"Adam Driver","character":"Gary Pearl"},{"name":"Scarlett Johansson","character":"Hester Pearl"},{"name":"Gavin Goudey","character":"Scott Pearl"},{"name":"Roman Engel","character":"Benjamin Pearl"},{"name":"Cindy Katz","character":"Iris Belfer"},{"name":"Yavor Vesselinov","character":"Alexei Yunov"},{"name":"Victor Ptak","character":"Semion Bogoyavich"},{"name":"Dimiter D. Marinov","character":"Daniil"},{"name":"Raphael Corkhill","character":"Vasily"}]'::jsonb, 'R', null),
(1131943, 'Madden', 'Drama', 110, 'NR', 'Chronicles John Madden''s incredible journey alongside best friend and true original Al Davis—from a Super Bowl-winning partnership with the Raiders, to becoming football’s most recognizable voice, to building the worldwide Madden NFL video game.', '#1e3a8a', '#0f172a', 'https://image.tmdb.org/t/p/w500/bRa83oPFFPqaAF3wrpVWPqqfFel.jpg', 'https://image.tmdb.org/t/p/w1280/iNKyRudHcd2oXV5eaWE0LbixkX3.jpg', null, 'xzh7HzLXXpk', '2026-11-11', 6.949, 0, 'tt24818230', null, null, null, 'Drama, Sejarah', 'David O. Russell', 'David O. Russell, Cambron Clark', 'Jason Blumenthal, Steve Tisch, Jonathan Shukat, Todd Black', 'Escape Artists, SMAC Entertainment, Skydance Sports, Amazon MGM Studios', '[{"name":"Nicolas Cage","character":"John Madden"},{"name":"Christian Bale","character":"Al Davis"},{"name":"John Mulaney","character":"Trip Hawkins"},{"name":"Kathryn Hahn","character":"Virginia Madden"},{"name":"Sienna Miller","character":"Carol Davis"},{"name":"Shane Gillis","character":""},{"name":"Sergio Duque","character":""},{"name":"David Lengel","character":"Trainer Tony"},{"name":"Shawn Alexander Thompson","character":"Neighbor"},{"name":"Hasani Vibez Comer","character":"Football Player"}]'::jsonb, 'R', null)
on conflict (tmdb_id) do update set
  title = excluded.title,
  genre = excluded.genre,
  duration_min = excluded.duration_min,
  synopsis = excluded.synopsis,
  poster_url = excluded.poster_url,
  backdrop_url = excluded.backdrop_url,
  vote_average = excluded.vote_average,
  trailer_key = excluded.trailer_key,
  release_date = excluded.release_date,
  popularity = excluded.popularity,
  vote_count = excluded.vote_count,
  -- data IMDb tidak ditimpa dengan kosong kalau kali ini OMDb tidak dipakai
  imdb_id = coalesce(excluded.imdb_id, movies.imdb_id),
  imdb_rating = coalesce(excluded.imdb_rating, movies.imdb_rating),
  imdb_votes = coalesce(excluded.imdb_votes, movies.imdb_votes),
  age_rated = coalesce(excluded.age_rated, movies.age_rated),
  genres = coalesce(excluded.genres, movies.genres),
  director = coalesce(excluded.director, movies.director),
  writers = coalesce(excluded.writers, movies.writers),
  producers = coalesce(excluded.producers, movies.producers),
  production = coalesce(excluded.production, movies.production),
  cast_members = coalesce(excluded.cast_members, movies.cast_members),
  certification = coalesce(excluded.certification, movies.certification),
  watchers = excluded.watchers;

-- Jadwal 7 hari ke depan di semua bioskop.
-- Fungsi ini dibuat oleh supabase-cinema-auth.sql, jadi file itu harus dijalankan lebih dulu.
select refresh_showtimes(7) as jadwal_baru_dibuat;
